('cin148', ARRAY['secondary_prep'], 'sec_cs', 'الخوارزميات', 'ما الذي يمثله المعين في المخطط الانسيابي؟', '["اختبارا أو قرارا","بداية الخوارزمية","نهاية الخوارزمية","عملية حسابية فقط"]'::jsonb, 'اختبارا أو قرارا', 'المعين لاختبار شرط.'),
