('cpe137', ARRAY['secondary_prep'], 'sec_pe', 'الثقافة الرياضية', 'من أول مغربية وعربية أحرزت ميدالية ذهبية أولمبية؟', '["نوال المتوكل","حسناء بنحسي","سعيد عويطة","هشام الكروج"]'::jsonb, 'نوال المتوكل', 'أحرزت ذهبية 400 م حواجز في أولمبياد لوس أنجلوس 1984.'),
