('cpe139', ARRAY['secondary_prep'], 'sec_pe', 'الثقافة الرياضية', 'مع أي دولتين ينظم المغرب كأس العالم 2030؟', '["إسبانيا والبرتغال","فرنسا وإيطاليا","مصر وتونس","البرازيل والأرجنتين"]'::jsonb, 'إسبانيا والبرتغال', 'ملف مشترك ثلاثي.'),
