('cpe142', ARRAY['secondary_prep'], 'sec_pe', 'القانون والتحكيم', 'ماذا يسمى الاحتكاك غير القانوني بالخصم في كرة السلة؟', '["خطأ شخصي","خطأ فني فقط","ضربة جزاء","ركلة حرة"]'::jsonb, 'خطأ شخصي', 'يحتسب خطأ شخصيا.'),
('cpe143', ARRAY['secondary_prep'], 'sec_pe', 'الإسعاف', 'كيف يوضع مغمى عليه تنفسه عادي؟', '["على الظهر مع رفع الرجلين","واقفا","جالسا","يسقى ماء فورا"]'::jsonb, 'على الظهر مع رفع الرجلين', 'لتحسين تدفق الدم إلى الرأس.'),
('cpe144', ARRAY['secondary_prep'], 'sec_pe', 'الصحة', 'ما أهمية الاستحمام بعد المجهود الرياضي؟', '["النظافة وإزالة العرق","زيادة التعب","تجنب الراحة","التخلص من الإحماء"]'::jsonb, 'النظافة وإزالة العرق', 'النظافة جزء من الصحة الرياضية.'),
('cpe145', ARRAY['secondary_prep'], 'sec_pe', 'الصحة', 'ما معنى مؤشر كتلة الجسم؟', '["الوزن بالكيلوغرام على مربع الطول بالمتر","الطول على الوزن","الوزن مضروبا في الطول","عدد السعرات اليومية"]'::jsonb, 'الوزن بالكيلوغرام على مربع الطول بالمتر', 'IMC = P / T².'),
('cpe146', ARRAY['secondary_prep'], 'sec_pe', 'بنية الحصة', 'كم تدوم مرحلة الإحماء تقريبا؟', '["10 إلى 15 دقيقة","من 45 إلى 60 دقيقة","دقيقة واحدة","ساعتان"]'::jsonb, '10 إلى 15 دقيقة', 'مدة معتدلة تهيئ الجسم.'),
('cpe147', ARRAY['secondary_prep'], 'sec_pe', 'بنية الحصة', 'في أي مرحلة من الحصة تنجز تمارين التمطيط الهادئة غالبا؟', '["العودة إلى الهدوء","قبل الإحماء","أثناء السباق","عند التقويم فقط"]'::jsonb, 'العودة إلى الهدوء', 'تساعد على الاسترخاء واستعادة المرونة.'),
('cpe148', ARRAY['secondary_prep'], 'sec_pe', 'مبادئ التدريب', 'ما مبدأ التدرج في التدريب؟', '["زيادة الحمل تدريجيا","البدء بأقصى حمل","تثبيت الحمل دائما","التخلي عن الإحماء"]'::jsonb, 'زيادة الحمل تدريجيا', 'يتجنب الإصابات ويحسن التكيف.'),
('cpe149', ARRAY['secondary_prep'], 'sec_pe', 'القيم', 'ما معنى اللعب النظيف؟', '["احترام الخصم والحكم والقانون","الفوز بأي وسيلة","تجاهل الحكم","إخفاء الأخطاء"]'::jsonb, 'احترام الخصم والحكم والقانون', 'قيمة تربوية أساسية في الرياضة.'),
('cpe150', ARRAY['secondary_prep'], 'sec_pe', 'ألعاب القوى', 'كم عدد العدائين في فريق التتابع 4 × 100 م؟', '["4","2","5","6"]'::jsonb, '4', 'أربعة عدائين يتناوبون على حمل العصا.'),
('cpe151', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والتردد القلبي', 'الصيغة التقريبية الشائعة لحساب التردد القلبي الأقصى النظري (FCM : Fréquence Cardiaque Maximale) لشخص هي:', '["FCM = 220 - العمر بالسنوات (للذكور)","FCM = 150 + العمر بالسنوات","FCM = 100 ثابتة للجميع","FCM = وزن الجسم مقسوماً على 2"]'::jsonb, 'FCM = 220 - العمر بالسنوات (للذكور)', 'معادلة أستيمو واستفيل كلاسيكية لتقدير النبض الأقصى: FCM = 220 - Âge (و 226 - Âge للإناث).'),
('cpe152', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا وحمض اللاكتيك', 'التراكم المفرط لأيونات الهيدروجين H⁺ وحمض اللاكتيك في العضلة أثناء المجهود اللاهوائي الكثيف يسبب:', '["انخفاض الـ pH العضلي (الحماض) وتثبيط الأنزيمات الحركية وشعوراً حاداً بالإعياء والتعب العضلي","تضاعف القوة العضلية تلقائياً للأبد","زيادة فورية في سعة الرئتين","انخفاض دقات القلب إلى الصفر"]'::jsonb, 'انخفاض الـ pH العضلي (الحماض) وتثبيط الأنزيمات الحركية وشعوراً حاداً بالإعياء والتعب العضلي', 'الحماض العضلي (Acidose) يعيق عمل جسور الأكتين-ميوزين ويثبط أنزيمات إنتاج الطاقة مما يفرض التوقف أو خفض الشدة.'),
('cpe153', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية والتعلم الحركي', 'المراحل الثلاث لتعلم المهارة الحركية حسب نموذج فيتس وبوسنر (Fitts & Posner) هي:', '["المرحلة المعرفية (Cognitive)، المرحلة الترابطية (Associative)، والمرحلة الذاتية التلقائية (Autonome)","مرحلة الخوف، مرحلة الشجاعة، ومرحلة الفوز","مرحلة الجري، مرحلة الوثب، ومرحلة الرمي","مرحلة المبتدئ، مرحلة المتوسط، ومرحلة المحترف فقط"]'::jsonb, 'المرحلة المعرفية (Cognitive)، المرحلة الترابطية (Associative)، والمرحلة الذاتية التلقائية (Autonome)', 'يتدرج التعلم الحركي من الفهم العقلي المصحوب بأخطاء، إلى ضبط التنسيق، وصولاً إلى الأداء الآلي السلس بدقة عالية.'),
('cpe154', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك EPS والتغذية الراجعة', 'ما هي «التغذية الراجعة الخارجية» (Feedback pédagogique) التي يقدمها مدرس التربية البدنية للمتعلم؟', '["معلومات توجيهية يقدمها المدرس للمتعلم حول نتيجة حركته أو مسارها لتحسين الإنجاز الحركي وتصحيح الخطأ","تقديم وجبة غذائية في نهاية الحصة","منح نقطة عددية في السبورة","إعادة تشغيل الموسيقى في القاعة"]'::jsonb, 'معلومات توجيهية يقدمها المدرس للمتعلم حول نتيجة حركته أو مسارها لتحسين الإنجاز الحركي وتصحيح الخطأ', 'التغذية الراجعة (Feedback de performance) ضرورية لربط الإحساس الداخلي بالتنفيذ الخارجي السليم.'),
('cpe155', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والمفاهيم التكتيكية', 'في الرياضات الجماعية بالكرة، المبدأ التكتيكي الأساسي في المرحلة الدفاعية هو:', '["حماية المرمى/السلة، وتأخير تقدم الخصم، واسترجاع الكرة أو منع التصويب","الانتشار في أقصى مساحة ممكنة في الملعب","توجيه الكرة نحو الأمام باليدين فقط","ترك الخصم يرمي بدون مضايقة"]'::jsonb, 'حماية المرمى/السلة، وتأخير تقدم الخصم، واسترجاع الكرة أو منع التصويب', 'الدفاع في الرياضات الجماعية يهدف بالأساس إلى حماية الهدف والضغط لافتكاك الكرة أو إجبار الخصم على ارتكاب خطأ.'),
('cpe156', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والمفاهيم التكتيكية', 'في الهجوم في الرياضات الجماعية، ما هو دور «التحرك بدون كرة» وخلق المساحات (Appel de balle)؟', '["التخلص من الرقابة وتوفير خيارات تمرير سانحة لحامل الكرة والمباغتة في العمق","الوقوف خلف المدافع مباشرة","تشتيت انتباه الحكم","الخروج من حدود الملعب للاستراحة"]'::jsonb, 'التخلص من الرقابة وتوفير خيارات تمرير سانحة لحامل الكرة والمباغتة في العمق', 'التحرك الذكي دون كرة يخلق خطوط تمرير ويخلخل الدفاع المنظم لتسهيل الوصول لمنطقة التهديف.'),
('cpe157', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى والرمي', 'في مسابقة رمي الجلة (Lancer du poids)، ما هو الشرط الميكانيكي لتحقيق أكبر مدى لرمي المقذوف؟', '["سرعة الانطلاق البدئية القصوى، وزاوية انطلاق تقارب 40 إلى 42 درجة، وارتفاع نقطة القذف","الرمي بزاوية عمودية 90 درجة","الرمي بيد واحدة بالركض الخلفي فقط","الرمي بثبات الرأس نحو الأرض"]'::jsonb, 'سرعة الانطلاق البدئية القصوى، وزاوية انطلاق تقارب 40 إلى 42 درجة، وارتفاع نقطة القذف', 'الميكانيكا الحيوية للرمي تثبت أن سرعة الانطلاق هي المتغير الحاسم، والزاوية المثلى أقل بقليل من 45° لوجود ارتفاع القذف.'),
('cpe158', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى وسباقات التناوب', 'في سباق التناوب 4 × 100 متر، ما هي «منطقة التسليم والتسلم» (Zone de transmission)؟', '["منطقة قانونية محددة بمسافة 20 متراً أو 30 متراً يجب أن يتم داخلها تبادل عصا التناوب بدقة","مكان انطلاق جميع المتسابقين في البداية","خط الوصول النهائي فقط","المنصة التي يقف فيها حكام السباق"]'::jsonb, 'منطقة قانونية محددة بمسافة 20 متراً أو 30 متراً يجب أن يتم داخلها تبادل عصا التناوب بدقة', 'خروج تبادل العصا عن حدود المنطقة المحددة قانونياً يؤدي إلى الإقصاء الفوري للفريق.'),
('cpe159', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الجمباز والتنظيم الحركي', 'في الجمباز، ما هي عناصر الربط الحركي الأساسية في تركيبة حركية إجبارية على بساط الحركات الأرضية؟', '["التوازن، الدوران، الطيران/القفز، والوضعية الساكنة مع الثبات والانسيابية","الجري السريع بدون توقف","رمي الكرات نحو الأعلى","حركات الرقص الشعبي فقط"]'::jsonb, 'التوازن، الدوران، الطيران/القفز، والوضعية الساكنة مع الثبات والانسيابية', 'بناء الجملة الحركية الجمبازية يتطلب التنوع بين مهارات الدوران (دحرجات)، والتوازن (الميزان)، والقفز والثبات النهائي.'),
('cpe160', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والصفات البدنية', 'ما هي «الصفات البدنية الأساسية الخمس» في الإعداد البدني الرياضي؟', '["القوة العضلية، والسرعة، والتحمل (المطاولة)، والمرونة (اللدونة)، والرشاقة/التوافق الحركي","الطول، والوزن، ولون العينين، ومحيط الرأس، والسمع","التركيز، والذاكرة، والتحدث، والكتابة، والحساب","المشي، والجلوس، والنوم، والأكل، والراحة"]'::jsonb, 'القوة العضلية، والسرعة، والتحمل (المطاولة)، والمرونة (اللدونة)، والرشاقة/التوافق الحركي', 'هذه الصفات الخمس تشكل الأعمدة الفسيولوجية لتطوير الأداء الحركي واللياقة البدنية الشاملة.'),
('cpe161', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك وبيداغوجيا الفارقية في EPS', 'كيف يطبق مدرس التربية البدنية «البيداغوجيا الفارقية» داخل القسم الرياضي؟', '["بتنويع الوضعيات التعلمية وشروط الإنجاز (مسافات، أوزان، أدوار، قواعد) لتلائم الفروق الفردية ومستويات التلاميذ المختلفة","بتدريب التلميذ المتفوق وإهمال الضعاف كلياً","بتطبيق نفس التمرين القاسي على الجميع بنفس المعيار الصارم","بإعفاء الإناث من ممارسة النشاط الرياضي"]'::jsonb, 'بتنويع الوضعيات التعلمية وشروط الإنجاز (مسافات، أوزان، أدوار، قواعد) لتلائم الفروق الفردية ومستويات التلاميذ المختلفة', 'الفارقية تقتضي ضبط المتغيرات الديداكتيكية حتى يجد كل متعلم تحدياً محفزاً يتناسب مع إمكاناته الحركية الفعلية.'),
('cpe162', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'التربية على الصحة والحياة المتوازنة', 'الهدف الصحي للتربية البدنية والرياضية يتجاوز مجرد الحصة المدرسية إلى:', '["ترسيخ عادة الممارسة الرياضية المنتظمة مدى الحياة والوقاية من السمنة وأمراض العصر الخاملة وتحقيق الرفاه البدني والنفسي","الحصول على نقطة جيدة في الامتحان فقط","التنافس العنيف مع الأقران","استهلاك المكملات الغذائية الاصطناعية المجهولة"]'::jsonb, 'ترسيخ عادة الممارسة الرياضية المنتظمة مدى الحياة والوقاية من السمنة وأمراض العصر الخاملة وتحقيق الرفاه البدني والنفسي', 'تعتبر التربية على الصحة والنشاط البدني المستدام ركناً أساسياً في التوجهات الحديثة للتربية البدنية.'),
('cpe163', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الروح الرياضية والتحكيم', 'إدماج مهام «التحكيم والتسجيل والملاحظة» بين التلاميذ في حصص التربية البدنية يهدف إلى:', '["تنمية الاستقلالية والمسؤولية الأخلاقية وفهم القوانين والإنصاف وتفادي النزاعات السلوكية","تعويض غياب الأستاذ داخل الملعب","إراحة التلاميذ الكسالى من الجري","التقاط صور تذكارية للمباريات"]'::jsonb, 'تنمية الاستقلالية والمسؤولية الأخلاقية وفهم القوانين والإنصاف وتفادي النزاعات السلوكية', 'تبادل الأدوار (لاعب، حكم، مسجل، ملاحظ) ينمي المواطنة الرياضية والوعي الشامل بالنشاط وقوانينه.'),
('cpe164', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والتقلص العضلي', 'التقلص العضلي «متساوي القياس» (Contraction isométrique) هو تقلص يحدث فيه:', '["تولد قوة عضلية وتوتر داخلي مع بقاء طول العضلة ثابتاً دون تحريك للمفصل","قصر في طول العضلة مع حركة المفاصل","تمدد في طول العضلة مع مقاومة ثقل خارجي","ارتخاء تام للألياف العضلية"]'::jsonb, 'تولد قوة عضلية وتوتر داخلي مع بقاء طول العضلة ثابتاً دون تحريك للمفصل', 'في الانقباض الإيزومتري (كتمارين الثبات Planche)، يتولد الشد العضلي دون إحداث حركة مفصلية أو تغير في الطول.'),
('cpe165', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'التشريح الميكانيكي والمفاصل', 'المفصل الزلالي (Synovial) يتميز بوجود سائل زلالي وغضروف مفصلي يهدفان أساساً إلى:', '["تقليل الاحتكاك بين نهايات العظام وامتصاص الصدمات أثناء الحركة الحركية","توليد الطاقة الكهربائية داخل الأطراف","ربط الجلد بالعضلات مباشرة","تخزين كميات هائلة من الدهون"]'::jsonb, 'تقليل الاحتكاك بين نهايات العظام وامتصاص الصدمات أثناء الحركة الحركية', 'الغضروف المفصلي والسائل الزليلي يوفران تزييتاً وانزلاقاً ميكانيكياً سلساً للأسطح المفصلية.'),
('cpe166', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضة المدرسية والجمعية الرياضية', 'الجمعية الرياضية المدرسية (Association Sportive Scolaire) بالمؤسسات التعليمية المغربية تمثل الإطار القانوني لـ:', '["تأطير أنشطة الرياضة المدرسية التنافسية والترفيهية خارج أوقات الدراسة وتنمية مواهب التلاميذ وتمثيل المؤسسة في البطولات","بيع المعدات الرياضية للتلاميذ بالتقسيط","تنظيم امتحانات الباكالوريا النظرية فقط","استخلاص رسوم التسجيل السنوي للدروس الخصوصية"]'::jsonb, 'تأطير أنشطة الرياضة المدرسية التنافسية والترفيهية خارج أوقات الدراسة وتنمية مواهب التلاميذ وتمثيل المؤسسة في البطولات', 'الجمعية الرياضية المدرسية تمكن التلاميذ المنخرطين من ممارسة رياضتهم المفضلة في البطولات المحلية والإقليمية والوطنية.'),
('cpe167', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى وتدريب التحمل', 'طريقة التدريب «المستمر بالسرعة الثابتة» في ألعاب القوى تهدف بالأساس إلى تطوير:', '["القدرة الهوائية والتحمل القلبي الوعائي (Endurance aérobie)","السرعة الانفجارية القصوى في 30 متراً","المرونة العضلية للكتفين فقط","القوة القصوى لرفع الأثقال"]'::jsonb, 'القدرة الهوائية والتحمل القلبي الوعائي (Endurance aérobie)', 'الجري المستمر المعتدل (Continuous training) يبني قاعدة التحمل الهوائي ويحسن كفاءة القلب وشبكة الشعيرات الدموية.'),
('cpe168', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى والتدريب الفتري', 'طريقة التدريب «الفتري المتقطع» (Entraînement par intervalles / Fractionné) تقوم على:', '["التناوب المنتظم بين فترات مجهود بدني كثيف وفترات استرجاع واستراحة إيجابية نشيطة ومحددة","الجري دون توقف حتى الإغماء","ممارسة النشاط الرياضي مرة واحدة في الشهر","الجلوس التام بعد كل دقيقة جري"]'::jsonb, 'التناوب المنتظم بين فترات مجهود بدني كثيف وفترات استرجاع واستراحة إيجابية نشيطة ومحددة', 'التدريب المتقطع (Interval training) وسيلة فعالة لرفع الـ VMA و VO2 max بتحفيز القلب بشدة مع فترات راحة محسوبة.'),
('cpe169', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'كرة القدم وقانون اللعبة', 'في كرة القدم، متى يكون اللاعب في موضع «تسلل» (Hors-jeu / Offside)؟', '["إذا كان أقرب إلى خط مرمى منافسه من الكرة ومن آخر ثاني مدافع لحظة تمرير الكرة إليه من زميله","إذا سجل هدفاً برأسه من ضربة ركنية","إذا استقبل الكرة مباشرة من رمية تماس","إذا كان متواجداً في نصف ملعبه الخاص"]'::jsonb, 'إذا كان أقرب إلى خط مرمى منافسه من الكرة ومن آخر ثاني مدافع لحظة تمرير الكرة إليه من زميله', 'موضع التسلل يتحدد بلحظة خروج الكرة من قدم الزميل، ولا تسلل في نصف ملعب اللاعب ولا من رمية تماس أو ركنية أو ضربة مرمى.'),
('cpe170', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'كرة القدم وقانون اللعبة', 'ما هو القرار التحكيمي الصحيح عند لمس المدافع للكرة بيده عمداً داخل منطقة الجزاء الخاصة بفريقه؟', '["احتساب ركلة جزاء (Penalty) ضد فريقه مع إمكانية إنذاره بحسب الحالة","احتساب ركلة ركنية للخصم","إسقاط الكرة بين قائد الفريقين","إلغاء المباراة وإعادتها"]'::jsonb, 'احتساب ركلة جزاء (Penalty) ضد فريقه مع إمكانية إنذاره بحسب الحالة', 'لمس اليد المتعمد داخل منطقة الجزاء يعاقب عليه بضربة جزاء من مسافة 11 متراً لصالح الفريق المهاجم.'),
('cpe171', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية والمشروع البيداغوجي', 'في ديداكتيك EPS، «المشروع البيداغوجي للمادة» (Projet Pédagogique d''EPS) يمثل:', '["وثيقة مرجعية تشخص واقع المؤسسة وتحدد الأهداف والاختيارات الديداكتيكية وبرمجة الأنشطة والتقويم المنسجم مع المنهاج","طلب خطي موجه للإدارة لشراء كرات جديدة","سجل يومي لتسجيل درجات الحرارة","قائمة طعام المطعم المدرسي"]'::jsonb, 'وثيقة مرجعية تشخص واقع المؤسسة وتحدد الأهداف والاختيارات الديداكتيكية وبرمجة الأنشطة والتقويم المنسجم مع المنهاج', 'المشروع البيداغوجي يترجم التوجيهات الرسمية إلى خطة عمل ملائمة لخصوصيات وبنيات وتلاميذ المؤسسة التعليمية.'),
('cpe172', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية وتدبير الفضاء', 'التدبير الفعال للملعب وفضاء ممارسة التربية البدنية يقتضي من المدرس التموضع في مكان يسمح بـ:', '["رؤية شاملة ومباشرة لجميع المتعلمين والمجموعات في آن واحد وضمان شروط السلامة والتوجيه","الجلوس داخل المكتب الإداري البعيد","الوقوف في الزاوية الميتة من الملعب","الاندماج كلاعب مع أحد الفرق ونسيان باقي المجموعات"]'::jsonb, 'رؤية شاملة ومباشرة لجميع المتعلمين والمجموعات في آن واحد وضمان شروط السلامة والتوجيه', 'تموضع الأستاذ المحيطي (Placement périphérique) يضمن المراقبة البصرية الشاملة والتدخل السريع للتصحيح والسلامة.'),
('cpe173', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الجمباز والإسناد والمساعدة', 'ماذا يقصد بـ «المساعدة والمرافقة الحركية» (Parade et aide) في تدريس الجمباز التربوي؟', '["تدخل يدوي آمن من الأستاذ أو الزميل لمساعدة المتعلم على إنجاز الحركة الحركية وتأمينه من السقوط الخاطئ","التصفيق والتشجيع بالهتاف فقط","تصوير الحركة بالفيديو البطيء فقط","تقييم الحركة بإعطاء نقطة فورية"]'::jsonb, 'تدخل يدوي آمن من الأستاذ أو الزميل لمساعدة المتعلم على إنجاز الحركة الحركية وتأمينه من السقوط الخاطئ', 'المرافقة (Parade) عنصر أمان نفسي وجسدي يساعد التلميذ على التغلب على الخوف الحركي وبناء الثقة في إتقان المهارة.'),
('cpe174', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'التربية البدنية الدامجة', 'في إطار «التربية الدامجة»، كيف يتعامل مدرس التربية البدنية مع تلميذ في وضعية إعاقة حركية خفيفة؟', '["تكييف الوضعيات والأدوار والقواعد والأدوات ليشارك بفعالية وأمان مع أقرانه وتحقيق أهداف تعلمية ملائمة له","إعفاؤه التام وحرمانه من النزول للملعب طيلة السنة","إجباره على أداء نفس الحركات الصعبة دون أي تكييف","تكليفه بحراسة ملابس زملائه فقط"]'::jsonb, 'تكييف الوضعيات والأدوار والقواعد والأدوات ليشارك بفعالية وأمان مع أقرانه وتحقيق أهداف تعلمية ملائمة له', 'التربية الدامجة في EPS تضمن حق كل متعلم في النشاط البدني عبر التكييف الديداكتيكي للمهام والقواعد.'),
('cpe175', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والترطيب', 'أثناء ممارسة النشاط البدني المكثف، ما هو السلوك الصحي السليم لتعويض السوائل المفقودة بالعرق؟', '["شرب الماء بكميات معتدلة وبجرعات متكررة قبل وأثناء وبعد المجهود البدني للوقاية من التجفاف","الامتناع التام عن شرب أي قطرة ماء حتى العودة للمنزل","تناول المشروبات الغازية السكرية بكثرة أثناء الجري","شرب لترين من الماء دفعة واحدة أثناء الجري السريع"]'::jsonb, 'شرب الماء بكميات معتدلة وبجرعات متكررة قبل وأثناء وبعد المجهود البدني للوقاية من التجفاف', 'الترطيب المنتظم يحافظ على التوازن المائي والحراري ويمنع انخفاض الكفاءة البدنية والتشنجات العضلية الحادة.'),
('cpe176', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية ومفهوم الكفاية', 'الكفاية الختامية في التربية البدنية والرياضية تقاس بقدرة المتعلم على:', '["تعبئة ودمج موارده المعرفية والبدنية والمهارية والوجدانية لمواجهة وحل وضعيات-مشكلات حركية مركبة","حفظ المصطلحات الفرنسية في كراسته فقط","الركض أسرع من الأستاذ في سباق المسافات الطويلة","شراء الملابس الرياضية ذات العلامات التجارية العالمية"]'::jsonb, 'تعبئة ودمج موارده المعرفية والبدنية والمهارية والوجدانية لمواجهة وحل وضعيات-مشكلات حركية مركبة', 'الكفاية الحركية تتجاوز المهارة الآلية المعزولة إلى القدرة على التكيف واتخاذ القرار الصائب داخل السياق الرياضي.'),
('cpe177', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك EPS وصياغة المعايير', 'في شبكة الملاحظة والتقويم في EPS، ما هو الفرق بين «معايير الإنجاز» (Critères de réalisation) و«معايير النجاح» (Critères de réussite)؟', '["معايير الإنجاز تصف كيفية وطريقة الأداء الحركي الصحيح، بينما معايير النجاح تصف النتيجة القابلة للقياس (كالهدف أو الوقت)","معايير الإنجاز للملابس ومعايير النجاح للنقط فقط","لا يوجد فرق فكلاهما نفس الشيء بالضبط","معايير النجاح يحددها التلاميذ ومعايير الإنجاز يحددها المدير"]'::jsonb, 'معايير الإنجاز تصف كيفية وطريقة الأداء الحركي الصحيح، بينما معايير النجاح تصف النتيجة القابلة للقياس (كالهدف أو الوقت)', 'معايير الإنجاز تجيب عن: «كيف أفعل لأنجح؟»، ومعايير النجاح تجيب عن: «متى أعلم أنني نجحت؟».'),
('cpe178', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الإصابات الرياضية والإسعاف الأولي', 'البروتوكول الإسعافي الأولي الموصى به فوراً عند حدوث التواء مفصلي حاد (Entorse) هو بروتوكول RICE المكون من:', '["الراحة (Rest)، وضع الثلج (Ice)، الضغط برباط مرن (Compression)، ورفع الطرف المصاب (Elevation)","تدليك المفصل بقوة فورا والركض عليه ثانية","استعمال الماء الساخن المغلي على المفصل","تجاهل الألم ومواصلة اللعب"]'::jsonb, 'الراحة (Rest)، وضع الثلج (Ice)، الضغط برباط مرن (Compression)، ورفع الطرف المصاب (Elevation)', 'بروتوكول RICE يحد من النزيف الداخلي والانتفاخ والالتهاب فور وقوع الإصابة المفصلية أو العضلية.'),
('cpe179', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والتكيف مع التداريب', 'مبدأ «التعويض الفائق» (Surcompensation) في نظرية التدريب الرياضي يعني:', '["استعادة الجسم لطاقته بعد المجهود وتجاوزه لمستوى لياقته البدئية ليصبح أكثر قوة وتحملاً مما كان عليه قبل التدريب","فقدان الجسم لجميع مكتسباته العضلية بعد الراحة","الشعور بألم دائم في العضلات دون أي تحسن","تراجع مستوى اللياقة تدريجياً مع التدريب المستمر"]'::jsonb, 'استعادة الجسم لطاقته بعد المجهود وتجاوزه لمستوى لياقته البدئية ليصبح أكثر قوة وتحملاً مما كان عليه قبل التدريب', 'التعويض الفائق أساس التكيف البيولوجي: التعب بالجهد ← استرجاع وتغذية راجعة ← ارتفاع مستوى القدرة البدنية.'),
('cpe180', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'القيم الأولمبية والتربية الرياضية', 'القيم الأولمبية الكلاسيكية الثلاث التي تحرص التربية البدنية على غرسها في الناشئة هي:', '["التميز (Excellence)، الصداقة (Amitié)، والاحترام المتبادل (Respect)","الفوز بأي ثمن ولو بالغش، الشهرة، وجني الأموال","القوة الجسدية، التعصب، وإقصاء المنافس","السفر الدائم، والمكافآت، والمظاهر"]'::jsonb, 'التميز (Excellence)، الصداقة (Amitié)، والاحترام المتبادل (Respect)', 'الميثاق الأولمبي يؤكد أن جوهر الرياضة بناء الشخصية الفاضلة وقبول الآخر واحترام القواعد والنزاهة الإنسانية.'),
('cpe181', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الجمباز والحركات الإيقاعية', 'ما هو العنصر المميز للجمباز الإيقاعي (GRS) مقارنة بالجمباز الفني الكلاسيكي؟', '["توظيف الأداة اليدوية (الشريط، الكرة، الطوق، الصولجان، الحبل) والتناغم مع الإيقاع الموسيقي والرقص الحركي","القفز من طائرة مروحية","استخدام الأثقال والأجهزة الحديدية الثقيلة","تسلق الحبال المعلقة في الهواء الطلق"]'::jsonb, 'توظيف الأداة اليدوية (الشريط، الكرة، الطوق، الصولجان، الحبل) والتناغم مع الإيقاع الموسيقي والرقص الحركي', 'الجمباز الإيقاعي يجمع بين التعبير الفني والرشاقة والتحكم البارع في الأدوات الخفيفة بالتناغم مع الموسيقى.'),
('cpe182', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والموقع في الملعب', 'في كرة اليد، منطقة الـ 6 أمتار (Zone de 6 mètres) مخصصة قانونياً لـ:', '["حارس المرمى فقط، ولا يحق لأي لاعب مهاجم أو مدافع لمس أرضيتها أثناء اللعب بالكرة","جميع اللاعبين دون أي قيد","قائد الفريق فقط","المهاجم الهداف فقط"]'::jsonb, 'حارس المرمى فقط، ولا يحق لأي لاعب مهاجم أو مدافع لمس أرضيتها أثناء اللعب بالكرة', 'منطقة المرمى حصرية للحارس، ومخالفة دخولها تعاقب برمي حرة أو رمية 7 أمتار بحسب موقع المدافع أو المهاجم.'),
('cpe183', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والموقع في الملعب', 'في كرة السلة، ما هي المدة الزمنية القصوى المتاحة للفريق الهجومي لتسديد الكرة نحو سلة الخصم ولمس الحلق؟', '["24 ثانية","10 ثوانٍ","45 ثانية","دقيقة كاملة"]'::jsonb, '24 ثانية', 'قانون الـ 24 ثانية يلزم الفريق المهاجم بتصويب الكرة للمس الحلق لضمان دينامية وسرعة اللعبة.'),
('cpe184', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا ونظام الطاقة الهوائي', 'الركيزة الطاقية الأساسية التي يعتمد عليها المسلك الهوائي أثناء الجري لمسافات طويلة تدوم أكثر من 40 دقيقة هي:', '["أكسدة الأحماض الدهنية (الليبيدات) إلى جانب الغلوكوز المتبقي","تفكك البروتينات العضلية فقط","الأملاح المعدنية والفيتامينات فقط","غاز النيتروجين المستنشق"]'::jsonb, 'أكسدة الأحماض الدهنية (الليبيدات) إلى جانب الغلوكوز المتبقي', 'في المجهودات الهوائية الطويلة تزداد مساهمة أكسدة الدهون (Lipolyse) كمصدر طاقة غير محدود تقريباً لتوفير الغليكوجين.'),
('cpe185', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية وعقد الدرس', '«التعاقد الديداكتيكي» في حصة التربية البدنية يتضمن اتفاقاً ضمنياً وصريحاً حول:', '["قواعد العمل، وضوابط السلامة، والالتزام بالزي الرياضي، والانخراط الإيجابي في الأنشطة والتقويم المتبادل","تحديد أسعار الملابس الرياضية","إعفاء التلاميذ من الدراسة في الأيام الممطرة","التنازل عن الامتحانات"]'::jsonb, 'قواعد العمل، وضوابط السلامة، والالتزام بالزي الرياضي، والانخراط الإيجابي في الأنشطة والتقويم المتبادل', 'التعاقد الصفي في EPS يضمن الانضباط وحسن استثمار الوقت والمحافظة على التجهيزات والمشاركة الفعالة.'),
('cpe186', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الأنشطة البدنية في الهواء الطلق', 'رياضة سباق التوجيه (Course d''orientation) تعتمد على تنمية المهارات المزدوجة المتمثلة في:', '["الجري في الفضاء الطبيعي واستعمال الخريطة والبوصلة للعثور على نقاط المراقبة (Balises) بأسرع وقت","تسلق الأشجار العالية فقط","البحث عن الآثار القديمة بدون أي أجهزة","السباحة في الأنهار الجليدية"]'::jsonb, 'الجري في الفضاء الطبيعي واستعمال الخريطة والبوصلة للعثور على نقاط المراقبة (Balises) بأسرع وقت', 'سباق التوجيه يدمج القدرة البدنية للعدو مع الكفاءة الذهنية لقراءة الخرائط والملاحة الطبوغرافية.'),
('cpe187', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والعضلات الهيكلية', 'الألياف العضلية البطيئة من النوع الأول (Type I / Fibres rouges) تتميز بكونها:', '["غنية بالميوغلوبين والميتوكوندريات وشديدة المقاومة للتعب ملائمة للأنشطة الهوائية والتحملية","سريعة الانقباض وضعيفة التحمل وتتعب في ثوانٍ","بيضاء عديمة الشعيرات الدموية","لا توجد إلا في عضلات الوجه"]'::jsonb, 'غنية بالميوغلوبين والميتوكوندريات وشديدة المقاومة للتعب ملائمة للأنشطة الهوائية والتحملية', 'الألياف الحمراء البطيئة مصممة بيولوجياً للمجهود الهوائي المستمر وتعتمد على تدفق الدم والأكسجين.'),
('cpe188', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا والألياف السريعة', 'الألياف العضلية السريعة من النوع الثاني (Type II / Fibres blanches) ملائمة أساساً لأنشطة:', '["السرعة القصوى والانفجارية والقفز ورفع الأثقال","الماراثون والجري لساعات طويلة","النوم والاسترخاء فقط","تمارين اليوغا والتأمل"]'::jsonb, 'السرعة القصوى والانفجارية والقفز ورفع الأثقال', 'الألياف البيضاء سريعة الانقباض وذات قدرة لاهوائية جبارة وتتميز بسرعة التوصيل العضلي ولكنها سريعة التعب.'),
('cpe189', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى وسباقات الحواجز', 'في سباق 110 أمتار حواجز للذكور، ما هو الإيقاع النمطي المعتمد لعدد الخطوات بين الحواجز لدى العدائين المتميزين؟', '["3 خطوات بين كل حاجزين","5 خطوات","خطوتان فقط","7 خطوات"]'::jsonb, '3 خطوات بين كل حاجزين', 'الإيقاع الثلاثي الكلاسيكي (3 foulées) يضمن الهجوم على كل حاجز بنفس الرجل القائدة دون فقدان السرعة الأفقية.'),
('cpe190', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية وتدبير الوقت', 'ماذا يقصد بـ «زمن الممارسة الحركية الفعلية» (Temps de pratique motrice effective) للتلميذ في الحصة؟', '["الوقت الحقيقي الذي يقضيه المتعلم في الحركة النشطة وممارسة النشاط البدني مقارنة بزمن الحصة الكلي","الوقت المستغرق في تبديل الملابس في المستودع","الوقت الذي يستغرقه الأستاذ في الشرح النظري المفرط","وقت الاستراحة بين الحصص"]'::jsonb, 'الوقت الحقيقي الذي يقضيه المتعلم في الحركة النشطة وممارسة النشاط البدني مقارنة بزمن الحصة الكلي', 'مؤشر جودة حصة EPS يرتبط برفع نسبة وقت الممارسة الفعلية وتقليص أوقات الانتظار والشرح الطويل.'),
('cpe191', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى والوثب الطولي', 'في الوثب الطولي (Saut en longueur)، قياس المسافة المحققة يتم من:', '["حافة لوحة الارتقاء إلى أقرب أثر يتركه المتسابق في الرمال بجسمه أو أطرافه","مكان انطلاق الجري الاقترابي","منتصف حفرة الرمل","أبعد نقطة تلمسها أقدام الرياضي فقط"]'::jsonb, 'حافة لوحة الارتقاء إلى أقرب أثر يتركه المتسابق في الرمال بجسمه أو أطرافه', 'يقاس القفز من خط الارتقاء حتى أدنى علامة يتركها جسم الواثب في حفرة الرمل باتجاه لوحة القفز.'),
('cpe192', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية والمراقبة المستمرة', 'التقويم التكويني (Évaluation formative) في مادة التربية البدنية والرياضية يتدخل أساساً لـ:', '["مواكبة المتعلم أثناء مسار التعلم، وتشخيص الصعوبات الحركية، وتقديم تغذية راجعة فورية لتصحيح المسار وتثبيت التقدم","منح النقطة الإشهادية النهائية للبكالوريا","إقصاء التلاميذ الضعاف من القسم","ترتيب المؤسسات على الصعيد الوطني"]'::jsonb, 'مواكبة المتعلم أثناء مسار التعلم، وتشخيص الصعوبات الحركية، وتقديم تغذية راجعة فورية لتصحيح المسار وتثبيت التقدم', 'التقويم التكويني أداة بيداغوجية للتعلم وليس للجزاء، فهو يساعد المتعلم على وعي أخطائه وتطوير حركاته.'),
('cpe193', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والدفاع المشترك', 'في كرة السلة، نظام الدفاع «رجل لرجل» (Défense individuelle / Homme à homme) يعني:', '["تكليف كل مدافع بمسؤولية رقابة ومتابعة لاعب مهاجم محدد طوال الهجمة","دفاع كل لاعب عن منطقة جغرافية محددة في الملعب","وقوف جميع المدافعين تحت السلة دون حراك","مراقبة الكرة فقط دون النظر للمهاجمين"]'::jsonb, 'تكليف كل مدافع بمسؤولية رقابة ومتابعة لاعب مهاجم محدد طوال الهجمة', 'الدفاع الفردي يلزم كل لاعب بملازمة خصمه المباشر، على عكس الدفاع المنطقي (Défense de zone).'),
('cpe194', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والدفاع المنطقي', 'في كرة اليد، التشكيل الدفاعي الكلاسيكي المشهور «6 - 0» يتميز بـ:', '["اصطفاف المدافعين الستة على خط الـ 6 أمتار لمنع الاختراقات وتصويبات الدائرة وإغلاق زوايا المرمى","خروج جميع المدافعين إلى منتصف الملعب","وجود حارس مرمى بدون أي مدافع","تغطية نصف الملعب فقط طولياً"]'::jsonb, 'اصطفاف المدافعين الستة على خط الـ 6 أمتار لمنع الاختراقات وتصويبات الدائرة وإغلاق زوايا المرمى', 'الدفاع 6-0 خط دفاعي مسطح متماسك يغلق العمق ويجبر الخصم على التصويب البعيد من خارج 9 أمتار.'),
('cpe195', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الفسيولوجيا ومعدل الأيض الأساسي', 'معدل الأيض الأساسي (Métabolisme de base) هو:', '["الحد الأدنى من الطاقة التي يستهلكها الجسم للحفاظ على الوظائف الحيوية الأساسية في حالة راحة تامة وصيام","الطاقة المستهلكة أثناء الجري السريع فقط","كمية الماء التي يفرزها الجلد في الصيف","عدد السعرات الحرارية في وجبة الغداء"]'::jsonb, 'الحد الأدنى من الطاقة التي يستهلكها الجسم للحفاظ على الوظائف الحيوية الأساسية في حالة راحة تامة وصيام', 'الأيض الأساسي يمثل الطاقة الضرورية لعمل القلب والرئتين والكليتين والدماغ والحفاظ على حرارة الجسم.'),
('cpe196', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'التدريب البدني ومفهوم التدرج', 'مبدأ «التدرج وزيادة الحمل التدريبي» (Surcharge progressive) في التربية البدنية يقتضي:', '["زيادة شدة أو حجم أو كثافة التمارين الرياضية تدريجياً وبانتظام لضمان استمرار تكيف الجسم وتطوير اللياقة","مضاعفة الأثقال عشر مرات في أول يوم","ممارسة نفس التمارين السهلة لعدة سنوات دون أي تغيير","التدريب المفرط المفاجئ بدون إحماء"]'::jsonb, 'زيادة شدة أو حجم أو كثافة التمارين الرياضية تدريجياً وبانتظام لضمان استمرار تكيف الجسم وتطوير اللياقة', 'التدرج يمنع الإصابات ويسمح للأنسجة العضلية والقلبية بالتكيف الإيجابي المستمر مع التحديات البدنية الجديدة.'),
('cpe197', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ألعاب القوى والوثب الثلاثي', 'في مسابقة الوثب الثلاثي (Triple saut)، ما هو الترتيب الحركي القانوني للخطوات الثلاث؟', '["الحجلة (على نفس رجل الارتقاء)، ثم الخطوة (على الرجل الأخرى)، ثم القفزة بالهبوط في حفرة الرمل","خطوتان بالرجل اليمنى ثم خطوتان بالرجل اليسرى","القفز المباشر بالقدمين معاً","الدوران مرتين قبل القفز"]'::jsonb, 'الحجلة (على نفس رجل الارتقاء)، ثم الخطوة (على الرجل الأخرى)، ثم القفزة بالهبوط في حفرة الرمل', 'التسلسل الإجباري للوثب الثلاثي: Hop (نفس القدم) ← Step (القدم المقابلة) ← Jump (الهبوط بالقدمين معاً).'),
('cpe198', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الجمباز والاتزان الحركي', 'حركة «الوقوف على اليدين» (Appui Tendu Renversé - ATR) في الجمباز تتطلب لتحقيق التوازن:', '["استقامة الجسم كلياً، وتثبيت الحوض والكتفين، وتوجيه مركز الثقل فوق قاعدة الارتكاز المحددة بالكفين","ثني الظهر بشدة وتفريج الساقين عشوائياً","النظر نحو السقف باستمرار","ثني المرفقين بالكامل حتى لمس الأرض بالأنف"]'::jsonb, 'استقامة الجسم كلياً، وتثبيت الحوض والكتفين، وتوجيه مركز الثقل فوق قاعدة الارتكاز المحددة بالكفين', 'حركة ATR تعتمد على المحاذاة العمودية للمفاصل (معصم، كتف، حوض، كاحل) والشد العضلي الشامل (Gainage).'),
('cpe199', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'الرياضات الجماعية والتحول الهجومي السريع', '«الهجوم الخاطف السريع» (Contre-attaque) في الرياضات الجماعية يتميز بـ:', '["الاستغلال الفوري لعدم توازن دفاع الخصم والانتقال فائق السرعة بالكرة نحو المرمى قبل تنظيم المدافعين","التمرير البطيء بين المدافعين في الخلف لعشر دقائق","إيقاف الكرة وطلب وقت مستقطع","إرجاع الكرة دائماً لحارس المرمى"]'::jsonb, 'الاستغلال الفوري لعدم توازن دفاع الخصم والانتقال فائق السرعة بالكرة نحو المرمى قبل تنظيم المدافعين', 'الهجوم المعاكس المباغت يستغل الفراغ الدفاعي للخصم عقب قطع الكرة لتسجيل هدف سريع بأقل عدد من التمريرات.'),
('cpe200', ARRAY['secondary_prep', 'secondary_qual'], 'sec_pe', 'ديداكتيك التربية البدنية والميثاق الصفي', 'ما هي القيمة التربوية الأسمى للرياضة المدرسية في المنظومة التعليمية المغربية؟', '["ترسيخ قيم التعايش والاندماج الاجتماعي، واحترام الذات والآخر، والانضباط للقواعد ونبذ العنف والتعصب بكل أشكاله","زرع الكراهية والعداوة بين تلاميذ المؤسسات المختلفة","تفضيل القوي وإقصاء الضعيف","التركيز على الفوز بأي وسيلة غير مشروعة"]'::jsonb, 'ترسيخ قيم التعايش والاندماج الاجتماعي، واحترام الذات والآخر، والانضباط للقواعد ونبذ العنف والتعصب بكل أشكاله', 'الرياضة المدرسية وسيلة تربوية نبيلة لنشر قيم التسامح والأخلاق المدنية والاندماج الإيجابي في المجتمع.'),
('cso116', ARRAY['secondary_prep'], 'sec_hist_geo', 'جغرافيا المغرب', 'ما أكبر مدينة مغربية من حيث عدد السكان؟', '["الدار البيضاء","الرباط","فاس","طنجة"]'::jsonb, 'الدار البيضاء', 'الدار البيضاء العاصمة الاقتصادية.'),
('cso117', ARRAY['secondary_prep'], 'sec_hist_geo', 'جغرافيا المغرب', 'ما عاصمة جهة سوس ماسة؟', '["أكادير","تارودانت","تيزنيت","ورزازات"]'::jsonb, 'أكادير', 'أكادير مقر الجهة.'),
('cso118', ARRAY['secondary_prep'], 'sec_hist_geo', 'جغرافيا المغرب', 'أين تقع سلسلة جبال الريف؟', '["شمال المغرب","جنوب المغرب","شرق المغرب فقط","وسط المغرب"]'::jsonb, 'شمال المغرب', 'الريف سلسلة جبلية تطل على المتوسط.'),
('cso119', ARRAY['secondary_prep'], 'sec_hist_geo', 'جغرافيا المغرب', 'ما المضيق الذي يفصل المغرب عن أوروبا؟', '["مضيق جبل طارق","مضيق هرمز","مضيق باب المندب","مضيق البوسفور"]'::jsonb, 'مضيق جبل طارق', 'يربط الأطلسي بالمتوسط.'),
