('fr159', ARRAY['primary'], 'fr', 'Propositions et phrase complexe', 'Dans « Je viendrai dès que j’aurai fini », la subordonnée exprime :', '["le temps","la cause","la conséquence","le but"]'::jsonb, 'le temps', '« dès que » est une conjonction de temps.'),
('fr160', ARRAY['primary'], 'fr', 'Propositions et phrase complexe', 'Des propositions juxtaposées sont reliées par :', '["un signe de ponctuation","une conjonction de coordination","un pronom relatif","une conjonction de subordination"]'::jsonb, 'un signe de ponctuation', 'Juxtaposition : virgule, point-virgule ou deux-points.'),
('fr161', ARRAY['primary'], 'fr', 'Ponctuation', 'Quel signe de ponctuation introduit une énumération ou une explication ?', '["les deux-points","le point-virgule","les points de suspension","le point d’exclamation"]'::jsonb, 'les deux-points', 'Les deux-points annoncent une liste, une explication ou une citation.'),
('fr162', ARRAY['primary'], 'fr', 'Ponctuation', 'Dans un dialogue, que place-t-on avant la parole d’un nouveau personnage ?', '["un tiret","un point-virgule","des parenthèses","un astérisque"]'::jsonb, 'un tiret', 'Le tiret marque le changement de locuteur.'),
('fr163', ARRAY['primary'], 'fr', 'Ponctuation', 'Quelle phrase est correctement ponctuée ?', '["Paul, mon voisin, est médecin.","Paul mon voisin est, médecin.","Paul, mon voisin est médecin.","Paul mon voisin, est médecin."]'::jsonb, 'Paul, mon voisin, est médecin.', 'L’apposition « mon voisin » se place entre deux virgules.'),
('fr164', ARRAY['primary'], 'fr', 'Ponctuation', 'Que doit-on écrire après un point ?', '["une majuscule","une minuscule","une virgule","un tiret"]'::jsonb, 'une majuscule', 'Le point termine la phrase ; la suivante commence par une majuscule.'),
('fr165', ARRAY['primary'], 'fr', 'Ponctuation', 'Quelle phrase respecte rigoureusement les règles de ponctuation du discours direct ?', '["Il demande : « Où vas-tu ? »","Il demande « Où vas-tu ? » :","Il demande : « Où vas-tu ? » .","Il demande, Où vas-tu ?"]'::jsonb, 'Il demande : « Où vas-tu ? »', 'Au discours direct, les deux-points introduisent les guillemets, et le point d''interrogation se place à l''intérieur des guillemets sans point final extérieur supplémentaire.'),
('fr166', ARRAY['primary'], 'fr', 'Ponctuation', 'Les points de suspension marquent :', '["une phrase inachevée ou une hésitation","la fin d’un paragraphe","une citation","une question"]'::jsonb, 'une phrase inachevée ou une hésitation', 'Ils indiquent aussi un sous-entendu ou une énumération non terminée.'),
('fr167', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Ce matin, Samir s’est levé en retard. Il a couru jusqu’à l’arrêt, mais le bus était déjà parti. » Que dit le texte ?', '["Samir a manqué son bus.","Samir a pris le bus.","Samir s’est levé tôt.","Samir est resté à la maison."]'::jsonb, 'Samir a manqué son bus.', 'Information explicite : le bus était déjà parti.'),
('fr168', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Ce matin, Samir s’est levé en retard. Il a couru jusqu’à l’arrêt, mais le bus était déjà parti. » Quel mot marque l’opposition ?', '["mais","ce","jusqu’à","déjà"]'::jsonb, 'mais', '« mais » oppose l’effort de Samir à son résultat.'),
('fr169', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Le ciel était noir, les oiseaux se taisaient et le vent s’était levé. » Que laisse deviner ce passage ?', '["Un orage approche.","Il fait très chaud.","C’est la fête.","La nuit est finie."]'::jsonb, 'Un orage approche.', 'Question d’inférence : les indices annoncent un orage.'),
('fr170', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Le ciel était noir, les oiseaux se taisaient. » Quel temps domine dans cette description ?', '["l’imparfait","le futur","le passé simple","le conditionnel"]'::jsonb, 'l’imparfait', 'L’imparfait sert à décrire le décor dans un récit passé.'),
('fr171', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Pour réussir ce gâteau, il faut d’abord mélanger les œufs et le sucre, puis ajouter la farine. » De quel type de texte s’agit-il ?', '["injonctif (prescriptif)","narratif","descriptif","argumentatif"]'::jsonb, 'injonctif (prescriptif)', 'Il donne des consignes pour réaliser quelque chose.'),
('fr172', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Il faut d’abord mélanger les œufs et le sucre, puis ajouter la farine. » Quels mots marquent l’ordre des actions ?', '["d’abord … puis","il faut","les œufs","la farine"]'::jsonb, 'd’abord … puis', 'Ce sont des organisateurs temporels.'),
('fr173', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « Fatima adore la lecture. Elle passe ses soirées à dévorer des romans. » Que signifie « dévorer » ici ?', '["lire avec avidité (sens figuré)","manger","détruire","jeter"]'::jsonb, 'lire avec avidité (sens figuré)', 'Sens figuré : lire très vite et avec passion.'),
('fr174', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Dans un récit, la situation initiale présente :', '["le cadre, le lieu et les personnages","la résolution du problème","l’élément perturbateur","la morale"]'::jsonb, 'le cadre, le lieu et les personnages', 'Elle installe l’équilibre de départ.'),
('fr175', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Dans un récit, l’élément perturbateur est :', '["l’événement qui rompt l’équilibre initial","la dernière phrase","la description du décor","la morale"]'::jsonb, 'l’événement qui rompt l’équilibre initial', 'Il lance l’action et provoque les péripéties.'),
('fr176', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Texte : « La mer est calme. Quelques voiliers blancs glissent sur l’eau. » De quel type de texte s’agit-il ?', '["descriptif","narratif","argumentatif","injonctif"]'::jsonb, 'descriptif', 'Il présente un lieu, sans événement.'),
('fr177', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Un texte argumentatif a pour but :', '["de convaincre le lecteur","de raconter une histoire","de donner un ordre","de décrire un objet"]'::jsonb, 'de convaincre le lecteur', 'Il défend une thèse avec des arguments et des exemples.'),
('fr178', ARRAY['primary'], 'fr', 'Compréhension de l’écrit', 'Que signifie l’expression « Il fait un froid de canard » ?', '["Il fait très froid.","Il y a des canards.","Il fait chaud.","Il neige."]'::jsonb, 'Il fait très froid.', 'Expression imagée à comprendre au sens figuré.'),
('fr179', ARRAY['primary'], 'fr', 'Production écrite', 'Dans une lettre amicale, la formule d’appel peut être :', '["Cher Ahmed,","Cordialement","Le 5 novembre","Objet : invitation"]'::jsonb, 'Cher Ahmed,', 'La formule d’appel s’adresse au destinataire en début de lettre.'),
('fr180', ARRAY['primary'], 'fr', 'Production écrite', 'Quelle formule convient pour terminer une lettre amicale ?', '["Je t’embrasse.","Veuillez agréer, Monsieur, mes salutations distinguées.","Madame la Directrice,","Objet : demande"]'::jsonb, 'Je t’embrasse.', 'La formule de politesse doit respecter le registre familier de la lettre.'),
('fr181', ARRAY['primary'], 'fr', 'Production écrite', 'Dans un récit au passé, quel temps utilise-t-on pour les actions de premier plan ?', '["le passé simple ou le passé composé","l’imparfait","le futur","le conditionnel"]'::jsonb, 'le passé simple ou le passé composé', 'L’imparfait sert à l’arrière-plan : description, habitude.'),
('fr182', ARRAY['primary'], 'fr', 'Production écrite', 'Pour éviter les répétitions dans un texte, on utilise :', '["des pronoms et des synonymes","la même phrase","des majuscules","des titres"]'::jsonb, 'des pronoms et des synonymes', 'La reprise nominale ou pronominale assure la cohérence.'),
('fr183', ARRAY['primary'], 'fr', 'Production écrite', 'Quels connecteurs marquent la chronologie ?', '["d’abord, ensuite, enfin","pourtant, cependant, mais","car, parce que, puisque","donc, ainsi, par conséquent"]'::jsonb, 'd’abord, ensuite, enfin', 'Ce sont des organisateurs temporels.'),
('fr184', ARRAY['primary'], 'fr', 'Production écrite', 'Quels connecteurs expriment la cause ?', '["car, parce que, puisque","d’abord, ensuite, enfin","pourtant, cependant","donc, ainsi"]'::jsonb, 'car, parce que, puisque', 'Ils répondent à la question : pourquoi ?'),
('fr185', ARRAY['primary'], 'fr', 'Production écrite', 'Un paragraphe bien construit s’organise autour de :', '["une idée directrice","une citation obligatoire","une question toujours","un titre"]'::jsonb, 'une idée directrice', 'Chaque paragraphe développe une idée principale.'),
('fr186', ARRAY['primary'], 'fr', 'Production écrite', 'Quelle étape précède la rédaction d’un texte ?', '["planifier : chercher les idées et faire un plan","recopier le texte","corriger les fautes","illustrer le texte"]'::jsonb, 'planifier : chercher les idées et faire un plan', 'Démarche : planifier, rédiger, réviser, réécrire.'),
('fr187', ARRAY['primary'], 'fr', 'Production écrite', 'Pour réviser un texte, que faut-il vérifier ?', '["la cohérence, l’orthographe et la ponctuation","uniquement la longueur","la couleur de l’encre","le nombre de mots"]'::jsonb, 'la cohérence, l’orthographe et la ponctuation', 'La grille de révision porte sur le sens et la langue.'),
('fr188', ARRAY['primary'], 'fr', 'Production écrite', 'La conclusion d’un texte argumentatif :', '["reprend la thèse et résume les arguments","introduit un nouvel argument","raconte une anecdote","pose cinq questions"]'::jsonb, 'reprend la thèse et résume les arguments', 'Elle clôt le raisonnement sans ajouter de nouvel argument.'),
('fr189', ARRAY['primary'], 'fr', 'Conjugaison', 'Futur simple de « voir » à la 3e personne du singulier :', '["il verra","il voira","il verrait","il voit"]'::jsonb, 'il verra', 'Le radical du futur de voir est « verr- ».'),
