('sc188', ARRAY['primary'], 'sc', 'البيئة والتنمية المستدامة', 'أي الممارسات الآتية تساهم في ترشيد استعمال الماء في الفلاحة؟', '["الري بالتنقيط","سقي الحقول وسط النهار","الري بالغمر المستمر","ترك قنوات السقي مفتوحة"]'::jsonb, 'الري بالتنقيط', 'الري بالتنقيط يوصل الماء إلى جذور النبات مباشرة فيقلل التبخر والضياع.'),
('sc189', ARRAY['primary'], 'sc', 'البيئة والتنمية المستدامة', 'أي مما يلي من أسباب التصحر؟', '["الرعي الجائر وقطع الأشجار","غرس الأحزمة الخضراء","تنظيم الرعي","الحفاظ على الغطاء النباتي"]'::jsonb, 'الرعي الجائر وقطع الأشجار', 'الرعي الجائر وقطع الأشجار يزيلان الغطاء النباتي فتتدهور التربة وتنجرف.'),
('sc190', ARRAY['primary'], 'sc', 'البيئة والتنمية المستدامة', 'أي مشروع مغربي كبير لإنتاج الطاقة الشمسية يوجد قرب ورزازات؟', '["مركب نور","محطة جرف الأصفر","سد الوحدة","ميناء طنجة المتوسط"]'::jsonb, 'مركب نور', 'مركب نور بورزازات من أكبر مشاريع الطاقة الشمسية المركزة في العالم.'),
('sc191', ARRAY['primary'], 'sc', 'البيئة والتنمية المستدامة', 'ما نتيجة تسرب الأسمدة الكيميائية الغنية بالنترات إلى مياه بحيرة؟', '["تكاثر الطحالب ونقص الأكسجين المذاب (الإثراء الغذائي)","ازدياد عدد الأسماك دائما","تحسن جودة الماء","انخفاض درجة حرارة الماء"]'::jsonb, 'تكاثر الطحالب ونقص الأكسجين المذاب (الإثراء الغذائي)', 'النترات تغذي الطحالب فتتكاثر، وعند تحللها يستهلك الأكسجين فتختنق الكائنات المائية.'),
('sc192', ARRAY['primary'], 'sc', 'البيئة والتنمية المستدامة', 'ما المقصود بمبدأ الثلاثية (3R) في تدبير النفايات؟', '["التقليل وإعادة الاستعمال وإعادة التدوير","الحرق والدفن والتصدير","الجمع والنقل والتخزين","الشراء والاستعمال والرمي"]'::jsonb, 'التقليل وإعادة الاستعمال وإعادة التدوير', 'المبدأ يرتب الخيارات من الأفضل: تقليل النفايات، ثم إعادة استعمالها، ثم إعادة تدويرها.'),
('sc193', ARRAY['primary'], 'sc', 'الأرض والكون', 'في أي تاريخ تقريبا يقع الانقلاب الصيفي في نصف الكرة الشمالي؟', '["حوالي 21 يونيو","حوالي 21 مارس","حوالي 21 دجنبر","حوالي 23 شتنبر"]'::jsonb, 'حوالي 21 يونيو', 'الانقلاب الصيفي يوافق أطول نهار في السنة بالنصف الشمالي، حوالي 21 يونيو.'),
('sc194', ARRAY['primary'], 'sc', 'الأرض والكون', 'في أي طور من أطوار القمر يمكن أن يحدث كسوف الشمس؟', '["المحاق (القمر الجديد)","البدر","التربيع الأول","التربيع الأخير"]'::jsonb, 'المحاق (القمر الجديد)', 'الكسوف يحدث حين يقع القمر بين الشمس والأرض، أي عند المحاق.'),
('sc195', ARRAY['primary'], 'sc', 'الأرض والكون', 'كيف تصنف الشمس فلكيا؟', '["نجم","كوكب","قمر","مذنب"]'::jsonb, 'نجم', 'الشمس نجم يشع الضوء والحرارة بفعل تفاعلات الاندماج النووي في قلبه.'),
('sc196', ARRAY['primary'], 'sc', 'الأرض والكون', 'وزن جسم على سطح الأرض 600 نيوتن. ما وزنه تقريبا على سطح القمر، علما أن ثقالة القمر نحو سدس ثقالة الأرض؟', '["100 نيوتن","3600 نيوتن","600 نيوتن","10 نيوتن"]'::jsonb, '100 نيوتن', 'الوزن على القمر نحو 600 ÷ 6 = 100 نيوتن، والكتلة لا تتغير.'),
('sc197', ARRAY['primary'], 'sc', 'الأرض والكون', 'السنة الضوئية وحدة لقياس:', '["المسافة","الزمن","السرعة","الكتلة"]'::jsonb, 'المسافة', 'السنة الضوئية المسافة التي يقطعها الضوء في سنة، أي نحو 9500 مليار كيلومتر.'),
('sc198', ARRAY['primary'], 'sc', 'الأرض والكون', 'ما السبب الرئيسي لظاهرة المد والجزر في المحيطات؟', '["جاذبية القمر والشمس لمياه المحيطات","هبوب الرياح","التيارات البحرية","الزلازل البحرية"]'::jsonb, 'جاذبية القمر والشمس لمياه المحيطات', 'جاذبية القمر، ومعها الشمس بدرجة أقل، تسبب ارتفاع مستوى المياه وانخفاضه دوريا.'),
('sc199', ARRAY['primary'], 'sc', 'الأرض والكون', 'كيف تتكون الصخور النارية؟', '["من تبرد الصهارة وتصلبها","من تراكم الرواسب وتماسكها","بتحول صخور أخرى تحت الضغط والحرارة","من بقايا الكائنات الحية فقط"]'::jsonb, 'من تبرد الصهارة وتصلبها', 'الصخور النارية كالغرانيت والبازلت تنتج عن تصلب الصهارة داخل الأرض أو على سطحها.'),
('sc200', ARRAY['primary'], 'sc', 'الأرض والكون', 'ما السبب الرئيسي لأغلب الزلازل؟', '["حركة الصفائح التكتونية واحتكاكها أو تصادمها","هبوب الرياح القوية","اختلاف حرارة الجو","المد والجزر"]'::jsonb, 'حركة الصفائح التكتونية واحتكاكها أو تصادمها', 'تتحرك الصفائح الصخرية لقشرة الأرض فتتراكم الإجهادات ثم تنطلق على شكل اهتزازات.'),
('dar151', ARRAY['primary'], 'dar', 'مكون الاستماع والتحدث', 'كم عدد الحصص المخصصة لمكون الاستماع والتحدث في المستويات الثلاثة الأولى أسبوعياً؟', '["5 حصص في الأسبوع","3 حصص في الأسبوع","حصتان فقط","6 حصص في الأسبوع"]'::jsonb, '5 حصص في الأسبوع', 'يخصص المنهاج المنقح للغة العربية في السنوات الثلاث الأولى 5 حصص أسبوعياً لمكون الاستماع والتحدث.'),
('dar152', ARRAY['primary'], 'dar', 'مكون الاستماع والتحدث', 'على مدى كم أسبوع يتم استثمار الحكاية الواحدة في مكون الاستماع والتحدث بالسنوات الثلاث الأولى؟', '["تُستثمر الحكاية الواحدة على مدى أسبوعين","تُستثمر الحكاية على مدى أسبوع واحد فقط","تُستثمر على مدى ثلاثة أسابيع متتالية","تُستثمر طيلة أسابيع الوحدة الأربعة"]'::jsonb, 'تُستثمر الحكاية الواحدة على مدى أسبوعين', 'في المستويات 1 و2 و3، يتم تقديم واستثمار حكاية واحدة في كل أسبوعين (أي حكايتان في الوحدة الديدكتيكية).'),
('dar153', ARRAY['primary'], 'dar', 'مكون الاستماع والتحدث', 'ما المدة الزمنية المخصصة لتقديم وضعية تواصلية واحدة في مكون الاستماع والتحدث؟', '["أسبوع تربوي واحد بمعدل حصتين","أسبوعان كاملان","ثلاثة أسابيع","شهر كامل"]'::jsonb, 'أسبوع تربوي واحد بمعدل حصتين', 'تُخصص أسبوعاً واحداً لكل وضعية تواصلية، بحيث يدرس المتعلم وضعيتين تواصليتين بموازاة حكاية واحدة خلال أسبوعين.'),
('dar154', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هي المراحل الخمس المعتمدة لتدريس مهارات الوعي الصوتي وفق القراءة المقطعية؟', '["العزل، التجزيء، التركيب، الحذف، والتعويض","الحفظ، الاستظهار، التسميع، الترجمة، والكتابة","الرسم، النقل، الإملاء، التعبير، والخط","الملاحظة، التحليل، المقارنة، الاستنباط، والتقييم"]'::jsonb, 'العزل، التجزيء، التركيب، الحذف، والتعويض', 'تتضمن مهارات الوعي الصوتي عزل المقطع، تجزيء الكلمة إلى مقاطع، تركيب المقاطع، وحذف أو تعويض مقطع للحصول على كلمة جديدة.'),
('dar155', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هو المبدأ الألفبائي في ديداكتيك القراءة المقطعية بالسلك الابتدائي؟', '["الربط المباشر والصحيح بين الصوت المنطوق (الفونيم) وحرفه المكتوب (الغرافيم)","حفظ الحروف الأبجدية بالترتيب الهجائي التقليدي","قراءة النصوص الشعرية مع الإنشاد السريع","استخراج الأفكار الأساسية من النص المسترسل"]'::jsonb, 'الربط المباشر والصحيح بين الصوت المنطوق (الفونيم) وحرفه المكتوب (الغرافيم)', 'المبدأ الألفبائي يقوم على إدراك المتعلم للعلاقة المتبادلة بين الأصوات اللغوية والرموز الخطية الممثلة لها.'),
('dar156', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'أي استراتيجية من استراتيجيات تنمية المفردات تقوم على البحث عن مشتقات الكلمة من نفس الجذر؟', '["عائلة الكلمة (الاشتقاق)","شبكة المفردات (الحقل الدلالي)","خريطة الكلمة (النوع والمرادف والضد)","مفاتيح السياق"]'::jsonb, 'عائلة الكلمة (الاشتقاق)', 'عائلة الكلمة تركز على الصيغ والمشتقات الصرفية التي تشترك في نفس الجذر اللغوي (كتب، كاتب، مكتوب، مكتبة).'),
('dar157', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما العناصر الأربعة التي تتضمنها «خريطة الكلمة» كاستراتيجية لتنمية المعجم؟', '["نوع الكلمة، مرادفها، ضدها، وتركيبها في جملة مفيدة","حروف الكلمة، عدد حركاتها، وزنها، وإعرابها","اشتقاقها، جمعها، مفردها، ومصدرها","صاحب النص، عنوانه، فكرته العامة، ومغزاه"]'::jsonb, 'نوع الكلمة، مرادفها، ضدها، وتركيبها في جملة مفيدة', 'خريطة الكلمة تتناول: نوع الكلمة (اسم/فعل)، معناها (مرادفها)، ضدها، واستعمالها في سياق تركيبي سليم.'),
('dar158', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'متى يتم تفعيل استراتيجية «التوقع» وبناء الفرضيات القرائية في درس القراءة؟', '["في مرحلة ما قبل القراءة بالاعتماد على العنوان والمؤشرات البصرية","بعد الانتهاء من قراءة النص كاملاً والإجابة عن الأسئلة","أثناء التمارين اللغوية الكتابية في نهاية الأسبوع","في مرحلة التقويم التشخيصي لبداية الموسم الدراسي فقط"]'::jsonb, 'في مرحلة ما قبل القراءة بالاعتماد على العنوان والمؤشرات البصرية', 'استراتيجية التوقع تطبق قبل القراءة لتحفيز الفضول وصياغة فرضيات حول مضمون النص انطلاقاً من العتبات.'),
('dar159', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هو النص المسترسل وما الغاية الديداكتيكية من إدراجه في المستويات العليا (4 و5 و6)؟', '["نص نثري طويل يمتد على 4 أجزاء لتنمية النفس القرائي والمطالعة المستمرة","نص شعري ملحن يُحفظ غيباً خلال حصة واحدة","حوار مسرحي قصير يقدم في عشر دقائق للترفيه","نص إملائي يختبر الرسم الإملائي للهمزات"]'::jsonb, 'نص نثري طويل يمتد على 4 أجزاء لتنمية النفس القرائي والمطالعة المستمرة', 'النص المسترسل نص سردي طويل يوزع على أسابيع الوحدة الأربعة بهدف تدريب المتعلم على القراءة الذاتية والنفس الطويل.'),
('dar160', ARRAY['primary'], 'dar', 'ديداكتيك الكتابة', 'ما هي المراحل الإجرائية المتدرجة لحصة الكتابة في المستوى الأول الابتدائي؟', '["التخطيط، النمذجة والملاحظة، التدرب على الألواح، الإنتاج على الدفاتر، ثم التصحيح","كتابة نص طويل من وحي الخيال دون مساعدة الأستاذ","حفظ القاعدة الصرفية ثم إعراب الجملة مباشرة","قراءة النص بصوت مرتفع دون استعمال القلم"]'::jsonb, 'التخطيط، النمذجة والملاحظة، التدرب على الألواح، الإنتاج على الدفاتر، ثم التصحيح', 'يبدأ تعليم الخط في المستوى الأول بعرض النموذج وملاحظته والتمرن في الهواء والألواح قبل الكتابة النهائية على الدفتر.'),
('dar161', ARRAY['primary'], 'dar', 'ديداكتيك الكتابة', 'ما الخطوات المنهجية المتبعة لإنتاج موضوع في التعبير الكتابي بالمستويات (4 و5 و6)؟', '["التخطيط، كتابة المسودة، المراجعة والتنقيح، ثم العرض والنشر","كتابة الموضوع مباشرة وتصحيحه بنقطة دون مسودة","حفظ مقال جاهز من الكراسة ونقله على السبورة","قراءة قصة وتلخيصها في سطرين خلال دقيقة واحدة"]'::jsonb, 'التخطيط، كتابة المسودة، المراجعة والتنقيح، ثم العرض والنشر', 'يعتمد التعبير الكتابي مساراً مرحلياً يبدأ بالتخطيط وتوليد الأفكار، يليه التسويد، ثم المراجعة والتحسين، وصولاً إلى العرض.'),
('dar162', ARRAY['primary'], 'dar', 'ديداكتيك الظواهر اللغوية', 'كيف تُمرر الظواهر اللغوية (الصرف والتحويل، التراكيب، الإملاء) في السنوات الثلاث الأولى؟', '["بشكل ضمني وتحسيسي عبر الاستعمال وسياق النصوص ودون قواعد مصرح بها","بتدريس القواعد النظرية وحفظ التعاريف النحوية حرفياً","بإجراء اختبارات إعرابية يومية ومكثفة","تُحذف تماماً ولا يُشار إليها بأي شكل من الأشكال"]'::jsonb, 'بشكل ضمني وتحسيسي عبر الاستعمال وسياق النصوص ودون قواعد مصرح بها', 'في المستويات 1 و2 و3 تُمرر القواعد ضمنياً من خلال التداول الشفهي والنصوص المقروءة دون تصريح بالقواعد والمصطلحات.'),
('dar163', ARRAY['primary'], 'dar', 'ديداكتيك الظواهر اللغوية', 'في أي مستوى ابتدائي يبدأ التصريح المنهاجي بقواعد التراكيب والصرف والتحويل؟', '["ابتداءً من المستوى الرابع الابتدائي","في المستوى الثاني الابتدائي","في السنة الأولى الابتدائية","في السلك الإعدادي فقط"]'::jsonb, 'ابتداءً من المستوى الرابع الابتدائي', 'ينص المنهاج المنقح على الانتقال من التحسيس الضمني إلى التدريس الصريح للقواعد اللغوية ابتداءً من السنة الرابعة.'),
('dar164', ARRAY['primary'], 'dar', 'مشروع الوحدة', 'ما الدور الديداكتيكي لمكون «مشروع الوحدة» في برنامج اللغة العربية؟', '["إدماج التعلمات اللغوية والمهارية في إطار عمل تعاوني هادف وملموس","شغل أوقات فراغ المتعلمين بأنشطة منزلية ترفيهية فقط","إلغاء حصص القراءة والكتابة لتعويضها بالرسم","إلزام المتعلم بإنجاز بحوث أكاديمية جامعية معقدة"]'::jsonb, 'إدماج التعلمات اللغوية والمهارية في إطار عمل تعاوني هادف وملموس', 'مشروع الوحدة هو إطار بيداغوجي إدماجي يُمكّن المتعلمين من تفعيل مكتسباتهم اللغوية والمعرفية في إنتاج جماعي ملموس.'),
('dar165', ARRAY['primary'], 'dar', 'التدبير الزمني للوحدة', 'كم عدد الأسابيع التربوية المخصصة لبناء التعلمات في كل وحدة ديدكتيكية بالابتدائي؟', '["4 أسابيع لبناء التعلمات يخصص الأسبوع الخامس للتقويم والدعم","أسبوعان للتعلم وأسبوعان للتقويم","5 أسابيع كاملة للبناء دون تقويم","3 أسابيع للبناء وأسبوعان للتقويم"]'::jsonb, '4 أسابيع لبناء التعلمات يخصص الأسبوع الخامس للتقويم والدعم', 'تمتد الوحدة الديداكتيكية لخمسة أسابيع: 4 أسابيع لإرساء الموارد وبناء التعلمات، والأسبوع الخامس مخصص للتقويم والدعم والتوليف.'),
('dar166', ARRAY['primary'], 'dar', 'مكون الاستماع والتحدث', 'ما هي المراحل الثلاث الأساسية لتقديم الحكاية في حصص الاستماع والتحدث؟', '["ما قبل الاستماع، أثناء الاستماع، وما بعد الاستماع","الحفظ على ظهر قلب، الاستظهار السريع، والترجمة","الإملاء المنظور، النسخ، والتصحيح الذاتي","استخراج القواعد الصرفية، الإعراب، والتطبيق"]'::jsonb, 'ما قبل الاستماع، أثناء الاستماع، وما بعد الاستماع', 'يتدرج درس الاستماع والتحدث عبر 3 مراحل منهجية كبرى: ما قبل الاستماع (التهيئة والتوقع)، أثناء الاستماع (الفهم)، وما بعد الاستماع (الاستثمار والإنتاج).'),
('dar167', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هي الاستراتيجية المعتمدة للتحقق من الفهم الصريح والضمني للنص القرائي؟', '["طرح أسئلة الفهم المباشرة واستنتاج المعاني الثاوية بين السطور","إعادة كتابة النص عشر مرات على الألواح","ترديد الأستاذ للنص دون إشراك التلاميذ","مطالبة المتعلم بتخمين خاتمة بديلة دون قراءة النص"]'::jsonb, 'طرح أسئلة الفهم المباشرة واستنتاج المعاني الثاوية بين السطور', 'يتحقق فهم المقروء من خلال استخراج المعطيات الصريحة، وتأويل المعاني الضمنية، وتركيب الأفكار وإبداء الرأي.'),
('dar168', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما المقصود بـ «الكلمات البصرية» في القراءة المقطعية بالمستويات الصغرى؟', '["كلمات تتكرر بكثرة في النصوص يقرؤها المتعلم ككل بطلاقة دون تهج مقطعي","كلمات مكتوبة بخط خفي لا يراها إلا المعلم","رسوم وصور بدون أي نص مكتوب","كلمات صعبة ومعقدة تستخرج من المعاجم اللغوية القديمة"]'::jsonb, 'كلمات تتكرر بكثرة في النصوص يقرؤها المتعلم ككل بطلاقة دون تهج مقطعي', 'الكلمات البصرية (Mots outils) هي مفردات وظيفية متداولة (مثل: هذا، ذلك، الذي، في) يُدرب المتعلم على التعرف عليها شمولياً وبسرعة.'),
('dar169', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هو الهدف الرئيس من اعتماد «القراءة المشتركة» في بداية حصص القراءة؟', '["تنمية الطلاقة وإغناء الرصيد اللغوي من خلال نصوص قصيرة وإيقاعية ممتعة","تصنيف التلاميذ إلى متفوقين ومتعثرين","إجراء فرض كتابي مفاجئ للمتعلمين","تدريب التلاميذ على التزام الصمت التام أثناء الحصة"]'::jsonb, 'تنمية الطلاقة وإغناء الرصيد اللغوي من خلال نصوص قصيرة وإيقاعية ممتعة', 'القراءة المشتركة نشاط افتتاحي يومي قصير يعتمد نصوصاً رشيقة وبسيطة تُقرأ جماعياً لتطوير إيقاع القراءة وحب اللغة.'),
('dar170', ARRAY['primary'], 'dar', 'التخطيط التربوي', 'ما الفرق الجوهري بين التخطيط طويل المدى والتخطيط قصير المدى في تدريس اللغة العربية؟', '["طويل المدى يغطي السنة الدراسية كاملة، بينما قصير المدى يغطي الجذاذة اليومية للحصة","طويل المدى خاص بالامتحانات، وقصير المدى خاص بالعطل المدرسية","طويل المدى يعده المفتش، وقصير المدى يعده المدير فقط","لا يوجد أي فرق بينهما فكلاهما نفس الشيء"]'::jsonb, 'طويل المدى يغطي السنة الدراسية كاملة، بينما قصير المدى يغطي الجذاذة اليومية للحصة', 'التخطيط السنوي هو تخطيط بعيد المدى، والتخطيط للوحدة متوسط المدى، في حين يمثل التخطيط للحصة واليوم تخطيطاً قصير المدى.'),
('dar171', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هي مهارة «التفييء الصوتي» في الوعي الصوتي؟', '["التعرف على الكلمة الشاذة التي تبتدئ أو تنتهي بصوت يختلف عن باقي الكلمات","قراءة الكلمات بالمقلوب من اليسار إلى اليمين","كتابة الصوت ثلاث مرات بألوان مختلفة","تحويل الفعل من الماضي إلى الأمر"]'::jsonb, 'التعرف على الكلمة الشاذة التي تبتدئ أو تنتهي بصوت يختلف عن باقي الكلمات', 'التفييء الصوتي يعني عزل الكلمة التي لا تنتمي للمجموعة الصوتية المشتركة (مثلاً: سمك، سحب، كتاب، سماء -> كتاب شاذة).'),
('dar172', ARRAY['primary'], 'dar', 'ديداكتيك الكتابة', 'ما الفرق بين الإملاء المنظور والإملاء غير المنظور بالسلك الابتدائي؟', '["المنظور يقرؤه المتعلم ويلاحظ كلماته وظواهره قبل الإملاء، بينما غير المنظور يملى مباشرة دون معاينة سابقة","المنظور يكتب بالأعين المغمضة وغير المنظور بالأعين المفتوحة","المنظور يكتب في البيت وغير المنظور في القسم","المنظور لا يحتوي على نقاط وغير المنظور يحتوي على حركات"]'::jsonb, 'المنظور يقرؤه المتعلم ويلاحظ كلماته وظواهره قبل الإملاء، بينما غير المنظور يملى مباشرة دون معاينة سابقة', 'في الإملاء المنظور تُفحص الظاهرة الإملائية وتُناقش كتابة كلماتها قبل إخفائها وإملائها، عكس غير المنظور الذي يقيس الاستقلالية التامة.'),
('dar173', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما هو مبدأ «التدرج والاستمرار» في هندسة منهاج اللغة العربية الابتدائي؟', '["تقديم المفاهيم من البسيط إلى المركب ومن الشفهي والمحسوس إلى المجرد والصريح","تقديم الدروس الصعبة في الأسبوع الأول لفرز التلاميذ","تكرار نفس الدرس بحذافيره في جميع المستويات الدراسية","الانتقال الفجائي من الحروف إلى كتابة الروايات الأدبية"]'::jsonb, 'تقديم المفاهيم من البسيط إلى المركب ومن الشفهي والمحسوس إلى المجرد والصريح', 'يبنى المنهاج لولبياً بحيث تتوسع الكفاية وتتطور تدريجياً من التحسيس الشفهي إلى الكتابة المنهجية المتقدمة.'),
('dar174', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'في المستوى الأول، كم حرفاً عربياً يتم تقديمه في كل أسبوع خلال الأسدوس الأول؟', '["حرف واحد في الأسبوع لتمكين المتعلم من التثبيت والتحكم","ثلاثة حروف في كل أسبوع دفعة واحدة","حرفان في كل حصة يومية","جميع الحروف الأبجدية في الشهر الأول"]'::jsonb, 'حرف واحد في الأسبوع لتمكين المتعلم من التثبيت والتحكم', 'يقدم المنهاج المنقح في المستوى الأول حرفاً واحداً في الأسبوع خلال الأسدوس الأول لضمان ترسيخ الصوت ورسمه الخطي.'),
('dar175', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'كم حرفاً يتم تقديمه في الأسبوع خلال الأسدوس الثاني من السنة الأولى الابتدائية؟', '["حرفان في كل أسبوع","حرف واحد كما في الأسدوس الأول","خمسة حروف في الأسبوع","لا تُقدم أي حروف جديدة"]'::jsonb, 'حرفان في كل أسبوع', 'بعد تمكن المتعلم من آليات الوعي الصوتي، يرتفع النسق في الأسدوس الثاني إلى تقديم حرفين في الأسبوع.'),
('dar176', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما الفرق الأساسي بين النص الوظيفي والنص الشعري في درس القراءة؟', '["النص الوظيفي نثري ينمي الكفايات التواصلية والمعرفية، بينما الشعري موزون ينمي التذوق الجمالي والإيقاعي","النص الوظيفي يقرأ فقط والنص الشعري يكتب فقط","النص الوظيفي لا يحتاج إلى أسئلة فهم عكس الشعري","النص الشعري مخصص للامتحانات فقط والوظيفي للأنشطة الموازية"]'::jsonb, 'النص الوظيفي نثري ينمي الكفايات التواصلية والمعرفية، بينما الشعري موزون ينمي التذوق الجمالي والإيقاعي', 'النص الوظيفي يعالج مجالات الوحدة بمفردات عملية، في حين يركز النص الشعري على البعد الإنشادي والموسيقى اللغوية.'),
('dar177', ARRAY['primary'], 'dar', 'تقويم ودعم اللغة العربية', 'ما هو الإجراء الديداكتيكي الأمثل عند ملاحظة تعثر تلميذ في التمييز بين صوتي (الدال والضاد)؟', '["اعتماد أنشطة الوعي الصوتي والمقارنة السمعية والتركيز على مخارج الحروف وصفاتها","تجاهل التعثر والاعتماد على مرور الوقت ليعالجه ذاتياً","إلزام التلميذ بكتابة الحرفين مائة مرة كعقوبة","منع التلميذ من المشاركة في حصة القراءة الشفهية"]'::jsonb, 'اعتماد أنشطة الوعي الصوتي والمقارنة السمعية والتركيز على مخارج الحروف وصفاتها', 'معالجة الخلط الصوتي تتطلب تدريباً سمعياً تمييزياً (عزل الصوت، مقارنة أزواج أدنى مثل: دخل/ضل) وتحديد صفة الإطباق والترقيق.'),
('dar178', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ماذا يقصد باستراتيجية «المصاوغة» أو «المحاكاة والنمذجة» التي يقوم بها الأستاذ في القراءة؟', '["قراءة نموذجية يقدمها الأستاذ تبين النطق السليم ومراعاة علامات الترقيم والتلوين الصوتي","قراءة المتعثرين أولاً لبيان الأخطاء للجميع","القراءة الصامتة الفردية دون توجيه","تسجيل صوت المتعلمين والاستماع إليه دون تعليق"]'::jsonb, 'قراءة نموذجية يقدمها الأستاذ تبين النطق السليم ومراعاة علامات الترقيم والتلوين الصوتي', 'النمذجة (Je fais) تتيح للمتعلم ملاحظة الأداء القرائي السليم الخالي من العيوب ليستند إليه في مرحلة الممارسة الموجهة والمستقلة.'),
('dar179', ARRAY['primary'], 'dar', 'التدبير الديداكتيكي', 'ما هي المراحل الأربع للإفراج التدريجي عن المسؤولية (Modèle de libération graduelle)؟', '["التهيئة والنمذجة، الممارسة الموجهة، الممارسة المستقلة، والتطبيق الإدماجي","الحفظ، الامتحان، التنقيط، والعقاب","الرسم، النقل، الخط، والإملاء","التقويم القبلي، النهائي، الشفهي، والكتابي"]'::jsonb, 'التهيئة والنمذجة، الممارسة الموجهة، الممارسة المستقلة، والتطبيق الإدماجي', 'نموذج التفويض التدريجي يقوم على: أنا أفعل (نمذجة)، نحن نفعل معاً (ممارسة موجهة)، أنتم تفعلون معاً، ثم أنت تفعل وحدك (استقلالية).'),
('dar180', ARRAY['primary'], 'dar', 'ديداكتيك الظواهر اللغوية', 'ما الترتيب المنهجي لحصة درس التراكيب في المستويين الخامس والسادس؟', '["وضعية الانطلاق وقراءة النص، الملاحظة والتحليل، الاستنتاج وبناء القاعدة، ثم التطبيق والتقويم","حفظ القاعدة في البيت أولاً ثم تسميعها في القسم","إجراء التمارين مباشرة دون تقديم أمثلة أو شواهد","كتابة الإعراب على السبورة ومطالبة التلاميذ بنقله حرفياً"]'::jsonb, 'وضعية الانطلاق وقراءة النص، الملاحظة والتحليل، الاستنتاج وبناء القاعدة، ثم التطبيق والتقويم', 'يعتمد المنهاج المقاربة الاستقرائية: الانطلاق من نص وشواهد لغوية، عزل الظاهرة وتحليلها، استنباط القاعدة وصياغتها، ثم التدريب والتطبيق.'),
('dar181', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما المعيار الديداكتيكي الأساسي لاختيار نصوص القراءة في كراسة المتعلم بالابتدائي؟', '["ملاءمة النص لمستوى نماء المتعلم وارتباطه بمجال الوحدة وتضمنه قيماً إيجابية","أن يكون النص مأخوذاً حصراً من كتب الأدب الجاهلي المعقدة","أن يخلو النص تماماً من أي كلمة جديدة أو فكرة ملهمة","أن يكون النص شديد الطول لا يقل عن عشر صفحات"]'::jsonb, 'ملاءمة النص لمستوى نماء المتعلم وارتباطه بمجال الوحدة وتضمنه قيماً إيجابية', 'تراعى شروط الدقة اللغوية، ومناسبة الموضوع للمرحلة العمرية، والانسجام مع المجال الحياتي للوحدة وقيم المواطنة وحقوق الإنسان.'),
('dar182', ARRAY['primary'], 'dar', 'مكون الاستماع والتحدث', 'ما النشاط الذي يتوج استثمار الحكاية في الأسبوع الثاني من تقديمها؟', '["تشخيص الحكاية ومسرحتها وإنتاج حكاية جديدة بتغيير إحدى الشخصيات أو الأحداث","إملاء الحكاية كاملة في دفاتر التسويد","إعراب جميع الجمل الواردة في متن الحكاية","قراءة الحكاية بصوت خافت دون أي حوار"]'::jsonb, 'تشخيص الحكاية ومسرحتها وإنتاج حكاية جديدة بتغيير إحدى الشخصيات أو الأحداث', 'مرحلة ما بعد الاستماع تستهدف الإبداع والإنتاج من خلال مسرحة المواقف وإعادة إنتاج حكايات موازية تعزز التعبير الطليق.'),
('dar183', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هو مؤشر «الدقة» في قياس الطلاقة القرائية لدى متعلم المستوى الابتدائي؟', '["قراءة الكلمات بشكل صحيح دون إبدال أو حذف أو زيادة في الحروف والحركات","القراءة بأقصى سرعة ممكنة دون الاهتمام بالنطق الصحيح","رفع الصوت عالياً جداً حتى يسمعه كل من في المؤسسة","التوقف لمدة طويلة بعد كل حرف مكتوب"]'::jsonb, 'قراءة الكلمات بشكل صحيح دون إبدال أو حذف أو زيادة في الحروف والحركات', 'الدقة القرائية تعني سلامة قراءة الحروف والمقاطع بالحركات الإعرابية التامة وتجنب الإسقاط أو التحريف الصوتي.'),
('dar184', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'كيف يتم استثمار استراتيجية «ملء الفراغات» أو «شكل الحرف الناقص» في دعم التعثر القرائي؟', '["لتدريب المتعلم على التركيب وتوقع المقاطع المناسبة واستكمال الكلمة دلالياً وخطياً","لاختبار قدرته على الرسم الهندسي","لإلغاء أهمية الحركات الإعرابية","لتفريغ وقت الحصة دون هدف بيداغوجي"]'::jsonb, 'لتدريب المتعلم على التركيب وتوقع المقاطع المناسبة واستكمال الكلمة دلالياً وخطياً', 'تساعد تمارين إكمال المقاطع الناقصة على تقوية التحليل والتركيب والربط بين الرسم الإملائي والسياق الدلالي للكلمة.'),
('dar185', ARRAY['primary'], 'dar', 'ديداكتيك الكتابة', 'ما الفرق في وظيفة حصة «الإنتاج الكتابي» بين المستويين الثالث والرابع؟', '["في الثالث تكون موجهة وبسيطة في فقرات قصيرة، بينما في الرابع تتسع للتوليد المنظم للفقرات المتعددة","في الثالث يكتب المتعلم بالقلم الرصاص وفي الرابع بالحبر فقط دون فرق ديداكتيكي","في الثالث تلغى الكتابة تماماً وتبدأ فجأة في الرابع","في الثالث يكتب مقالاً صحفياً وفي الرابع حكاية خرافية"]'::jsonb, 'في الثالث تكون موجهة وبسيطة في فقرات قصيرة، بينما في الرابع تتسع للتوليد المنظم للفقرات المتعددة', 'يتدرج التعبير الكتابي من بناء جمل وفقرات بسيطة بتوجيه ودعامات مساعدة في الثالث إلى مهارات كتابية مهيكلة في الرابع.'),
('dar186', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما المقصود باستراتيجية «المراقبة الذاتية للفهم» أثناء القراءة؟', '["وعي القارئ بمدى فهمه للنص وإدراكه لمواطن الغموض واستخدامه آليات للتوضيح كإعادة القراءة","النظر إلى المرآة أثناء القراءة لتحسين تعابير الوجه","قراءة فقرة وتخطي فقرة أخرى عشوائياً","انتظار تدخل الأستاذ لشرح كل كلمة بمفردها فوراً"]'::jsonb, 'وعي القارئ بمدى فهمه للنص وإدراكه لمواطن الغموض واستخدامه آليات للتوضيح كإعادة القراءة', 'المراقبة الذاتية مهارة ما وراء معرفية (Métacognition) تجعل المتعلم ينتبه متى انقطع حبل الفهم ليعيد القراءة أو يبحث عن سياق الكلمة.'),
('dar187', ARRAY['primary'], 'dar', 'مشروع الوحدة', 'في أي أسابيع الوحدة يتم إنجاز مراحل مشروع الوحدة بالمدرسة الابتدائية؟', '["يمتد عبر أسابيع الوحدة الخمسة من التحديد والتخطيط، إلى الإنجاز والتدقيق، ثم العرض النهائي","ينجز كاملاً في حصة واحدة في بداية السنة","ينجز في العطلة الصيفية فقط","يقتصر على حصة التقويم والدعم في الأسبوع الخامس فقط دون تحضير"]'::jsonb, 'يمتد عبر أسابيع الوحدة الخمسة من التحديد والتخطيط، إلى الإنجاز والتدقيق، ثم العرض النهائي', 'يتدرج مشروع الوحدة أسبوعياً: أ1 (التحديد والتخطيط)، أ2 وأ3 (الإنجاز والتتبع)، أ4 (إتمام الإنجاز والمراجعة)، أ5 (العرض والمقاسمة).'),
('dar188', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما المقصود بـ «المقاربة النصية» المعتمدة في تدريس اللغة العربية بالتعليم الابتدائي؟', '["اتخاذ النص محوراً ومنطلقاً جامعاً تروج من خلاله مختلف الأنشطة القرائية واللغوية والتعبيرية","حفظ النصوص الأدبية واستظهارها دون تحليل","إلغاء التواصل الشفهي والاكتفاء بقراءة الكتب المطبوعة","تدريس القواعد النحوية بشكل معزول ومجرد عن أي سياق نصي"]'::jsonb, 'اتخاذ النص محوراً ومنطلقاً جامعاً تروج من خلاله مختلف الأنشطة القرائية واللغوية والتعبيرية', 'المقاربة النصية تجعل من النص منطلقاً لتعلم اللغة وظواهرها التعبيرية والتركيبية في إطار نسقي متكامل وليس مجزأ.'),
('dar189', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هي التقنية المعتمدة لتدريب المتعلم على التمييز السمعي للأصوات المتقاربة مثل (س / ص)؟', '["الاستماع إلى أزواج دنيا وتمييز الصوت المرقق من الصوت المفخم وتحديد موقعه","مطالبته بالصمت والتوقف عن التحدث تماماً","إجراء عملية حسابية في الجمع والطرح","كتابة نص جغرافي طويل دون تشكيل"]'::jsonb, 'الاستماع إلى أزواج دنيا وتمييز الصوت المرقق من الصوت المفخم وتحديد موقعه', 'الأزواج الدنيا (Paires minimales) مثل (سار/صار، سيف/صيف) تعد أنجع وسيلة ديداكتيكية لتدريب الأذن على التمييز الصوتي الدقيق.'),
('dar190', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما وظيفة «الألعاب القرائية» في السنوات الأولى من التعليم الابتدائي؟', '["تحبيب القراءة للمتعلمين وتيسير التمرن على التركيب والتجزيء المقطعي في قالب تفاعلي ممتع","إضاعة الحصة دون تعلم حقيقي","تدريب التلاميذ على التنافس العدائي بينهم","الاستغناء عن الدفاتر والكتب نهائياً"]'::jsonb, 'تحبيب القراءة للمتعلمين وتيسير التمرن على التركيب والتجزيء المقطعي في قالب تفاعلي ممتع', 'تعتمد البيداغوجيا اللعبية في القراءة على بطاقات الكلمات والعجلة المقطعية والدومينو اللغوي لتثبيت التعلمات بمرونة وحافزية عالية.'),
('dar191', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ماذا يقصد بـ «القراءة المستقلة الذاتية» لدى متعلمي الطور المتقدم بالابتدائي؟', '["قدرة المتعلم على قراءة كتب وقصص وفهمها بمفرده خارج وداخل الفصل دون توجيه مباشر مستمر","قراءة المتعلم وهو معزول في غرفة مظلمة","ترديد الكلمات خلف المعلم فقط","قراءة الحروف المتقطعة دون فهم المعنى العام"]'::jsonb, 'قدرة المتعلم على قراءة كتب وقصص وفهمها بمفرده خارج وداخل الفصل دون توجيه مباشر مستمر', 'القراءة المستقلة هي أرقى مراتب التعلم القرائي، حيث يصبح المتعلم قارئاً ذاتياً يتمتع بالاستقلالية وحب المطالعة.'),
('dar192', ARRAY['primary'], 'dar', 'ديداكتيك الظواهر اللغوية', 'في درس التراكيب، ما دور مرحلة «الاستنتاج» في النهج الاستقرائي؟', '["صياغة وتلخيص القاعدة اللغوية المستهدفة من طرف المتعلمين بأنفسهم وبتوجيه الأستاذ","إعطاء الواجبات المنزلية بسرعة","مسح السبورة ومغادرة قاعة التدريس","حفظ نماذج إعرابية جاهزة دون تفكير"]'::jsonb, 'صياغة وتلخيص القاعدة اللغوية المستهدفة من طرف المتعلمين بأنفسهم وبتوجيه الأستاذ', 'مرحلة الاستنتاج تلي الملاحظة والتحليل، وتهدف إلى بناء القاعدة صياغةً واضحة بلسان المتعلم كحصيلة للتفكير الاستقرائي.'),
('dar193', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما هي «كفايات التواصل الشفهي» المستهدفة في السلك الابتدائي؟', '["حسن الإنصات، فهم المسموع، التعبير الشفهي الواضح، والقدرة على المحاورة وإبداء الرأي","الصراخ بصوت مرتفع لإثبات الحضور","الامتناع عن الحديث أمام الزملاء خجلاً","الاستظهار الآلي للنصوص دون فهم معناها"]'::jsonb, 'حسن الإنصات، فهم المسموع، التعبير الشفهي الواضح، والقدرة على المحاورة وإبداء الرأي', 'يرتكز التواصل الشفهي على استقبال الرسالة السمعية وفك شفرتها وتوليد استجابة شفهية سليمة متكيفة مع السياق التواصلي.'),
('dar194', ARRAY['primary'], 'dar', 'ديداكتيك الكتابة', 'ما هي معايير تقويم إنتاج تعبيري كتابي بالسنة السادسة الابتدائية؟', '["الملاءمة مع الموضوع، الانسجام وتسلسل الأفكار، سلامة اللغة، وحسن التقديم وعلامات الترقيم","طول النص بالصفحات فقط بصرف النظر عن المضمون","زخرفة الحروف بالرسومات الملونة فقط","كتابة كلمات نادرة وغير مفهومة لإبهار المصحح"]'::jsonb, 'الملاءمة مع الموضوع، الانسجام وتسلسل الأفكار، سلامة اللغة، وحسن التقديم وعلامات الترقيم', 'تعتمد شبكات التقويم معايير دقيقة: معيار الملاءمة (احترام التعليمة)، معيار الانسجام، معيار سلامة الرسم والتركيب، ومعيار الإتقان والتميز.'),
('dar195', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما المقصود بـ «القراءة الإعرابية / المعبرة»؟', '["تلوين الصوت وفق دلالات الجمل الاستفهامية والتعجبية ومراعاة التوقف عند علامات الترقيم","قراءة الحركات الإعرابية الأخيرة فقط وحذف الكلمات","إعراب كل كلمة قبل نطقها بصوت خافت","القراءة المتقطعة كلمة بكلمة مع التوقف الطويل"]'::jsonb, 'تلوين الصوت وفق دلالات الجمل الاستفهامية والتعجبية ومراعاة التوقف عند علامات الترقيم', 'القراءة المعبرة (Lecture expressive / Prosodie) تعكس فهم القارئ للمشاعر والمواقف عبر نبرة الصوت والإيقاع وعلامات الترقيم.'),
('dar196', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما هي استراتيجية «خرائط التفكير السردي» لتلخيص الحكايات والقصص؟', '["تحديد عناصر السرد: الزمان، المكان، الشخصيات، البداية، العقدة/المشكل، والحل/النهاية","إحصاء عدد النقاط والفواصل في الصفحة الأولى","تلوين صور الغلاف بألوان مائية","حذف السطر الأول والأخير من القصة فقط"]'::jsonb, 'تحديد عناصر السرد: الزمان، المكان، الشخصيات، البداية، العقدة/المشكل، والحل/النهاية', 'بنية السرد أو خطاطة القصة تساعد المتعلم على تمثيل المعمار السردي للنص بصرياً وإدراك حبكة الأحداث.'),
('dar197', ARRAY['primary'], 'dar', 'التدبير الديداكتيكي', 'كيف يساهم «التعلم بالقرين» (Peer learning) في تجويد القراءة بالسلك الابتدائي؟', '["قراءة ثنائية بين تلميذين يستمع كل منهما للآخر ويصحح له بلباقة مما يعزز الثقة والطلاقة","عقاب التلميذ الضعيف من طرف زميله المتفوق","جلوس كل تلميذ وحيداً دون أي تفاعل مع الآخرين","تبادل الدفاتر وتمزيق الصفحات المشوشة"]'::jsonb, 'قراءة ثنائية بين تلميذين يستمع كل منهما للآخر ويصحح له بلباقة مما يعزز الثقة والطلاقة', 'تتيح القراءة الثنائية (Lecture en binôme) تدريباً تفاعلياً آمناً يخفف من قلق الأداء ويزيد من وقت القراءة الفعلي لكل متعلم.'),
('dar198', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما هو الهدف من حصص «النقل» في المستويين الأول والثاني؟', '["ترسيخ الرسم الخطي الصحيح للحروف والكلمات وضبط مقاييسها ومحاذاة السطر","ملء الكراسة بسرعة للخروج إلى الساحة","تدريب التلميذ على حفظ الكلمات دون قراءتها","استبدال حصص القراءة بالرسم التجريدي"]'::jsonb, 'ترسيخ الرسم الخطي الصحيح للحروف والكلمات وضبط مقاييسها ومحاذاة السطر', 'نشاط النقل يربط الإدراك البصري بالحركي، ويدرب اليد على مقاييس الحروف والمسافات واحترام السطر والتنسيق.'),
('dar199', ARRAY['primary'], 'dar', 'ديداكتيك القراءة', 'ما دلالة استراتيجية «التلخيص» كإحدى استراتيجيات ما بعد القراءة؟', '["إعادة صياغة الأفكار الجوهرية للنص بأسلوب شخصي موجز مع استبعاد التفاصيل الثانوية","نسخ النص بأكمله بخط صغير جداً","حذف الكلمات الطويلة والإبقاء على الحروف فقط","قراءة النص من آخره إلى أوله"]'::jsonb, 'إعادة صياغة الأفكار الجوهرية للنص بأسلوب شخصي موجز مع استبعاد التفاصيل الثانوية', 'التلخيص يعكس أرقى مستويات الفهم والتحليل، حيث يقوم المتعلم بتجريد الأفكار الرئيسة والتعبير عنها بتركيب لغوي خاص ومكثف.'),
('dar200', ARRAY['primary'], 'dar', 'ديداكتيك اللغة العربية', 'ما هي الغاية النهائية الشاملة من تدريس اللغة العربية بالسلك الابتدائي في المغرب؟', '["تمكين المتعلم من التعبير السليم والاستماع الفعال والتفكير النقدي والمطالعة المستقلة والانفتاح المعرفي","إلزام المتعلم بحفظ القواعد النحوية المعقدة دون قدرة على التعبير بها","إعداده للمسابقات الإملائية الأكاديمية الصرفة فقط","فصله عن هويته الوطنية ومحيطه الاجتماعي"]'::jsonb, 'تمكين المتعلم من التعبير السليم والاستماع الفعال والتفكير النقدي والمطالعة المستقلة والانفتاح المعرفي', 'تستهدف مادة اللغة العربية بناء شخصية المتعلم الفكرية والتواصلية وتزويده بأداة التفكير والتعلم والاندماج المجتمعي.'),
('dfr151', ARRAY['primary'], 'dfr', 'Activités orales', 'Au cycle primaire, quel est le volume horaire hebdomadaire généralement alloué aux activités orales en 1re et 2e années ?', '["Quatre à cinq séances par semaine centrées sur la communication","Une seule séance de 20 minutes par mois","Aucune séance car l''écrit est prioritaire dès le premier jour","Une séance unique de grammaire théorique"]'::jsonb, 'Quatre à cinq séances par semaine centrées sur la communication', 'En 1re et 2e AEP, l''oral constitue l''ossature essentielle de l''apprentissage du français avec une fréquence quasi-quotidienne.'),
('dfr152', ARRAY['primary'], 'dfr', 'Activités orales', 'Quelles sont les trois étapes didactiques majeures d''une leçon de communication orale au primaire ?', '["Avant l''écoute (découverte), pendant l''écoute (compréhension), et après l''écoute (production/réinvestissement)","Dictée, copie, et punition corporelle","Lecture silencieuse, analyse grammaticale, et calcul mental","Traduction littérale vers la langue maternelle uniquement"]'::jsonb, 'Avant l''écoute (découverte), pendant l''écoute (compréhension), et après l''écoute (production/réinvestissement)', 'La démarche préconisée comprend la phase de découverte/anticipation, la phase de compréhension et décorticage, puis l''appropriation et le réinvestissement.'),
('dfr153', ARRAY['primary'], 'dfr', 'Activités orales', 'Dans le cadre de l''enseignement explicite de l''oral, que signifie « modéliser une situation de communication » ?', '["L''enseignant joue le dialogue ou le modèle communicatif de manière vivante et expressive pour montrer l''exemple","L''enseignant demande aux élèves de lire un livre en silence","L''enseignant écrit une longue liste de vocabulaire sans la prononcer","L''enseignant chronomètre le temps de récréation"]'::jsonb, 'L''enseignant joue le dialogue ou le modèle communicatif de manière vivante et expressive pour montrer l''exemple', 'La modélisation consiste à expliciter et dramatiser la situation langagière pour que les apprenants observent la prosodie, les mimiques et les structures cibles.'),
('dfr154', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'En lecture au primaire, qu''est-ce que la « conscience phonologique » ?', '["La capacité à identifier, manipuler et segmenter les unités sonores de la langue orale (syllabes, rimes, phonèmes)","La connaissance par cœur de la vie des auteurs classiques","L''aptitude à dessiner des lettres cursives sans rature","La mémorisation visuelle de textes documentaires complexes"]'::jsonb, 'La capacité à identifier, manipuler et segmenter les unités sonores de la langue orale (syllabes, rimes, phonèmes)', 'La conscience phonologique est la compétence métalinguistique permettant de percevoir la structure sonore des mots indépendamment de leur sens.'),
('dfr155', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Que désigne la « voie indirecte » (ou voie phonologique) dans les modèles de lecture (double voie) ?', '["Le décodage séquentiel passant par la conversion du graphème en phonème pour accéder au sens","La reconnaissance orthographique instantanée du mot sans déchiffrage","L''écoute d''un enregistrement audio les yeux fermés","La lecture du texte à l''envers de la fin vers le début"]'::jsonb, 'Le décodage séquentiel passant par la conversion du graphème en phonème pour accéder au sens', 'La voie indirecte ou phonologique repose sur l''application rigoureuse des règles de conversion grapho-phonémique (CGP).'),
('dfr156', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Que désigne la « voie directe » (ou voie lexicale / orthographique) dans la lecture experte ?', '["L''accès immédiat au sens et à la prononciation du mot stocké dans le lexique mental sans passer par le découpage","L''épellation lettre par lettre à voix haute","L''apprentissage exclusif des lettres de l''alphabet à l''écrit","La traduction par dictionnaire bilingue"]'::jsonb, 'L''accès immédiat au sens et à la prononciation du mot stocké dans le lexique mental sans passer par le découpage', 'La voie directe permet une reconnaissance visuelle instantanée des mots familiers, condition indispensable à une fluence optimale.'),
('dfr157', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Parmi les activités suivantes, laquelle développe directement la conscience syllabique chez l''enfant ?', '["Frapper dans les mains le nombre de syllabes contenues dans un mot (ex: « ba-na-ne » -> 3 frappes)","Recopier une page d''histoire dans le cahier du jour","Apprendre la table de multiplication de 7","Chercher un verbe du 3e groupe au subjonctif"]'::jsonb, 'Frapper dans les mains le nombre de syllabes contenues dans un mot (ex: « ba-na-ne » -> 3 frappes)', 'La segmentation et le comptage kinesthésique (frappes) des syllabes orales sont des piliers du développement de la conscience syllabique.'),
('dfr158', ARRAY['primary'], 'dfr', 'Didactique de l''écriture', 'Dans l''apprentissage du graphisme et de l''écriture en 1re AEP, quel est le rôle des « gestes graphiques préparatoires » ?', '["Développer la motricité fine, la coordination œil-main et l''orientation spatiale (traits, ronds, ponts, boucles)","Apprendre à rédiger des dissertations philosophiques","Faire mémoriser les règles de grammaire par écrit","Remplacer les activités sportives et de récréation"]'::jsonb, 'Développer la motricité fine, la coordination œil-main et l''orientation spatiale (traits, ronds, ponts, boucles)', 'Les exercices graphiques préparent la main à exécuter avec fluidité et précision les tracés de base nécessaires à l''écriture cursive.'),
('dfr159', ARRAY['primary'], 'dfr', 'Didactique de l''écriture', 'Quelle est la progression recommandée pour l''apprentissage de l''écriture cursive au cycle primaire ?', '["Tracé dans l''air et bac à sable, ardoise avec interlignes agrandis, puis cahier d''écriture à interlignes Seyès","Cahier à petites lignes directement sans aucune préparation","Clavier d''ordinateur uniquement sans toucher au stylo","Dictée de phrases complexes dès la première semaine"]'::jsonb, 'Tracé dans l''air et bac à sable, ardoise avec interlignes agrandis, puis cahier d''écriture à interlignes Seyès', 'La démarche va du geste large et corporel vers le support grand format, pour aboutir au calibrage fin sur le lignage standard Seyès.'),
('dfr160', ARRAY['primary'], 'dfr', 'Activités de langue', 'Quelle est la démarche pédagogique préconisée pour enseigner la grammaire et la conjugaison aux niveaux 4, 5 et 6 AEP ?', '["Une démarche inductive : observation/découverte, manipulation/analyse, conceptualisation (règle), application et évaluation","Une démarche déductive imposant la règle par cœur avant tout exemple","La copie systématique de dictionnaires pendant 45 minutes","La suppression totale des leçons de langue"]'::jsonb, 'Une démarche inductive : observation/découverte, manipulation/analyse, conceptualisation (règle), application et évaluation', 'La démarche inductive part du corpus textuel manipulé par l''élève pour le conduire à dégager et formuler activement la règle de fonctionnement.'),
('dfr161', ARRAY['primary'], 'dfr', 'Activités de langue', 'Dans une leçon de langue selon la démarche active, quel est l''objectif de la phase de « manipulation » ?', '["Permettre aux élèves de tester des permutations, substitutions et transformations pour identifier les régularités","Distribuer les fournitures scolaires en silence","Faire réciter la poésie de la semaine","Corriger les devoirs de mathématiques"]'::jsonb, 'Permettre aux élèves de tester des permutations, substitutions et transformations pour identifier les régularités', 'Les manipulations syntaxiques (déplacement, remplacement, suppression, ajout) rendent visible le rôle des éléments dans la phrase.'),
('dfr162', ARRAY['primary'], 'dfr', 'Production de l''écrit', 'En production de l''écrit aux 5e et 6e AEP, pourquoi préconise-t-on l''usage d''un « premier jet » (brouillon) ?', '["Pour décharger l''apprenant de la perfection immédiate et l''encourager à rédiger librement avant révision","Pour gaspiller du papier inutilement","Pour punir les élèves qui écrivent trop lentement","Pour remplacer la note de l''examen final"]'::jsonb, 'Pour décharger l''apprenant de la perfection immédiate et l''encourager à rédiger librement avant révision', 'Le premier jet sépare la génération d''idées de la mise en forme orthographique et syntaxique, favorisant la réécriture réflexive.'),
('dfr163', ARRAY['primary'], 'dfr', 'Production de l''écrit', 'Comment l''enseignant peut-il aider les élèves à réviser et améliorer leur premier jet en production écrite ?', '["En fournissant une grille d''auto-évaluation critériée et en animant un atelier de négociation textuelle","En réécrivant lui-même le texte à la place de l''élève sans rien expliquer","En déchirant la copie des élèves qui ont fait des fautes","En mettant un zéro sans annotations constructives"]'::jsonb, 'En fournissant une grille d''auto-évaluation critériée et en animant un atelier de négociation textuelle', 'Une grille d''auto-évaluation guide l''élève sur les points à corriger (majuscules, accords, connecteurs, clarté) en favorisant son autonomie.'),
('dfr164', ARRAY['primary'], 'dfr', 'Projet de classe', 'Quelle est la vocation pédagogique du « Projet de classe » au cycle primaire marocain ?', '["Fédérer les apprentissages linguistiques autour d''une réalisation collective concrète et valorisante","Organiser une compétition individuelle payante entre les classes","Dispenser l''école des cours de français","Préparer un spectacle de fin d''année sans lien avec le programme"]'::jsonb, 'Fédérer les apprentissages linguistiques autour d''une réalisation collective concrète et valorisante', 'Le projet de classe donne du sens aux apprentissages scolaires en intégrant la communication, la recherche, l''écrit et le travail coopératif.'),
('dfr165', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Qu''est-ce qu''un texte « injonctif » fréquemment étudié au primaire ?', '["Un texte qui donne des ordres, des conseils ou des instructions à suivre (recette de cuisine, notice de montage)","Un poème rimé sur la nature","Un récit de fiction avec des dragons et des fées","Un article de dictionnaire expliquant l''étymologie"]'::jsonb, 'Un texte qui donne des ordres, des conseils ou des instructions à suivre (recette de cuisine, notice de montage)', 'Le texte injonctif ou prescriptif utilise couramment l''impératif ou l''infinitif pour guider l''action du destinataire.'),
('dfr166', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Quelle est la spécificité textuelle du texte « narratif » au primaire ?', '["Il relate une succession d''événements réels ou imaginaires organisés selon un schéma narratif chronologique","Il décrit minutieusement un paysage immobile sans aucune action","Il donne la notice technique de fabrication d''un moteur d''avion","Il expose des arguments pour convaincre un auditoire politique"]'::jsonb, 'Il relate une succession d''événements réels ou imaginaires organisés selon un schéma narratif chronologique', 'Le texte narratif met en scène des personnages dans un cadre spatio-temporel donné avec une situation initiale, un élément déclencheur, des péripéties et un dénouement.'),
('dfr167', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Que vise la technique de lecture appelée « lecture silencieuse sélective ou de repérage » (Scanning) ?', '["Rechercher rapidement une information précise dans le texte (un nom propre, une date, un chiffre) sans tout lire","Lire le texte en articulant chaque mot à voix haute sans respirer","Traduire le premier paragraphe uniquement","Compter le nombre de voyelles dans le titre"]'::jsonb, 'Rechercher rapidement une information précise dans le texte (un nom propre, une date, un chiffre) sans tout lire', 'Le balayage visuel (scanning) permet à l''apprenant d''extraire efficacement une donnée ciblée sans surcharge cognitive.'),
('dfr168', ARRAY['primary'], 'dfr', 'Évaluation et remédiation', 'Qu''est-ce qu''une « erreur interférentielle » chez un apprenant marocain apprenant le français ?', '["Une erreur résultant du transfert négatif d''une structure de la langue maternelle (arabe ou amazighe) vers le français","Une faute due à la fatigue physique en fin de journée","Une erreur intentionnelle pour défier l''enseignant","Une faute typographique commise par l''imprimeur du manuel"]'::jsonb, 'Une erreur résultant du transfert négatif d''une structure de la langue maternelle (arabe ou amazighe) vers le français', 'L''interférence linguistique (ex: « la table à mon père » ou l''omission d''articles) s''explique par le calque syntaxique ou phonétique de la L1.'),
('dfr169', ARRAY['primary'], 'dfr', 'Évaluation et remédiation', 'Face à une erreur récurrente de prononciation du son [p] confondu avec [b], quelle stratégie didactique est la plus appropriée ?', '["Faire ressentir kinesthésiquement l''absence de vibration des cordes vocales pour [p] (son sourd) versus [b] (son sonore)","Priver l''élève de récréation jusqu''à ce qu''il prononce correctement","Ignorer l''erreur car la phonétique n''a aucune importance en langue étrangère","Lui faire copier cent fois le mot « poupée » sans le faire parler"]'::jsonb, 'Faire ressentir kinesthésiquement l''absence de vibration des cordes vocales pour [p] (son sourd) versus [b] (son sonore)', 'La méthode verbo-tonale et la prise de conscience motrice (toucher la gorge pour sentir les vibrations) corrigent efficacement ce contraste phonologique.'),
('dfr170', ARRAY['primary'], 'dfr', 'Didactique du lexique', 'Quelle activité permet d''enrichir le vocabulaire thématique des élèves de manière structurée ?', '["La construction d''une carte mentale (champ lexical) regroupant mots dérivés, synonymes et expressions du thème","La mémorisation par ordre alphabétique d''un dictionnaire médical","La lecture rapide de phrases sans queue ni tête","L''interdiction de poser des questions sur le sens des mots"]'::jsonb, 'La construction d''une carte mentale (champ lexical) regroupant mots dérivés, synonymes et expressions du thème', 'Le réseau sémantique visuel (carte heuristique) aide à ancrer les nouveaux vocables dans la mémoire à long terme par association d''idées.'),
('dfr171', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Dans le cadre de l''évaluation de la lecture à voix haute, que mesure le score MCLM ?', '["Le nombre de Mots Correctement Lus en une Minute","La Moyenne des Cahiers Lus le Matin","Le Maximum de Cartes de Langue Mémorisées","La Mention de Compréhension de la Littérature Moderne"]'::jsonb, 'Le nombre de Mots Correctement Lus en une Minute', 'Le test MCLM (Mots Correctement Lus par Minute) est le standard international pour quantifier la vitesse et la précision du décodage.'),
('dfr172', ARRAY['primary'], 'dfr', 'Didactique de l''orthographe', 'Quelle est la différence fondamentale entre l''orthographe lexicale (d''usage) et l''orthographe grammaticale ?', '["L''orthographe lexicale dépend de la mémoire du mot (ex: « oiseau »), tandis que la grammaticale dépend des règles d''accord (ex: « les oiseaux chantent »)","L''orthographe d''usage s''applique aux nombres et la grammaticale aux verbes","L''orthographe lexicale ne s''apprend jamais à l''école primaire","Il n''y a aucune différence, ce sont deux termes synonymes"]'::jsonb, 'L''orthographe lexicale dépend de la mémoire du mot (ex: « oiseau »), tandis que la grammaticale dépend des règles d''accord (ex: « les oiseaux chantent »)', 'L''orthographe d''usage fixe la graphie conventionnelle d''un mot, tandis que l''orthographe grammaticale régit les accords en genre, nombre et personnes dans la phrase.'),
('dfr173', ARRAY['primary'], 'dfr', 'Didactique de l''orthographe', 'Qu''est-ce qu''une « dictée négociée » (ou dictée dialoguée) en classe de français ?', '["Un exercice où les élèves confrontent leurs justifications orthographiques en petits groupes avant d''établir une version commune","Un marchandage avec l''enseignant pour supprimer la moitié des phrases dictées","Une dictée où les élèves ont le droit de regarder la correction sur le tableau","Une dictée lue par un magnétophone à vitesse accélérée"]'::jsonb, 'Un exercice où les élèves confrontent leurs justifications orthographiques en petits groupes avant d''établir une version commune', 'La dictée négociée stimule les métacognitions orthographiques en obligeant les apprenants à argumenter sur les accords et règles.'),
('dfr174', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Pourquoi est-il préjudiciable de demander aux élèves de suivre avec le doigt au-delà de la phase de déchiffrage initial ?', '["Car le pointage au doigt ralentit l''empan visuel et freine le développement d''une lecture fluide par groupes de mots","Car cela salit les pages du livre avec l''encre","Car le programme officiel interdit strictement l''usage des mains","Car le doigt empêche les autres élèves de regarder le tableau"]'::jsonb, 'Car le pointage au doigt ralentit l''empan visuel et freine le développement d''une lecture fluide par groupes de mots', 'Le suivi au doigt maintient l''enfant dans un déchiffrage mot à mot, alors que la lecture fluide requiert des saccades oculaires englobant des syntagmes.'),
('dfr175', ARRAY['primary'], 'dfr', 'Didactique du FLE', 'Dans l''approche actionnelle (CECRL), comment est défini l''apprenant de langue étrangère ?', '["Comme un acteur social accomplissant des tâches communicatives authentiques dans un contexte donné","Comme un récepteur passif qui mémorise des listes de règles de grammaire","Comme un traducteur littéraire professionnel","Comme un imitateur parfait sans initiative personnelle"]'::jsonb, 'Comme un acteur social accomplissant des tâches communicatives authentiques dans un contexte donné', 'La perspective actionnelle privilégie la réalisation de projets et de tâches concrètes où la langue est un instrument d''action sociale.'),
('dfr176', ARRAY['primary'], 'dfr', 'Didactique de la poésie', 'Quel est l''objectif prioritaire d''une séance de poésie/diction au primaire ?', '["Sensibiliser à la musicalité de la langue, travailler la diction, l''intonation et libérer l''émotion esthétique","Analyser rigoureusement toutes les fonctions grammaticales de chaque vers","Obliger les élèves à copier le poème vingt fois sans faute","Transformer la poésie en formule mathématique"]'::jsonb, 'Sensibiliser à la musicalité de la langue, travailler la diction, l''intonation et libérer l''émotion esthétique', 'La récitation poétique développe l''expressivité orale, le rythme et le plaisir de jouer avec les sonorités de la langue française.'),
('dfr177', ARRAY['primary'], 'dfr', 'Gestion de classe en FLE', 'Que préconise la pédagogie différenciée lors d''une séance de lecture en classe hétérogène ?', '["Adapter les tâches et les aides (longueur du texte, guidage, étayage) selon les besoins des différents profils d''élèves","Enseigner au rythme des deux meilleurs élèves et abandonner le reste de la classe","Donner le même exercice standard sans aucun accompagnement pour tous","Séparer définitivement les élèves faibles dans un couloir sombre"]'::jsonb, 'Adapter les tâches et les aides (longueur du texte, guidage, étayage) selon les besoins des différents profils d''élèves', 'La différenciation pédagogique propose des itinéraires diversifiés (contenus, processus, productions) pour conduire tous les élèves aux mêmes compétences socles.'),
('dfr178', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Qu''est-ce qu''une question de compréhension « inférentielle » sur un texte narratif ?', '["Une question dont la réponse n''est pas écrite mot à mot mais doit être déduite en croisant les indices du texte et les connaissances du lecteur","Une question dont la réponse se trouve soulignée en gras à la ligne 1","Une question portant sur la date de naissance de l''imprimeur","Une question demandant de compter le nombre total de lettres de l''alphabet"]'::jsonb, 'Une question dont la réponse n''est pas écrite mot à mot mais doit être déduite en croisant les indices du texte et les connaissances du lecteur', 'Les inférences exigent du lecteur de combler les blancs du texte en établissant des liens logiques et psychologiques implicites.'),
('dfr179', ARRAY['primary'], 'dfr', 'Didactique de l''écriture', 'À quelle étape de la production écrite intervient l''activité de « toilettage du texte » (réécriture/mise au propre) ?', '["En phase finale après révision, corrections orthographiques et validation par l''enseignant ou les pairs","Avant même d''avoir réfléchi au sujet d''écriture","Dès la première minute de la séance sur le brouillon","Pendant la récréation sans relecture"]'::jsonb, 'En phase finale après révision, corrections orthographiques et validation par l''enseignant ou les pairs', 'La mise au propre et le toilettage interviennent quand le texte a été structuré et corrigé, prêt à être édité ou partagé.'),
('dfr180', ARRAY['primary'], 'dfr', 'Activités orales', 'Dans les premiers apprentissages oraux, quel est l''intérêt didactique des « comptines et chansons rythmées » ?', '["Elles facilitent l''imprégnation auditive, l''assimilation des structures syntaxiques et l''articulation grâce au rythme et aux rimes","Elles servent uniquement à calmer le bruit sans aucune valeur d''apprentissage","Elles remplacent totalement l''évaluation certificative du trimestre","Elles apprennent à écrire à la plume d''oie"]'::jsonb, 'Elles facilitent l''imprégnation auditive, l''assimilation des structures syntaxiques et l''articulation grâce au rythme et aux rimes', 'Les comptines fixent les mélodies intonatives et les schémas phonétiques de la langue étrangère de façon ludique et mémorisable.'),
('dfr181', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Dans le décodage en 2e AEP, comment nomme-t-on la fusion d''une consonne et d''une voyelle (ex : [l] + [a] = [la]) ?', '["La combinatoire (ou fusion syllabique)","L''accord grammatical en genre","La conjugaison passive","La transformation interrogative"]'::jsonb, 'La combinatoire (ou fusion syllabique)', 'La combinatoire est le mécanisme clé qui permet de fusionner les phonèmes pour produire des syllabes puis des mots déchiffrables.'),
('dfr182', ARRAY['primary'], 'dfr', 'Didactique du lexique', 'Que vise l''étude des « familles de mots » au cycle primaire ?', '["Faire comprendre la dérivation lexicale par préfixation et suffixation à partir d''un radical commun","Classer les mots selon l''âge des personnes de la famille","Apprendre uniquement les noms des membres de la parenté","Supprimer les synonymes de la langue française"]'::jsonb, 'Faire comprendre la dérivation lexicale par préfixation et suffixation à partir d''un radical commun', 'La morphologie dérivationnelle permet d''étendre le lexique en observant la construction des mots (ex: dent, dentiste, dentifrice, édenté).'),
('dfr183', ARRAY['primary'], 'dfr', 'Activités de langue', 'Pourquoi est-il déconseillé d''enseigner des règles de grammaire par le métalangage abstrait en 4e AEP ?', '["Car l''enfant de 9 ans a besoin d''exemples concrets et de manipulations avant d''appréhender des étiquettes terminologiques complexes","Parce que les manuels scolaires n''ont pas de pages de grammaire","Parce que la grammaire est inutile pour parler français","Parce que le ministère l''a totalement supprimée des concours"]'::jsonb, 'Car l''enfant de 9 ans a besoin d''exemples concrets et de manipulations avant d''appréhender des étiquettes terminologiques complexes', 'Le développement cognitif au primaire exige une approche fonctionnelle et opératoire du fonctionnement de la langue plutôt que des cours théoriques formels.'),
('dfr184', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Quel rôle joue l''image accompagnant un texte de lecture en 1re et 2e AEP ?', '["Un étayage visuel indispensable pour formuler des hypothèses de sens et faciliter la compréhension","Une simple décoration sans aucune fonction pédagogique","Un moyen de cacher les fautes de frappe de l''imprimeur","Un exercice de peinture à faire à la maison"]'::jsonb, 'Un étayage visuel indispensable pour formuler des hypothèses de sens et faciliter la compréhension', 'L''image sert de tremplin iconique pour contextualiser la situation d''énonciation et aider au décryptage du message écrit.'),
('dfr185', ARRAY['primary'], 'dfr', 'Production de l''écrit', 'Comment organiser une activité d''écriture guidée en 3e année primaire ?', '["À partir d''un canevas à compléter, d''images séquentielles ou d''une boîte de mots ordonnée","En exigeant un roman de 50 pages rédigé individuellement sans aide","En recopiant un article de loi constitutionnelle","En dictant sans interruption pendant deux heures"]'::jsonb, 'À partir d''un canevas à compléter, d''images séquentielles ou d''une boîte de mots ordonnée', 'L''écriture guidée fournit des tuteurs (mots outils, structures inductrices, images) qui allègent la tâche et sécurisent l''apprenant.'),
('dfr186', ARRAY['primary'], 'dfr', 'Didactique du FLE', 'Dans le cadre de l''approche communicative, quelle importance accorde-t-on au statut de l''erreur ?', '["L''erreur est considérée comme un témoin positif de l''activité cognitive de l''élève et une étape normale de l''apprentissage","L''erreur est une faute grave qui doit être systématiquement sanctionnée par une punition","L''erreur montre que l''élève ne sera jamais capable d''apprendre une langue","L''erreur doit être dissimulée aux inspecteurs de l''éducation"]'::jsonb, 'L''erreur est considérée comme un témoin positif de l''activité cognitive de l''élève et une étape normale de l''apprentissage', 'La didactique moderne envisage l''erreur comme une hypothèse transitoire (interlangue) sur laquelle bâtir la remédiation constructive.'),
('dfr187', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Quelle est la définition d''un texte « informatif ou documentaire » au cycle primaire ?', '["Un texte qui transmet des savoirs et explications vérifiables sur un sujet du monde réel (animaux, sciences, histoire)","Un conte merveilleux avec des animaux qui parlent","Une fable morale écrite en vers rimés","Une annonce publicitaire de vente de bonbons"]'::jsonb, 'Un texte qui transmet des savoirs et explications vérifiables sur un sujet du monde réel (animaux, sciences, histoire)', 'Le texte informatif enrichit la culture générale de l''élève en décrivant des faits objectifs avec un lexique précis et scientifique.'),
('dfr188', ARRAY['primary'], 'dfr', 'Didactique de l''orthographe', 'Quelle stratégie favorise la fixation orthographique des mots invariables (toujours, jamais, beaucoup, souvent) ?', '["L''apprentissage régulier par la mémoire visuelle, l''épellation et l''écriture répétée en contexte de phrases","La recherche de leur terminaison au féminin","L''application des règles d''accord avec le sujet","L''utilisation d''une calculette scientifique"]'::jsonb, 'L''apprentissage régulier par la mémoire visuelle, l''épellation et l''écriture répétée en contexte de phrases', 'Les mots invariables ne répondant pas à une logique flexionnelle, ils doivent être stockés dans le lexique orthographique par réactivation fréquente.'),
('dfr189', ARRAY['primary'], 'dfr', 'Évaluation en FLE', 'Qu''est-ce qu''une grille de correction avec critères minimaux et critères de perfectionnement selon De Ketele ?', '["Les critères minimaux conditionnent la réussite (pertinence, correction), les critères de perfectionnement valorisent l''originalité et le style","Une grille où tous les critères valent 0 point","Un barème qui note uniquement la propreté de l''écriture","Un examen éliminatoire sans seconde chance"]'::jsonb, 'Les critères minimaux conditionnent la réussite (pertinence, correction), les critères de perfectionnement valorisent l''originalité et le style', 'La règle des 2/3 des points affectée aux critères minimaux assure la maîtrise socle, tandis que les critères de perfectionnement départagent l''excellence.'),
('dfr190', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Qu''est-ce que « l''anticipation » dans la lecture active d''un texte ?', '["Émettre des hypothèses sur le contenu ou la suite du texte à partir du titre, des illustrations et du contexte","Sauter les trois dernières pages du livre pour finir plus vite","Lire le texte avant le maître pendant la nuit","Deviner la note que l''enseignant va attribuer"]'::jsonb, 'Émettre des hypothèses sur le contenu ou la suite du texte à partir du titre, des illustrations et du contexte', 'L''anticipation mobilise le schéma cognitif du lecteur et maintient son attention active pour valider ou infirmer ses prédictions.'),
('dfr191', ARRAY['primary'], 'dfr', 'Activités orales', 'Quel dispositif favorise le plus la prise de parole spontanée des élèves timides en classe de français ?', '["Le travail en petits groupes ou en binômes coopératifs avec des tâches stimulantes et rassurantes","L''interrogation magistrale devant toute la classe sous la menace d''une mauvaise note","L''interdiction de parler sans avoir été désigné par tirage au sort","L''obligation de parler uniquement à voix très basse"]'::jsonb, 'Le travail en petits groupes ou en binômes coopératifs avec des tâches stimulantes et rassurantes', 'Le petit groupe réduit le filtre affectif et la peur du jugement, multipliant le temps de parole effectif de chaque élève.'),
('dfr192', ARRAY['primary'], 'dfr', 'Didactique de la conjugaison', 'Quelle difficulté majeure rencontrent les apprenants arabophones lors de l''apprentissage du passé composé en français ?', '["Le choix de l''auxiliaire (être ou avoir) et l''accord du participe passé, notions inexistantes dans le système verbal arabe","Le fait que les verbes français soient tous invariables","L''absence totale de voyelles dans les temps du passé","La prononciation des pronoms personnels sujets"]'::jsonb, 'Le choix de l''auxiliaire (être ou avoir) et l''accord du participe passé, notions inexistantes dans le système verbal arabe', 'L''arabe utilise une forme synthétique simple pour le passé (المتعلق بالفعل الماضي), ce qui rend le maniement de deux éléments verbaux (auxiliaire + participe) complexe.'),
('dfr193', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'Que désigne la « prosodie » dans la lecture à voix haute ?', '["L''ensemble des traits oraux comprenant l''intonation, le rythme, l''accentuation et le respect des pauses expressives","Le nombre total de mots compliqués présents dans le dictionnaire","La couleur de la couverture du manuel scolaire","Le volume sonore mesuré en décibels par un appareil électronique"]'::jsonb, 'L''ensemble des traits oraux comprenant l''intonation, le rythme, l''accentuation et le respect des pauses expressives', 'Une bonne prosodie est la signature d''une compréhension en temps réel, car l''intonation traduit le découpage syntaxique et le ton du texte.'),
('dfr194', ARRAY['primary'], 'dfr', 'Production de l''écrit', 'Pourquoi est-il utile de faire produire des écrits courts (jogging d''écriture) quotidiennement ?', '["Pour automatiser les gestes grapho-moteurs, désinhiber le rapport à l''écrit et renforcer la confiance rédactionnelle","Pour occuper les élèves pendant que le maître téléphone","Pour remplir les cahiers afin de satisfaire les parents d''élèves","Pour remplacer complètement les cours de lecture"]'::jsonb, 'Pour automatiser les gestes grapho-moteurs, désinhiber le rapport à l''écrit et renforcer la confiance rédactionnelle', 'Le jogging d''écriture quotidien (5 à 10 minutes) dédramatise l''acte d''écrire et habitue l''apprenant à formuler rapidement sa pensée.'),
('dfr195', ARRAY['primary'], 'dfr', 'Didactique du lexique', 'Comment aborder l''étude des « homonymes » (ex : vert, verre, ver, vers) à l''école primaire ?', '["En s''appuyant sur le sens en contexte de phrases pour distinguer la graphie et la fonction grammaticale","En interdisant d''utiliser ces mots dans les conversations","En les apprenant uniquement par récitation sans jamais les écrire","En affirmant que tous ces mots signifient exactement la même chose"]'::jsonb, 'En s''appuyant sur le sens en contexte de phrases pour distinguer la graphie et la fonction grammaticale', 'Les homonymes partageant la même phonie, seul le recours au contexte sémantique et syntaxique permet d''identifier l''orthographe appropriée.'),
('dfr196', ARRAY['primary'], 'dfr', 'Didactique du FLE', 'Qu''appelle-t-on le « bain linguistique » en didactique des langues vivantes ?', '["L''exposition maximale et régulière des apprenants à des situations authentiques et riches d''écoute et d''expression en langue cible","Un exercice de natation pratiqué en langue française","La mémorisation passive de règles sans jamais entendre de locuteur","La traduction intégrale du cours en langue maternelle"]'::jsonb, 'L''exposition maximale et régulière des apprenants à des situations authentiques et riches d''écoute et d''expression en langue cible', 'L''immersion ou bain linguistique fournit les inputs compréhensibles (Krashen) nécessaires à l''imprégnation naturelle de la langue.'),
('dfr197', ARRAY['primary'], 'dfr', 'Didactique de la lecture', 'À quelle étape de la leçon de lecture vérifie-t-on la validité des hypothèses émises par les élèves au début ?', '["Après la première lecture magistrale ou silencieuse globale du texte","Avant même d''ouvrir le manuel scolaire","Trois mois après la fin de l''unité didactique","Cette vérification n''est jamais effectuée"]'::jsonb, 'Après la première lecture magistrale ou silencieuse globale du texte', 'La validation ou réfutation des hypothèses de sens s''effectue immédiatement après le premier contact global avec le texte pour confirmer le sens général.'),
('dfr198', ARRAY['primary'], 'dfr', 'Didactique de l''écriture', 'Quel est l''intérêt de la « copie active » par rapport à la copie servile lettre par lettre au primaire ?', '["L''élève mémorise un groupe de mots ayant du sens avant de l''écrire sans regarder le modèle à chaque lettre","L''élève recopie le texte les yeux fermés","L''élève photocopie la page chez le libraire","L''élève dicte à son camarade sans écrire lui-même"]'::jsonb, 'L''élève mémorise un groupe de mots ayant du sens avant de l''écrire sans regarder le modèle à chaque lettre', 'La copie active ou différée exerce l''empan visuo-spatial et la mémoire de travail en contraignant l''élève à traiter des unités porteuses de sens.'),
('dfr199', ARRAY['primary'], 'dfr', 'Évaluation et remédiation', 'Dans le cycle primaire, comment s''organise la semaine de consolidation et de soutien (semaine 5 de chaque unité) ?', '["Elle est consacrée à l''évaluation des acquis, au diagnostic des lacunes et à des activités de soutien différencié","Elle est réservée uniquement au repos et aux jeux sans travail scolaire","Elle sert à anticiper le programme de l''année scolaire suivante","Elle consiste à refaire exactement tous les examens depuis le début"]'::jsonb, 'Elle est consacrée à l''évaluation des acquis, au diagnostic des lacunes et à des activités de soutien différencié', 'La 5e semaine permet de mesurer les compétences visées par l''unité didactique et d''apporter les remédiations ciblées aux élèves en difficulté.'),
('dfr200', ARRAY['primary'], 'dfr', 'Finalités de l''enseignement du français', 'Quelle est la finalité majeure de l''enseignement du français à l''école primaire marocaine ?', '["Doter l''apprenant d''une compétence de communication orale et écrite fonctionnelle lui permettant de s''exprimer et d''accéder aux savoirs","Transformer chaque élève en linguiste spécialiste de la grammaire historique","Remplacer les langues officielles nationales","Préparer uniquement à des concours de traduction simultanée"]'::jsonb, 'Doter l''apprenant d''une compétence de communication orale et écrite fonctionnelle lui permettant de s''exprimer et d''accéder aux savoirs', 'Le français est enseigné en tant que langue étrangère d''ouverture et langue d''apprentissage de disciplines scientifiques (DNL) dans le cursus ultérieur.'),
('dma151', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما هو المبدأ الأساسي الذي تقوم عليه النظومة العشرية الموضعية لتدريس الأعداد بالسلك الابتدائي؟', '["قيمة الرقم تتحدد بموضعه وموقعه في العدد، وكل انتقال برتبة نحو اليسار يضاعف القيمة بعشر مرات","قيمة الرقم ثابتة لا تتغير مهما تغير موقعه في العدد","الاعتماد على نظام الأساس الستيني فقط في قراءة الأعداد الصحيحة","جمع الأرقام المكونة للعدد دون اعتبار للمنازل"]'::jsonb, 'قيمة الرقم تتحدد بموضعه وموقعه في العدد، وكل انتقال برتبة نحو اليسار يضاعف القيمة بعشر مرات', 'النظام العشري الموضعي يرتكز على التجميع بالعشرات والتبادل، حيث يمثل كل رقم قوة للعدد 10 حسب منزلته (وحدات، عشرات، مئات...).'),
('dma152', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'لماذا يُوصى ديداكتيكياً باستعمال «جدول العد» والمكعبات وقضبان العشرات في بناء مفهوم العدد بالسنوات الأولى؟', '["لتجسيد الانتقال الحسي من الملموس وشبه المحسوس نحو التجريد الرياضي والرمز المكتوب","لتسلية المتعلم وإشغاله باللعب الترفيهي دون هدف رياضي","لأن المنهاج يمنع كتابة الأرقام على السبورة","لحفظ الأعداد من 1 إلى 100 في حصة واحدة"]'::jsonb, 'لتجسيد الانتقال الحسي من الملموس وشبه المحسوس نحو التجريد الرياضي والرمز المكتوب', 'تؤكد النظريات البنائية (برونر وبياجه) أن بناء مفهوم العدد يمر عبر ثلاثة أطوار: الطور العيني/المجسم، الطور شبه المحسوس (التمثيل بالرسم)، ثم الطور الرمزي المجرد.'),
('dma153', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما هو العائق الديداكتيكي الشائع لدى المتعلم عند دراسة «الأعداد العشرية»؟', '["اعتبار الجزء العشري عدداً صحيحاً مستقلاً والقول خطأً بأن 3.12 أكبر من 3.5 لأن 12 أكبر من 5","حفظ جدول الضرب في مدة قصيرة جداً","رسم الدائرة بالبركار بدقة عالية","التفريق بين المستقيم والقطعة المستقيمة"]'::jsonb, 'اعتبار الجزء العشري عدداً صحيحاً مستقلاً والقول خطأً بأن 3.12 أكبر من 3.5 لأن 12 أكبر من 5', 'هذا العائق ناتج عن تمديد خصائص الأعداد الصحيحة الطبيعية إلى حقل الأعداد العشرية دون استيعاب القيمة المكانية للأعشار وأجزاء المئة.'),
('dma154', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما المدخل الديداكتيكي الأنسب لتقديم مفهوم «الكسور» في السنة الرابعة الابتدائية؟', '["انطلاقاً من تجزيء وحدة قياس متصلة أو متقطعة (قرص، شريط، مجموعة عناصر) إلى أجزاء متساوية متكافئة","حفظ قواعد قسمة الكسور المعقدة مباشرة","كتابة بسط ومقام على السبورة ومطالبة التلاميذ بنقله دون نمذجة حسية","تدريس الأعداد العقدية أولاً"]'::jsonb, 'انطلاقاً من تجزيء وحدة قياس متصلة أو متقطعة (قرص، شريط، مجموعة عناصر) إلى أجزاء متساوية متكافئة', 'يبنى مفهوم الكسر كعلاقة بين الجزء والكل (Partage équitable) عبر طي وتجزيء الأشرطة والأشكال الهندسية المتساوية الأجزاء.'),
('dma155', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما مصدر الخطأ الشهير في جمع كسرين: 1/2 + 1/3 = 2/5 ؟', '["تطبيق غير مبرر لخاصية جمع الأعداد الطبيعية بجمع البسط مع البسط والمقام مع المقام مباشرة","صعوبة قراءة الأرقام المكتوبة بخط صغير","عدم معرفة عملية الجمع البسيطة","خلط المتعلم بين الجمع والطرح"]'::jsonb, 'تطبيق غير مبرر لخاصية جمع الأعداد الطبيعية بجمع البسط مع البسط والمقام مع المقام مباشرة', 'يقع التلميذ في خطأ الجمع الخطي للبسوط والمقامات لغياب تمثل معنى الكسر وضرورة توحيد المقامات للتعبير عن أجزاء من نفس الوحدة.'),
('dma156', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'كيف يُقدَّم مفهوم «الضرب» كعملية حسابية في المستويين الثاني والثالث؟', '["كحساب تراكمي لمجموع حدود متساوية متكررة (الجمع المتكرر) أو كتنظيم شبكي مستطيل","بحفظ جداول الضرب عن ظهر قلب قبل فهم المعنى","كعملية طرح متكرر للواحد","بقسمة العدد الكبير على العدد الصغير"]'::jsonb, 'كحساب تراكمي لمجموع حدود متساوية متكررة (الجمع المتكرر) أو كتنظيم شبكي مستطيل', 'يُبنى الضرب ديداكتيكياً عبر وضعيات الجمع المتكرر (3 + 3 + 3 + 3 = 4 × 3) والشبكات التربيعية لتثبيت المعنى قبل الحفظ الآلي.'),
('dma157', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما هي المراحل المتدرجة لبناء خوارزمية القسمة الإقليدية الاعتيادية؟', '["المعالجة بالتوزيع العيني والتجميع، ثم الطرح المتكرر، ثم الحصر بين مضاعفين، وأخيراً الخوارزمية الاعتيادية","البدء بالخوارزمية الاعتيادية مباشرة على السبورة","استعمال الآلة الحاسبة الإلكترونية حصراً","الاستغناء عن مفهوم الباقي والتركيز على القسمة المضبوطة فقط"]'::jsonb, 'المعالجة بالتوزيع العيني والتجميع، ثم الطرح المتكرر، ثم الحصر بين مضاعفين، وأخيراً الخوارزمية الاعتيادية', 'التدرج من التوزيع الفعلي والطرح المتكرر لحاصل الضرب يمنح الخوارزمية الاعتيادية معنى عملياً يحمي المتعلم من الآلية الصماء.'),
('dma158', ARRAY['primary'], 'dma', 'الحساب الذهني', 'ما الأهمية الديداكتيكية لتخصيص خمس دقائق يومياً للحساب الذهني في كل حصة رياضيات؟', '["إنماء المرونة العددية، تقوية استراتيجيات الحساب السريع، وتعزيز التقدير والتحكم الذهني في الأعداد","إضاعة الوقت في بداية الحصة لتأخير الدرس","معاقبة التلاميذ الكسالى بنقاط سلبية","استبدال التمارين الكتابية نهائياً"]'::jsonb, 'إنماء المرونة العددية، تقوية استراتيجيات الحساب السريع، وتعزيز التقدير والتحكم الذهني في الأعداد', 'الحساب الذهني السريع والنشط يحرر الذاكرة العاملة ويدرب التلميذ على التفكيك والتركيب العددي واستعمال خواص العمليات.'),
('dma159', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'وفق نموذج «فان هيل» (Van Hiele) لمستويات التفكير الهندسي، ما هو المستوى الأول لدى تلميذ الطور الأول الابتدائي؟', '["المستوى البصري أو العياني (Visualisation): التعرف على الأشكال الهندسية ككل انطلاقاً من مظهرها العام دون تجريد لخواصها","مستوى البرهان الاستنباطي الشكلي المتقدم","مستوى التحليل الصارم للمنطق الرياضي المسلماتي","مستوى كتابة المعادلات الجبرية للأشكال"]'::jsonb, 'المستوى البصري أو العياني (Visualisation): التعرف على الأشكال الهندسية ككل انطلاقاً من مظهرها العام دون تجريد لخواصها', 'يميز فان هيل المستوى 0/1 بالإدراك الشكلي الإجمالي (هذا مربع لأنه يشبه النافذة)، قبل الانتقال في المستويات اللاحقة لتحليل الخاصيات (الأضلاع والزوايا).'),
('dma160', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما الفرق الديداكتيكي الأساسي بين «المجسمات» (Solides) و«الأشكال المستوية» (Figures planes) في الابتدائي؟', '["المجسمات تشغل حيزاً في الفضاء ثلاثي الأبعاد وتتميز بالوجوه والرؤوس والحروف، بينما الأشكال المستوية ثنائية الأبعاد ترسم في المستوى","المجسمات ترسم بالقلم فقط والأشكال المستوية تصنع من الحديد فقط","لا يوجد أي فرق فالمجسم هو نفسه الشكل المستوي تماماً","الأشكال المستوية تدرس في الإعدادي فقط والمجسمات في الابتدائي فقط"]'::jsonb, 'المجسمات تشغل حيزاً في الفضاء ثلاثي الأبعاد وتتميز بالوجوه والرؤوس والحروف، بينما الأشكال المستوية ثنائية الأبعاد ترسم في المستوى', 'ديداكتيك الهندسة ينطلق من المجسمات الملموسة في الفضاء المحيط (الفضاء الكبير والوسيط) وصولاً إلى إسقاط ونشر وجوهها كأشكال هندسية مستوية.'),
('dma161', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما هي الأداة الهندسية الأساسية للتحقق من تعامد مستقيمين ورسم زاوية قائمة بالابتدائي؟', '["الكوس (المزواة)","المسطرة غير المدرجة فقط","المنقلة لرسم الزوايا الحادة فقط","البركار فقط دون أي أداة أخرى"]'::jsonb, 'الكوس (المزواة)', 'الكوس (Équerre) هو الأداة الديداكتيكية العينية لضبط الزاوية القائمة والتحقق من تعامد مستقيمين وإنشاء المربعات والمستطيلات والارتفاعات.'),
('dma162', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما المدخل الديداكتيكي الأنجع لتقديم مفهوم «التماثل المحوري» (Symétrie axiale)؟', '["تقنية الطي وتطابق النصفين، والتخريم واستعمال ورق الكلك والمرايا في المستوى الحسي","حفظ إحداثيات التحويلات النقطية في الفضاء التحليلي","رسم دائرة وحساب مساحتها بالقواعد التقريبية","حساب جداول الضرب الصعبة"]'::jsonb, 'تقنية الطي وتطابق النصفين، والتخريم واستعمال ورق الكلك والمرايا في المستوى الحسي', 'الطي على طول محور التماثل ومعاينة التطابق التام يرسخ المفهوم كتحويل يحافظ على الأبعاد والمسافات والأشكال.'),
('dma163', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'ما هو التدرج المنهجي الصحيح لتدريس أي مقدار فيزيو-رياضي (طول، كتلة، سعة، مساحة) بالابتدائي؟', '["المقارنة المباشرة، المقارنة غير المباشرة بواسطة أداة وسيطة، القياس بوحدة اعتباطية، ثم القياس بالوحدات الاصطلاحية المعيارية (النظام المتري)","الانتقال الفوري إلى جدول التحويلات في الحصة الأولى مباشرة","حفظ قواعد التحويل المترية عن ظهر قلب دون إجراء أي قياس فعلي","حل مسائل معقدة بالعملات الأجنبية قبل قياس الطول"]'::jsonb, 'المقارنة المباشرة، المقارنة غير المباشرة بواسطة أداة وسيطة، القياس بوحدة اعتباطية، ثم القياس بالوحدات الاصطلاحية المعيارية (النظام المتري)', 'يبدأ القياس حركياً بمقارنة جسدين، ثم استعمال وحدة وسيطة غير معيارية (خيط، كف، إناء)، لإدراك ضرورة التوافق على وحدة عالمية معيارية موحدة.'),
('dma164', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'ما الفرق الديداكتيكي الجوهري بين «المحيط» (Périmètre) و«المساحة» (Aire) لتفادي الخلط بينهما؟', '["المحيط مقدار خطي أحادي البعد يقيس طول الإطار الخارجي، بينما المساحة مقدار ثنائي البعد يقيس الحيز الداخلي المشغول بالسطح","المحيط يقاس بالمتر المربع والمساحة تقاس بالسنتيمتر","المحيط يخص الدائرة فقط والمساحة تخص المثلث فقط","المحيط والمساحة لهما نفس الصيغة الحسابية تماماً"]'::jsonb, 'المحيط مقدار خطي أحادي البعد يقيس طول الإطار الخارجي، بينما المساحة مقدار ثنائي البعد يقيس الحيز الداخلي المشغول بالسطح', 'الخلط بين المحيط والمساحة من أكثر العوائق شهرة، ويعالج بالترصيف والتغطية بالشبكات التربيعية (Pavillage) لتمييز السطح الداخلي عن محيط الحافة.'),
('dma165', ARRAY['primary'], 'dma', 'ديداكتيك التناسبية', 'ما هو المفهوم الرياضي المحوري الذي يشكل معيار التحقق من وجود وضعية تناسبية؟', '["ثبات معامل التناسب بين قيم السطر الأول وقيم السطر المقابل في الجدول","تساوي مجموع أعداد السطر الأول مع مجموع أعداد السطر الثاني","وجود أعداد أولية في الجدول فقط","أن تكون جميع قيم الجدول متساوية تماماً"]'::jsonb, 'ثبات معامل التناسب بين قيم السطر الأول وقيم السطر المقابل في الجدول', 'الجدول التناسبي يتميز بوجود معامل تناسب ثابت (k) يتيح المرور من سطر لآخر بالضرب أو القسمة، وتمثيله المبياني مستقيم يمر من أصل المعلم.'),
('dma166', ARRAY['primary'], 'dma', 'ديداكتيك التناسبية', 'أي المواضيع الرياضية الآتية تندرج مباشرة ضمن تطبيقات التناسبية بالتعليم الابتدائي؟', '["النسبة المئوية، السرعة المتوسطة، سلم التصاميم والخرائط، والكتلة الحجمية","حساب قياس الزوايا المنفرجة بالمنقلة فقط","نشر المكعب ومتوازي المستطيلات","جمع الأعداد الصحيحة الطبيعية"]'::jsonb, 'النسبة المئوية، السرعة المتوسطة، سلم التصاميم والخرائط، والكتلة الحجمية', 'كل هذه المفاهيم هي نماذج لوضعيات تناسبية خطية من نوع y = ax تُعالج بنفس الأدوات الرياضية لمعامل التناسب والرابع المتناسب.'),
('dma167', ARRAY['primary'], 'dma', 'حل المسائل الرياضية', 'وفق نموذج «جورج بوليا» (George Polya)، ما هي الخطوات الأربع لحل المسألة الرياضية؟', '["فهم المسألة، وضع خطة الحل، تنفيذ الخطة، والتحقق والمراجعة النقدية للنتيجة","قراءة المسألة، جمع الأعداد فوراً، كتابة الجواب، ثم النوم","حفظ نص المسألة غيباً، رسم مربع، استدعاء ولي الأمر، ثم مغادرة الفصل","ضرب جميع الأعداد الواردة في المسألة ببعضها مباشرة"]'::jsonb, 'فهم المسألة، وضع خطة الحل، تنفيذ الخطة، والتحقق والمراجعة النقدية للنتيجة', 'خطوات بوليا تمثل المعمارية الكلاسيكية المعتمدة في ديداكتيك حل المشكلات: تمثل المعطيات والمجهول، ابتكار استراتيجية، الإنجاز الحسابي، ونقد معقولية النتيجة.'),
('dma168', ARRAY['primary'], 'dma', 'حل المسائل الرياضية', 'ماذا يقصد بالنمذجة الرياضية (Modélisation) في سياق معالجة مسألة واقعية بالسلك الابتدائي؟', '["ترجمة الموقف الواقعي المعاش والبيانات اللغوية إلى علاقات ورموز وعمليات رياضية قابلة للحل","صنع مجسمات خشبية ملونة لبيعها في المعرض","نقل نص المسألة بخط عربي جميل دون حله","حساب متوسط علامات التلاميذ في الامتحان"]'::jsonb, 'ترجمة الموقف الواقعي المعاش والبيانات اللغوية إلى علاقات ورموز وعمليات رياضية قابلة للحل', 'النمذجة هي الجسر الرابط بين الواقع المجتمعي والرياضيات الصورية، حيث ينتقل المتعلم من السياق الحياتي إلى التمثيل التخطيطي والصيغة الحسابية.'),
('dma169', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'حسب نظرية غي بروسو، ما الذي يميز «وضعية الفعل» (Situation d''action)؟', '["تفاعل المتعلم مباشرة مع الوسط المادي لحل المشكلة دون حاجة إلى لغة صورية للتواصل مع الآخرين","كتابة القاعدة الرياضية على السبورة وتكرارها جماعياً","استماع التلاميذ لشرح الأستاذ لمدة ساعة كاملة","تسليم ورقة الامتحان النهائي للمفتش"]'::jsonb, 'تفاعل المتعلم مباشرة مع الوسط المادي لحل المشكلة دون حاجة إلى لغة صورية للتواصل مع الآخرين', 'في وضعية الفعل، يبني المتعلم قرارات فردية تجريبية ويتلقى رجع أثر فوري من الوسط (Milieu) ليعدل استراتيجيته الحركية والذهنية.'),
('dma170', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'في نظرية الوضعيات الديداكتيكية، ما هي «وضعية الصياغة» (Situation de formulation)؟', '["وضعية تستوجب صياغة رسالة واضحة ومشفرة لغوياً أو رمزياً لنقل خطة أو معلومة إلى شريك آخر لإنجاز المهمة","حفظ جدول الضرب وترديده بصوت مرتفع","تصحيح الأخطاء الإملائية في كتاب الرياضيات","رسم شجرة العائلة الرياضية"]'::jsonb, 'وضعية تستوجب صياغة رسالة واضحة ومشفرة لغوياً أو رمزياً لنقل خطة أو معلومة إلى شريك آخر لإنجاز المهمة', 'تتطلب وضعية الصياغة استخدام أدوات لغوية أو رموز اصطلاحية تجعل الرسالة مفهومة لمتلقٍ لا يرى نفس الوسط المادي.'),
('dma171', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما المقصود بـ «وضعية التداول والمصادقة» (Situation de validation) عند بروسو؟', '["مرحلة يقدم فيها المتعلم حججاً وبراهين رياضية عقلانية لإقناع أقرانه بصحة استراتيجيته أو لرفض مقترح خاطئ","موافقة الأستاذ السريعة بوضع علامة صح دون نقاش","تصفيق التلاميذ على الفائز في مسابقة الحساب السريع","شراء الأدوات الهندسية من المكتبة والمصادقة على الفاتورة"]'::jsonb, 'مرحلة يقدم فيها المتعلم حججاً وبراهين رياضية عقلانية لإقناع أقرانه بصحة استراتيجيته أو لرفض مقترح خاطئ', 'تعتمد المصادقة على المحاججة العقلانية والتبرير الرياضي، حيث لا يُقبل الحل لسلطة الأستاذ بل لمنطق الحجة والبرهان.'),
('dma172', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ماذا يقصد بمرحلة «المأسسة» (Institutionnalisation) في الدرس البنائي للرياضيات؟', '["تدخل الأستاذ لإعطاء المعرفة المكتشفة طابعها الرسمي العالمي الصالح للاستعمال وتثبيتها كقاعدة اصطلاحية","بناء مدرسة جديدة في القرية لتدريس الرياضيات","تأسيس نادٍ ترفيهي لمسابقات الشطرنج","إجراء امتحان كتابي صارم نهاية الحصة"]'::jsonb, 'تدخل الأستاذ لإعطاء المعرفة المكتشفة طابعها الرسمي العالمي الصالح للاستعمال وتثبيتها كقاعدة اصطلاحية', 'المأسسة هي اللحظة التي يرفع فيها الأستاذ المعرفة الذاتية السياقية للتلاميذ إلى مستوى المعرفة الرياضية المقننة المشتركة.'),
('dma173', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو «المتغير الديداكتيكي» (Variable didactique) في هندسة الأنشطة الرياضية؟', '["عنصر أو شرط في الوضعية المشكلة يؤدي تغيير قيمته إلى تغيير استراتيجيات الحل وتكلفة الإنجاز المعرفية","حالة الطقس ودرجة حرارة حجرة الدرس","نوع الحبر المستخدم في كتابة المسألة","اسم المتعلم الذي يقف أمام السبورة"]'::jsonb, 'عنصر أو شرط في الوضعية المشكلة يؤدي تغيير قيمته إلى تغيير استراتيجيات الحل وتكلفة الإنجاز المعرفية', 'التحكم في المتغيرات الديداكتيكية (مثل طبيعة الأعداد: صغيرة أو كبيرة، كسرية أو صحيحة) يجبر المتعلم على مغادرة الحل القديم وبناء استراتيجية جديدة.'),
('dma174', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو أثر توباز (Effet Topaze) كأحد انزلاقات العقد الديداكتيكي؟', '["عندما يواجه التلميذ صعوبة، يقوم الأستاذ بتوجيهه تدريجياً وإعطائه تلميحات مفرطة حتى يعطيه الجواب دون جهد تفكيري","غياب الأستاذ المتكرر عن حصص الرياضيات","إلزام التلاميذ بحل المسائل في الظلام","عقاب المتعلمين بدنياً عند الخطأ"]'::jsonb, 'عندما يواجه التلميذ صعوبة، يقوم الأستاذ بتوجيهه تدريجياً وإعطائه تلميحات مفرطة حتى يعطيه الجواب دون جهد تفكيري', 'أثر توباز يفرغ النشاط التعليمي من محتواه الرياضي حين يضيق المعلم السؤال إلى أن ينطق التلميذ بالحل دون فهم فعلي.'),
('dma175', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو أثر جوردان (Effet Jourdain) في تعاقد القسم الرياضي؟', '["تأويل سلوك أو إجابة بسيطة وتافهة للتلميذ على أنها دليل عبقري على فهم نظرية علمية معقدة","إجراء رحلة استكشافية خارج المؤسسة","حفظ قواعد نيوتن في درس الحساب","تدريس الرياضيات باللغة الألمانية"]'::jsonb, 'تأويل سلوك أو إجابة بسيطة وتافهة للتلميذ على أنها دليل عبقري على فهم نظرية علمية معقدة', 'أثر جوردان يحدث عندما يتفادى الأستاذ مواجهة فشل التلميذ، فيعتبر أي حركة عفوية دليلاً وهمياً على الفهم العميق للمفهوم.'),
('dma176', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'لماذا تم استبدال الطريقة القديمة للطرح بالاستعارة بـ «تقنية الطرح بالإفاضة أو الإضافة المتساوية»؟', '["لأنها تستند إلى خاصية رياضية واضحة ومبرهنة وهي ثبات الفارق بإضافة نفس العدد للحدين: a - b = (a+c) - (b+c)","لأن طريقة الاستعارة ممنوعة قانوناً بمرسوم وزاري","لأنها لا تحتاج إلى معرفة جدول الجمع","لأنها تجعل الطرح أطول وأصعب على المتعلم"]'::jsonb, 'لأنها تستند إلى خاصية رياضية واضحة ومبرهنة وهي ثبات الفارق بإضافة نفس العدد للحدين: a - b = (a+c) - (b+c)', 'تقنية الإضافة المتساوية (إضافة 10 للحد العلوي و1 منزلة العشرات للحد السفلي) ترتكز على مبرهنة رياضية صلبة وتسهل الحساب دون شطب الذاكرة.'),
('dma177', ARRAY['primary'], 'dma', 'تنظيم ومعالجة المعطيات', 'ما الهدف الديداكتيكي من تدريس مكون «تنظيم ومعالجة البيانات» بالابتدائي؟', '["قراءة وتفسير الجداول والمخططات البيانية (بالأعمدة، بالقطاعات، بالخطوط) والقدرة على فرز وتنظيم معطيات رقمية","حفظ معادلات التراجع الخطي والاحتمالات المركبة في سن مبكرة","استبدال مادة التاريخ بمادة الإحصاء الطبي","رسم خرائط الطقس بدون استخدام الأرقام"]'::jsonb, 'قراءة وتفسير الجداول والمخططات البيانية (بالأعمدة، بالقطاعات، بالخطوط) والقدرة على فرز وتنظيم معطيات رقمية', 'تنمية الحس الإحصائي وتدريب المتعلم على استخراج قراءات تركيبية ونقدية لمعطيات ممثلة مبيانياً تفيده في حياته اليومية.'),
('dma178', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما دور «الحساب التقريبي والتقديري» (Ordre de grandeur) قبل إنجاز أي عملية حسابية كتابية؟', '["توقع النتيجة التقريبية للتحقق الذاتي من معقولية الجواب وكشف الأخطاء الفادحة في المنازل والفواصل","إعطاء النتيجة الصحيحة بالمليمتر دون الحاجة للحساب","إلغاء أهمية العمليات الحسابية الدقيقة","استعماله فقط عند نسيان الأدوات المدرسية"]'::jsonb, 'توقع النتيجة التقريبية للتحقق الذاتي من معقولية الجواب وكشف الأخطاء الفادحة في المنازل والفواصل', 'رتبة القدر تمثل آلية رقابة ذاتية بالغة الأهمية تحمي التلميذ من القبول اللانقدي لنتائج غير منطقية تماماً.'),
('dma179', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما هي «الشبكة التربيعية» وكيف تفيد في تدريس تكبير وتصغير الأشكال؟', '["أداة وسيطة تمكن من الحساب البسيط لأطوال الأضلاع بمضاعفة أو قسمة عدد التربيعات مع الحفاظ التام على قياس الزوايا","لعبة إلكترونية لتسلية الأطفال في نهاية الحصة","شبكة لصيد الأسماك تستعمل في النشاط العلمي فقط","أداة لرسم الدوائر دون بركار"]'::jsonb, 'أداة وسيطة تمكن من الحساب البسيط لأطوال الأضلاع بمضاعفة أو قسمة عدد التربيعات مع الحفاظ التام على قياس الزوايا', 'تيسر التربيعات إدراك مفهوم التشابه والتكبير عبر نسب عددية واضحة لأطوال الأضلاع مع إبراز بقاء الزوايا ثابتة لا تتغير.'),
('dma180', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'عند جمع عددين صحيحين، ما مصدر الخطأ في إنجاز العملية: 47 + 25 = 612 ؟', '["عدم استيعاب مفهوم «الاحتفاظ» وكتابة مجموع الوحدات (12) كاملاً بجوار مجموع العشرات (6)","عدم معرفة جدول جمع 7 + 5","طرح 25 من 47 بالخطأ","كتابة الأعداد باللغة الفرنسية"]'::jsonb, 'عدم استيعاب مفهوم «الاحتفاظ» وكتابة مجموع الوحدات (12) كاملاً بجوار مجموع العشرات (6)', 'هذا الخطأ الكلاسيكي يكشف جهلاً بقاعدة المبادلة (10 وحدات تصبح عشرة واحدة تُحول للمنزلة التالية) ويتطلب تدريباً بالمكعبات والقضبان.'),
('dma181', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو التوزيع المنهجي لحصص درس الرياضيات بالتعليم الابتدائي في كل أسبوع؟', '["5 حصص في الأسبوع مدة كل حصة 55 دقيقة تخصص أولاها للبناء والنمذجة ثم الترييض وأخيراً التقويم والدعم","حصة واحدة أسبوعياً مدتها خمس ساعات","حصتان فقط يوم الجمعة والسبت","عشر حصص يومية لا تتوقف"]'::jsonb, '5 حصص في الأسبوع مدة كل حصة 55 دقيقة تخصص أولاها للبناء والنمذجة ثم الترييض وأخيراً التقويم والدعم', 'يخصص المنهاج 5 حصص أسبوعية لمادة الرياضيات تمارس فيها الأنشطة بالتدرج: بناء المفهوم، الترييض والتدريب، ثم تقويم ودعم المعالجة.'),
('dma182', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما هو التحديد الديداكتيكي لخاصيات «المربع» مقارنة بـ «المعين» في المستوى الابتدائي؟', '["كلاهما له أربعة أضلاع متقايسة، لكن المربع يتميز إضافياً بأربع زوايا قائمة وقطرين متعامدين ومتقايسين","المربع ليس له أضلاع متقايسة بينما المعين أضلاعه متقايسة","المعين له أربع زوايا قائمة والمربع ليس له أي زاوية قائمة","المعين هو مجسم ثلاثي الأبعاد والمربع شكل مستوي"]'::jsonb, 'كلاهما له أربعة أضلاع متقايسة، لكن المربع يتميز إضافياً بأربع زوايا قائمة وقطرين متعامدين ومتقايسين', 'التصنيف الهندسي يبرز الخاصيات المشتركة والخاصيات المميزة؛ فالمربع حالة خاصة من المعين والمستطيل معاً بتوفر الزوايا القائمة وتطابق الأضلاع.'),
('dma183', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما المقصود بـ «الأعداد الكسرية المتكافئة» (Fractions équivalentes) وكيف تدرس عيانياً؟', '["كسور مختلفة تمثل نفس المقدار، وتدرس بطي وتقسيم أشرطة متطابقة لبيان أن 1/2 يكافئ 2/4 ويكافئ 4/8","كسور لها نفس البسط ومقامات مختلفة دون تساوي القيم","أعداد كسرية لا يمكن جمعها أبداً","كسور يكون بسطها دائماً صفراً"]'::jsonb, 'كسور مختلفة تمثل نفس المقدار، وتدرس بطي وتقسيم أشرطة متطابقة لبيان أن 1/2 يكافئ 2/4 ويكافئ 4/8', 'التكافؤ الحسي بالشرائط والأقراص يسبق صياغة القاعدة الجبرية لضرب أو قسمة البسط والمقام في نفس العدد غير المنعدم.'),
('dma184', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'عند حساب حجم متوازي المستطيلات، ما هي القاعدة المعتمدة وعلاقتها بمساحة القاعدة؟', '["الحجم يساوي جداء مساحة القاعدة في الارتفاع: V = B × h = (الطول × العرض) × الارتفاع","الحجم يساوي مجموع أطوال أضلاعه الأربعة","الحجم يساوي مساحة السطح مقسومة على اثنين","الحجم هو محيط القاعدة مضروباً في الصفر"]'::jsonb, 'الحجم يساوي جداء مساحة القاعدة في الارتفاع: V = B × h = (الطول × العرض) × الارتفاع', 'يبنى الحجم بتكديس طبقات من المكعبات الوحدوية بارتفاع متوازي المستطيلات لربط الحجم بجداء الأبعاد الثلاثة.'),
('dma185', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ماذا يقصد بـ «الوضعية المشكلة الرياضية» (Situation-problème) في مدخل الكفايات؟', '["وضعية ذات معنى تطرح عائقاً وتحدياً يتطلب تجنيد معارف سابقة وبناء معارف جديدة لتجاوزه","تمرين روتيني بسيط يحل بتطبيق مباشر لقاعدة معروفة دون أي جهد تفكيري","مسألة مستحيلة الحل وضعها الأستاذ لتعجيز التلاميذ وتخويفهم","نص طويل يتضمن ألغازاً أدبية لا علاقة لها بالرياضيات"]'::jsonb, 'وضعية ذات معنى تطرح عائقاً وتحدياً يتطلب تجنيد معارف سابقة وبناء معارف جديدة لتجاوزه', 'الوضعية المشكلة هي المحرك الديداكتيكي للتعلم؛ تضع التلميذ أمام عائق معرفي يتطلب صراعاً معرفياً واستنفاراً للقدرات لبناء المفهوم الجديد.'),
('dma186', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ما هي المقاربة الديداكتيكية لتجاوز عائق ضرب عدد عشري في 10 أو 100؟', '["تفسير الظاهرة بإزاحة رتب الأرقام نحو المنازل الأعلى (اليسار) برتبة أو رتبتين وليس بحركة الفاصلة فقط","حفظ قاعدة وضع الأصفار عشوائياً بعد الفاصلة","حذف الجزء العشري نهائياً والاحتفاظ بالصحيح","الاستعانة بالآلة الحاسبة ومنع التفكير الذهني"]'::jsonb, 'تفسير الظاهرة بإزاحة رتب الأرقام نحو المنازل الأعلى (اليسار) برتبة أو رتبتين وليس بحركة الفاصلة فقط', 'الفهم العلمي الموضعي يوضح أن الرقم هو الذي يتضاعف بقوة 10 فينتقل من رتبة الأعشار إلى الوحدات ومن الوحدات إلى العشرات.'),
('dma187', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'كيف يساهم «نشر المجسمات» (Patron / Développement) في تعميق الفهم الهندسي؟', '["يربط بين الرؤية ثلاثية الأبعاد للمجسم في الفضاء وسطحه المنبسط ثنائي الأبعاد في المستوى مع بيان توافق الوجوه","يستعمل فقط لتغليف الهدايا دون فائدة تعليمية","يعوض حفظ جداول القسمة الإقليدية","يبرهن على توازي خطوط الطول والعرض الجغرافية"]'::jsonb, 'يربط بين الرؤية ثلاثية الأبعاد للمجسم في الفضاء وسطحه المنبسط ثنائي الأبعاد في المستوى مع بيان توافق الوجوه', 'نشر وطي الورق المقوى المقصوص يتيح للمتعلم الانتقال الإدراكي بين الفضاء الثلاثي الأبعاد والمستوي ثنائي الأبعاد واكتشاف قواعد التركيب.'),
('dma188', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'ما العلاقة القياسية المباشرة بين وحدات قياس السعة ووحدات قياس الحجم؟', '["1 ديسيمتر مكعب (1 dm³) يعادل تماماً 1 لتر (1 L)","1 متر مكعب يعادل 1 لتر","1 سنتيمتر مكعب يعادل 1 لتر","لا توجد أي علاقة بين السعة والحجم"]'::jsonb, '1 ديسيمتر مكعب (1 dm³) يعادل تماماً 1 لتر (1 L)', 'العلاقة 1 dm³ = 1 L هي حجر الزاوية الديداكتيكي للربط بين جدولي وحدات القياس (الحجم والسعات) وتجرب في القسم بملء مكعب 10×10×10 سم بالماء.'),
('dma189', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو دور «التمثيل التخطيطي والرسم» في مرحلة فهم نص المسألة الرياضية؟', '["تحويل المعطيات المجردة والعلاقات الكمية إلى نموذج بصري يساعد على إدراك بنية المشكلة والعمليات اللازمة","تزيين دفتر الحساب لإرضاء الأستاذ بالرسوم فقط","استبدال الحساب الرياضي بحصة تربية تشكيلية","إخفاء الأخطاء الحسابية خلف الألوان"]'::jsonb, 'تحويل المعطيات المجردة والعلاقات الكمية إلى نموذج بصري يساعد على إدراك بنية المشكلة والعمليات اللازمة', 'التمثيل بالمخططات (الشريطية، السهمية، أو المربعات) يخفف العبء المعرفي ويساعد المتعلم على الانتقال السلس من النص اللغوي إلى الصيغة الرياضية.'),
('dma190', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'ماذا يعني مفهوم «العدد الأولي» (Nombre premier) وكيف يقدم في السنة السادسة؟', '["عدد صحيح طبيعي أكبر من 1 يقبل بالضبط قاسمين اثنين مختلفين هما: 1 ونفسه","عدد ينتهي برقم زوجي دائماً","أي عدد مكتوب في أول سطر بالصفحة","عدد يمكن قسمته على جميع الأعداد دون باقي"]'::jsonb, 'عدد صحيح طبيعي أكبر من 1 يقبل بالضبط قاسمين اثنين مختلفين هما: 1 ونفسه', 'يقدم العدد الأولي عبر البحث المنهجي عن قواسم الأعداد (مثلاً قواسم 7 هي 1 و7 فقط)، لتفكيك الأعداد في تفكيكات جداء عوامل أولية.'),
('dma191', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما الميزة الهندسية المميزة لـ «الدائرة» مقارنة بالمضلعات الاعتيادية؟', '["منحن مغلق تبعد جميع نقطه بمسافة ثابتة (الشعاع) عن نقطة مركزية ثابتة (المركز) وليس لها أضلاع مستقيمة","مضلع ذو ثلاثة أضلاع وزاويتين منفرجتين","مجسم ثلاثي الأبعاد يحتوي على 6 رؤوس","شكل هندسي يتكون من أربعة خطوط متعامدة فقط"]'::jsonb, 'منحن مغلق تبعد جميع نقطه بمسافة ثابتة (الشعاع) عن نقطة مركزية ثابتة (المركز) وليس لها أضلاع مستقيمة', 'الدائرة تُعرف بالمحل الهندسي للنقاط متساوية البعد عن المركز، ويرسخ رسمها بالبركار مفهومي المركز والشعاع.'),
('dma192', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'ما هو الثابت الرياضي π (بي) وكيف يُستكشف ديداكتيكياً في الابتدائي؟', '["النسبة الثابتة بين محيط أي دائرة وقطرها (حوالي 3.14) وتكتشف تجريبياً بلف خيط حول أسطوانات مختلفة وقياس القطر","درجة حرارة غليان الماء في الأوعية الدائرية","عدد أيام الشهر القمري مقسومة على 7","قيمة الزاوية القائمة في المثلث متساوي الساقين"]'::jsonb, 'النسبة الثابتة بين محيط أي دائرة وقطرها (حوالي 3.14) وتكتشف تجريبياً بلف خيط حول أسطوانات مختلفة وقياس القطر', 'التجريب بالقياس الفعلي لمحيط أقراص وعلب مختلفة وقسمته على أقطارها يبين للتلاميذ ثبات النسبة P/D عند القيمة التقريبية 3.14.'),
('dma193', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هو «التعاقد الديداكتيكي» (Contrat didactique) حسب بروسو؟', '["مجموع الالتزامات والانتظارات الصريحة والضمنية المتبادلة بين المدرس والمتعلمين حول موضوع المعرفة","عقد عمل قانوني موقع بين الأستاذ ومديرية التعليم","وثيقة تجارية لشراء اللوازم المدرسية","اتفاق بين أولياء الأمور وحارس المؤسسة"]'::jsonb, 'مجموع الالتزامات والانتظارات الصريحة والضمنية المتبادلة بين المدرس والمتعلمين حول موضوع المعرفة', 'التعاقد الديداكتيكي يحدد قواعد اللعبة الصفية غير المصرح بها غالباً، والتي تحكم ما ينتظره كل طرف من الآخر تجاه المعرفة الرياضية.'),
('dma194', ARRAY['primary'], 'dma', 'ديداكتيك الأعداد والحساب', 'كيف يساهم مفهوم «الحصر بين مضاعفين متتاليين» في تيسير تقدير خارج القسمة؟', '["يحدد عدد أرقام الخارج ويحصر قيمته في مجال عددي ضيق مما يمنع الأخطاء الفاحشة في الحساب","يحول القسمة إلى مسألة هندسية ترسم بالمسطرة فقط","يلغي الحاجة لمعرفة جداول الضرب نهائياً","يسمح بحساب الجذور المربعة دون عمليات"]'::jsonb, 'يحدد عدد أرقام الخارج ويحصر قيمته في مجال عددي ضيق مما يمنع الأخطاء الفاحشة في الحساب', 'حصر المقسوم (b × 10 < a < b × 100) يعلم التلميذ فوراً أن الخارج يتكون من رقمين، مما يضبط التقدير والتحكم في الخوارزمية.'),
('dma195', ARRAY['primary'], 'dma', 'ديداكتيك الهندسة والفضاء', 'ما هو الخطأ المفهومي عند التلميذ الذي يدعي أن «المستطيل المائل لم يعد مستطيلاً»؟', '["سيادة عائق الإدراك البصري الثابت واعتبار الوضعية الفضائية (الأفقية والعمودية) خاصية جوهرية للشكل الهندسي","ضعف بصري يتطلب نظارات طبية فورية","صعوبة في مسك القلم بيده اليمنى","عدم معرفة أسماء الألوان الأساسية"]'::jsonb, 'سيادة عائق الإدراك البصري الثابت واعتبار الوضعية الفضائية (الأفقية والعمودية) خاصية جوهرية للشكل الهندسي', 'يربط الأطفال في المراحل الأولى المفهوم بوضعية نموذجية (Prototype)، ويتطلب التغلب عليه تدوير الأشكال وعرضها في وضعيات فضاء متنوعة.'),
('dma196', ARRAY['primary'], 'dma', 'ديداكتيك القياس', 'ما هي الصيغة الرياضية لحساب مساحة المثلث انطلاقاً من مساحة متوازي الأضلاع أو المستطيل؟', '["نصف جداء القاعدة في الارتفاع الموافق لها: S = (القاعدة × الارتفاع) ÷ 2","مجموع أطوال الأضلاع الثلاثة مقسوماً على ثلاثة","مربع طول الضلع الأكبر","جداء الأضلاع الثلاثة في بعضها"]'::jsonb, 'نصف جداء القاعدة في الارتفاع الموافق لها: S = (القاعدة × الارتفاع) ÷ 2', 'تُبنى صيغة مساحة المثلث بقص مستطيل أو متوازي أضلاع قطرياً إلى مثلثين متطابقين، ليبرهن المتعلم عيانياً أن المثلث نصف مساحته.'),
('dma197', ARRAY['primary'], 'dma', 'ديداكتيك التناسبية', 'ماذا يعني «السلم 1/100» على تصميم معماري لغرفة صفية؟', '["كل 1 سنتيمتر على التصميم يمثل في الواقع 100 سنتيمتر (أي 1 متر) في القياس الحقيقي","أن طول الغرفة يساوي 100 كيلومتر بالتمام والكمال","أن تكلفة بناء الغرفة هي 100 درهم فقط","أن التصميم مخصص لمائة تلميذ معاً"]'::jsonb, 'كل 1 سنتيمتر على التصميم يمثل في الواقع 100 سنتيمتر (أي 1 متر) في القياس الحقيقي', 'السلم هو معامل تناسب خطي يمثل النسبة بين البعد على التصميم (المصغر) والبعد الحقيقي المعبر عنهما بنفس الوحدة.'),
('dma198', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما المقصود بـ «الصراع السوسيو-معرفي» (Conflit socio-cognitif) في مجموعات حل المسائل؟', '["المواجهة الإيجابية بين تمثلات واستراتيجيات حل متباينة للأقران تؤدي لإعادة تنظيم الفرد لبنيته المعرفية","شجار وخلاف عنيف بين التلاميذ في الساحة","انتقاد لاذع يوجهه المعلم للتلميذ لإحباطه","عدم اتفاق الأساتذة على جدول الحراسة في الامتحانات"]'::jsonb, 'المواجهة الإيجابية بين تمثلات واستراتيجيات حل متباينة للأقران تؤدي لإعادة تنظيم الفرد لبنيته المعرفية', 'الصراع السوسيو-معرفي (حسب مدرسة جنيف النيوبياجية) يحفز التفكير اللامركزي ويكشف قصور النظرة الفردية بفضل تفاعل الأقران.'),
('dma199', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هي وظيفة أسبوع الدعم والتوليف (الأسبوع الخامس) في مادة الرياضيات؟', '["تشخيص الثغرات المرصودة خلال أسابيع البناء الأربعة وتقديم أنشطة علاجية فارقية لتثبيت الكفايات","تقديم دروس جديدة إضافية خارج المنهاج الرسمي","إجراء مسابقات رياضية ترفيهية في ساحة المدرسة فقط","تكرار إملاء نصوص اللغة العربية"]'::jsonb, 'تشخيص الثغرات المرصودة خلال أسابيع البناء الأربعة وتقديم أنشطة علاجية فارقية لتثبيت الكفايات', 'يخصص أسبوع الدعم والتقويم بالوحدة لرصد مكامن الصعوبة وتصنيف المتعلمين حسب حاجاتهم لتقديم معالجة بيداغوجية مخصصة.'),
('dma200', ARRAY['primary'], 'dma', 'ديداكتيك الرياضيات', 'ما هي الكفاية النهائية الختامية لتدريس الرياضيات في ختام السلك الابتدائي بالمغرب؟', '["حل وضعيات مشكلة دالة بتجنيد المكتسبات في الأعداد والحساب والهندسة والقياس وتنظيم المعطيات في سياقات حياتية متنوعة","حفظ براهين النظريات الجامعية في الطوبولوجيا والجبر المجرد","استعمال الآلة الحاسبة دون معرفة أي عملية كتابية بسيطة","اجتياز الامتحانات دون فهم المعاني الرياضية المكتسبة"]'::jsonb, 'حل وضعيات مشكلة دالة بتجنيد المكتسبات في الأعداد والحساب والهندسة والقياس وتنظيم المعطيات في سياقات حياتية متنوعة', 'تتوج الكفاية الختامية تكامل المجالات الرياضية لتمكين المتعلم من التفكير المنطقي الاستدلالي وحل مشكلات بيئته ومواصلة مساره الإعدادي بنجاح.'),
('dsc151', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي الخاصية البيداغوجية المحورية لـ «وضعية الانطلاق» في درس النشاط العلمي؟', '["أن تكون وضعية محفزة مستقاة من المحيط المعاش للمتعلم تثير الدهشة والتساؤل وتولد صراعاً معرفياً دالاً","أن تتضمن الحل العلمي الكامل مع الشرح المباشر لجميع النتائج","أن تكون نصاً نظرياً طويلاً يُحفظ عن ظهر قلب قبل بداية الدرس","أن تخلو تماماً من أي سؤال أو مفارقة علمية"]'::jsonb, 'أن تكون وضعية محفزة مستقاة من المحيط المعاش للمتعلم تثير الدهشة والتساؤل وتولد صراعاً معرفياً دالاً', 'وضعية الانطلاق الناجحة هي التي تخلق خلخلة إبستمولوجية (Perturbation) تدفع المتعلمين إلى التساؤل والبحث عن تفسير.'),
('dsc152', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما الفرق الديداكتيكي الدقيق بين «سؤال التقصي» و«الفرضية العلمية»؟', '["سؤال التقصي يحدد المشكلة المراد استقصاؤها بصيغة استفهامية، والفرضية هي تفسير مؤقت مقترح ينتظر التحقق التجريبي","سؤال التقصي يطرحه التلميذ والفرضية يفرضها الأستاذ كحقيقة لا نقاش فيها","الفرضية تطرح في أول الحصة وسؤال التقصي يكتب في آخر الدرس","سؤال التقصي والفرضية هما نفس الشيء ولا فرق بينهما مطلقاً"]'::jsonb, 'سؤال التقصي يحدد المشكلة المراد استقصاؤها بصيغة استفهامية، والفرضية هي تفسير مؤقت مقترح ينتظر التحقق التجريبي', 'سؤال التقصي يصوغ الإشكال (Comment? Pourquoi?)، والفرضية (Hypothèse) جواب تخميني محتمل يتطلب الاختبار للتحقق من صدقيته.'),
('dsc153', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي طرائق التحقق والتقصي المعتمدة في النشاط العلمي إلى جانب التجريب المباشر؟', '["الملاحظة المباشرة بالميدان، النمذجة المجسمة، الزيارات الميدانية، والبحث التوثيقي الموجه","التخمين بالقرعة واختيار الإجابة بالصدفة","السؤال المباشر لحارس المؤسسة دون تجريب","حفظ أقوال الفلاسفة الإغريق القدامى فقط"]'::jsonb, 'الملاحظة المباشرة بالميدان، النمذجة المجسمة، الزيارات الميدانية، والبحث التوثيقي الموجه', 'لا ينحصر التقصي في التجربة المخبرية فقط؛ فالظواهر الفلكية والبيئية تتطلب الملاحظة والنمذجة أو التوثيق العلمي.'),
('dsc154', ARRAY['primary'], 'dsc', 'كراسة التقصي العلمي', 'ما هو الدور الديداكتيكي لـ «دفتر / كراسة التقصي العلمي» لدى متعلم السلك الابتدائي؟', '["فضاء شخصي لتدوين الأسئلة والفرضيات، ورسم التجارب والبيانات، وصياغة الاستنتاجات العلمية بتدرج","دفتر لجمع توقيعات الأصدقاء في نهاية السنة فقط","كتاب جاهز ومطبوع مسبقاً لا يكتب فيه التلميذ أي كلمة","سجل مخصص لتسجيل العقوبات المدرسية والغيابات"]'::jsonb, 'فضاء شخصي لتدوين الأسئلة والفرضيات، ورسم التجارب والبيانات، وصياغة الاستنتاجات العلمية بتدرج', 'دفتر التقصي (Carnet de chercheur) يدرب التلميذ على الممارسة العلمية الحقيقية بتسجيل أفكاره وملاحظاته ورسومه البيانية والتوثيقية.'),
('dsc155', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي وظيفة مرحلة «المأسسة والتعميم» في ختام خطوات نهج التقصي؟', '["صياغة الخلاصة المعرفية الرسمية بلغة علمية دقيقة وربطها بالمعارف المنهجية المعتمدة وتطبيقها في سياقات جديدة","توزيع الهدايا والشهادات التقديرية على التلاميذ","تنظيف قاعة الدرس ومسح الطاولات فقط","إلغاء ما توصل إليه التلاميذ وإعادة قراءة الكتاب المدرسي من البداية"]'::jsonb, 'صياغة الخلاصة المعرفية الرسمية بلغة علمية دقيقة وربطها بالمعارف المنهجية المعتمدة وتطبيقها في سياقات جديدة', 'المأسسة العلمية تثبت المعرفة المكتشفة وتمنحها تسميتها الصائبة وتعممها لتمكين المتعلم من استثمارها في وضعيات حياتية أخرى.'),
('dsc156', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما هو المدخل الديداكتيكي المناسب لدراسة «السلاسل والشبكات الغذائية» في الابتدائي؟', '["الانطلاق من ملاحظة وسط طبيعي محلي وتحديد الكائنات المنتجة (النباتات) والمستهلكة والمحللة والعلاقات التغذوية بينها","حفظ الأسماء العلمية اللاتينية للحيوانات المفترسة فقط","رسم حيوانات خيالية وأسطورية لا وجود لها في الطبيعة","تدريس تصنيف الحفريات الجيولوجية القديمة"]'::jsonb, 'الانطلاق من ملاحظة وسط طبيعي محلي وتحديد الكائنات المنتجة (النباتات) والمستهلكة والمحللة والعلاقات التغذوية بينها', 'ملاحظة بيئة مألوفة (حديقة المدرسة، غابة مجاورة) تجسد تدفق الطاقة وتبرز دور المنتجين والمستهلكين في توازن الحميلة البيئية.'),
('dsc157', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يُعالج العائق الشائع القائل بأن «الهواء ليس مادة لأنه غير مرئي» في النشاط العلمي؟', '["عبر تجارب حسية مثل حصر الهواء في محقنة، وتنكيس كأس فيه منديل جاف في الماء، ومقارنة وزن كرة منفوخة وفارغة","بإخبار التلاميذ شفهياً بأن الهواء مادة وعقاب من يعترض على ذلك","بحذف درس الهواء من المقرر السنوي","بالانتظار حتى وصول التلميذ إلى السلك الثانوي"]'::jsonb, 'عبر تجارب حسية مثل حصر الهواء في محقنة، وتنكيس كأس فيه منديل جاف في الماء، ومقارنة وزن كرة منفوخة وفارغة', 'التجريب الحسي والمادي المباشر يثبت أن الهواء يشغل حيزاً (لا يدخل الماء للكأس المنكس) وله كتلة وقابل للانضغاط، مما يفكك التصور الخاطئ.'),
('dsc158', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما الفرق الديداكتيكي الأساسي بين «التحول الفيزيائي» و«التحول الكيميائي» في تجارب الابتدائي؟', '["التحول الفيزيائي يغير شكل أو حالة المادة مع إمكانية الرجوع للأصل (كالذوبان والانصهار)، بينما الكيميائي ينتج مواد جديدة غير قابلة للرجوع بسهولة (كالاحتراق)","التحول الفيزيائي يحدث في المختبر والكيميائي في المطبخ فقط","التحول الكيميائي يخص الغازات فقط والفيزيائي يخص السوائل فقط","كلاهما نفس الشيء تماماً ولا يوجد أي فرق علمي"]'::jsonb, 'التحول الفيزيائي يغير شكل أو حالة المادة مع إمكانية الرجوع للأصل (كالذوبان والانصهار)، بينما الكيميائي ينتج مواد جديدة غير قابلة للرجوع بسهولة (كالاحتراق)', 'المقارنة بين انصهار الشمع أو ذوبان الملح (تغير فيزيائي عكوس) واحتراق الورق أو صدأ الحديد (تغير كيميائي ينتج أجساماً جديدة) توضح التمييز بوضوح.'),
('dsc159', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'ما المعين الديداكتيكي الأنجع لتفسير «تعاقب الليل والنهار» و«فصول السنة» لتلاميذ الابتدائي؟', '["النمذجة المجسمة باستعمال مجسم الكرة الأرضية ومصدر ضوئي (مصباح) يمثل الشمس مع محاكاة الدوران حول المحور وحول الشمس","النظر المباشر بالعين المجردة إلى قرص الشمس في الظهيرة","رسم لوحة فنية لغروب الشمس دون أي مجسم","حفظ المسافات الفلكية بملايين الكيلومترات دون تمثيل بصري"]'::jsonb, 'النمذجة المجسمة باستعمال مجسم الكرة الأرضية ومصدر ضوئي (مصباح) يمثل الشمس مع محاكاة الدوران حول المحور وحول الشمس', 'النمذجة ثلاثية الأبعاد تنقل المتعلم من الإدراك الذاتي الخاطئ (حركة الشمس الظاهرية) إلى الفهم العلمي الحقيقي لدوران الأرض حول نفسها وحول الشمس.'),
('dsc160', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'في درس الدارة الكهربائية البسيطة، ما هو الخطأ الشائع لدى الأطفال حول انتقال التيار؟', '["تصور وجود تيار أحادي ينطلق من قطب واحد نحو المصباح ليستهلكه، دون إدراك ضرورة وجود دارة حلقية مغلقة ومكتملة","الاعتقاد بأن الأسلاك النحاسية مصنوعة من البلاستيك","تصور أن المصباح يضيء بدون بطارية دائماً","الاعتقاد بأن القاطع الكهربائي هو مصدر الطاقة الرئيسي"]'::jsonb, 'تصور وجود تيار أحادي ينطلق من قطب واحد نحو المصباح ليستهلكه، دون إدراك ضرورة وجود دارة حلقية مغلقة ومكتملة', 'نموذج التيار أحادي السلك هو تمثل شائع جداً، ويعالج بجعل التلميذ يركب الدارة بنفسه ويرى انطفاء المصباح بمجرد فتح أي جزء من الحلقة.'),
('dsc161', ARRAY['primary'], 'dsc', 'التدبير الديداكتيكي للنشاط العلمي', 'ما هي قواعد السلامة والأمان الأساسية الواجب اتباعها في ورشات التجارب بالابتدائي؟', '["تجنب المواد الكيميائية الخطرة والسامة، عدم تذوق أو شم المحاليل، والحذر عند استخدام مصادر الحرارة والزجاج","ترك التلاميذ يخلطون المواد الكيميائية المجهولة بحرية تامة","استعمال تيار المنازل 220 فولت مباشرة في التجارب البسيطة","منع التلاميذ من ارتداء القفازات أو غسل أيديهم بعد النشاط"]'::jsonb, 'تجنب المواد الكيميائية الخطرة والسامة، عدم تذوق أو شم المحاليل، والحذر عند استخدام مصادر الحرارة والزجاج', 'السلامة المدرسية تلزم المدرس باستعمال بطاريات ذات توتر منخفض جداً (4.5V) ومواد مألوفة آمنة وتأطير جميع العمليات بدقة.'),
('dsc162', ARRAY['primary'], 'dsc', 'علوم الحياة', 'كيف يُقدَّم مفهوم «التكيف لدى الكائنات الحية» في السلك الابتدائي؟', '["من خلال دراسة خصائص مورفولوجية وسلوكية لأعضاء حيوانات ونباتات تمكنها من العيش في بيئات محددة (كالصحراء أو الماء)","بافتراض أن الحيوانات تختار لونها بإرادتها الواعية في كل صباح","بالقول إن الكائنات الحية كلها متشابهة في بيئاتها وطريقة تغذيتها","بدراسة الطفرات الوراثية على المستوى الجزيئي للحمض النووي"]'::jsonb, 'من خلال دراسة خصائص مورفولوجية وسلوكية لأعضاء حيوانات ونباتات تمكنها من العيش في بيئات محددة (كالصحراء أو الماء)', 'ربط شكل المنقار بنوع الغذاء، أو زعانف الأسماك بالسباحة، أو سنام الجمل بتخزين الدهون، يقدم المفهوم بشكل حي ومشاهد.'),
('dsc163', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ماذا يقصد بـ «عزل المتغيرات» (Contrôle des variables) أثناء تصميم تجربة علمية؟', '["تغيير عامل تجريبي واحد فقط قيد الدراسة وتثبيت سائر العوامل الأخرى للتأكد من مصدر النتيجة","تغيير جميع الظروف والعوامل معاً في نفس الوقت بصورة عشوائية","حبس التلميذ الذي يطرح أسئلة كثيرة في غرفة معزولة","استعمال أدوات تجريبية مكسورة لإثبات صحة الفرضية"]'::jsonb, 'تغيير عامل تجريبي واحد فقط قيد الدراسة وتثبيت سائر العوامل الأخرى للتأكد من مصدر النتيجة', 'عزل المتغيرات شرط الصرامة العلمية (مثلاً لاختبار أثر الضوء على نمو النبتة: نثبت الماء والتربة والحرارة ونغير الضوء فقط في تجربتي الشاهد والمختبر).'),
('dsc164', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما هو الفارق الديداكتيكي بين «الذوبان» (Dissolution) و«الانصهار» (Fusion) لتجنب خلط المفاهيم؟', '["الذوبان يتطلب وجود مذيب ومذاب (مثل ذوبان السكر في الماء)، بينما الانصهار تحول حالة صلبة إلى سائلة بفعل الحرارة دون سائل مذيب (مثل انصهار الجليد)","الذوبان يخص المعادن فقط والانصهار يخص الغازات فقط","الذوبان والانصهار مصطلحان متطابقان تماماً يعبران عن نفس الشيء","الانصهار يحدث في الماء البارد والذوبان في النار"]'::jsonb, 'الذوبان يتطلب وجود مذيب ومذاب (مثل ذوبان السكر في الماء)، بينما الانصهار تحول حالة صلبة إلى سائلة بفعل الحرارة دون سائل مذيب (مثل انصهار الجليد)', 'الخلط اللغوي الدارج (مثل قول: ذاب الجليد) يعالج ديداكتيكياً بالتجربة المقارنة: تسخين شمعة (انصهار) مقابل وضع ملح في ماء (ذوبان).'),
('dsc165', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هو دور «التجربة الشاهدة» (Expérience témoin) في نهج التقصي العلمي؟', '["مرجع للمقارنة يثبت بشكل قاطع أن المتغير المدروس هو الفاعل الحقيقي في ظهور النتيجة دون غيره","تجربة يشاهدها التلاميذ عبر شاشة التلفاز فقط دون لمس الأدوات","تجربة فاشلة يعاقب عليها الأستاذ بوضع نقطة الصفر","تجربة يؤديها تلميذ واحد متفوق أمام المفتش"]'::jsonb, 'مرجع للمقارنة يثبت بشكل قاطع أن المتغير المدروس هو الفاعل الحقيقي في ظهور النتيجة دون غيره', 'التجربة الشاهدة تمثل الركيزة المنهجية التي تمنح المصداقية للاستدلال العلمي وتستبعد الصدفة والتفسيرات البديلة.'),
('dsc166', ARRAY['primary'], 'dsc', 'التكنولوجيا والتصميم', 'ما هو الهدف من إدراج مشاريع «التصميم والتكنولوجيا» (STEM) في برنامج النشاط العلمي؟', '["تطبيق المعارف العلمية في حل مشكلات عملية عبر تصميم ونمذجة وصنع أدوات وأجهزة بسيطة (سيارة شراعية، مقياس مطر، مجسم رئة)","تدريب التلاميذ على تفكيك الأجهزة المنزلية الثمينة في البيت","شغل حصص العلوم بالأشغال اليدوية الترفيهية دون سند معرفي","إلغاء تعلم القراءة والكتابة والرياضيات"]'::jsonb, 'تطبيق المعارف العلمية في حل مشكلات عملية عبر تصميم ونمذجة وصنع أدوات وأجهزة بسيطة (سيارة شراعية، مقياس مطر، مجسم رئة)', 'المشاريع التكنولوجية تجسد مبادئ الهندسة والتصميم وتنمي الابتكار والتعلم الإدماجي عبر الربط بين العلم والتطبيق الحياتي.'),
('dsc167', ARRAY['primary'], 'dsc', 'علوم الحياة', 'كيف يدرس مفهوم «التنفس لدى الكائنات الحية» في بيئاتها المختلفة (هوائية ومائية)؟', '["بالمقارنة بين التنفس الرئوي والتنفس الغلصمي والجلدي، وملاحظة حركات الأسماك وتبادل الغازات التنفسية","بالقول إن الأسماك تتنفس الماء نفسه كغذاء وليس الأكسجين المذاب","بمنع مقارنة الإنسان بالحيوانات في أي خاصية فيزيولوجية","بحفظ أسماء الأعصاب الدقيقة في الدماغ فقط"]'::jsonb, 'بالمقارنة بين التنفس الرئوي والتنفس الغلصمي والجلدي، وملاحظة حركات الأسماك وتبادل الغازات التنفسية', 'الملاحظة العيانية لحركة الغلاصم وماء الجير وتجارب التبادل الغازي ترسخ مفهوم التنفس كامتصاص للأكسجين وطرح لثنائي أكسيد الكربون.'),
('dsc168', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما دلالة «الرسم التخطيطي العلمي» (Schéma scientifique) ومواصفاته الديداكتيكية بالابتدائي؟', '["تمثيل مبسط وواضح للتجربة أو العضو، يعتمد خطوطاً دقيقة، ومفتاحاً وعنواناً وأسهماً تشير إلى البيانات بدقة","لوحة زيتية مليئة بالظلال الفنية المعقدة دون أسماء بيانات","رسم حر عشوائي بالأصابع على دفاتر التسويد","صورة فوتوغرافية تؤخذ بالهاتف وتلصق في الكراسة"]'::jsonb, 'تمثيل مبسط وواضح للتجربة أو العضو، يعتمد خطوطاً دقيقة، ومفتاحاً وعنواناً وأسهماً تشير إلى البيانات بدقة', 'الرسم التخطيطي العلمي ليس رسماً فنياً تعبيرياً، بل أداة تواصل علمي مقننة تجرد الظاهرة إلى خطوط وأسماء وظيفية دالة.'),
('dsc169', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يتم استكشاف قانون «الروافع والتوازن» ديداكتيكياً في السنة الخامسة أو السادسة؟', '["باستعمال مسطرة ترتكز على محور، وكتل مختلفة توضع على مسافات متباينة لاكتشاف علاقة التوازن بين القوة وذراعها","بحفظ قوانين العزوم الرياضية المعقدة نظرياً دون تجريب","بجعل التلاميذ يتدافعون بالأيدي في الساحة","برسم ميزان قديم غير دقيق على السبورة فقط"]'::jsonb, 'باستعمال مسطرة ترتكز على محور، وكتل مختلفة توضع على مسافات متباينة لاكتشاف علاقة التوازن بين القوة وذراعها', 'التجريب باللعب (الأرجوحة، الروافع البسيطة) يتيح للتلميذ استنتاج أن زيادة البعد عن المحور تقلل من الجهد اللازم لرفع الثقل.'),
('dsc170', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'ما هو المدخل المعتمد لتدريس «دورة الماء في الطبيعة» بالابتدائي؟', '["ربط تحولات حالات المادة (تبخر، تكاثف، تساقط، جريان وتجمد) بنموذج تفاعلي يحاكي أثر حرارة الشمس والرياح في دورة مغلقة","القول إن مياه الأمطار تأتي من الفضاء الخارجي في نيازك جليدية كل يوم","شرب كميات كبيرة من الماء في الفصل","حفظ أسماء محطات تصفية المياه العادمة بالمدن الكبرى"]'::jsonb, 'ربط تحولات حالات المادة (تبخر، تكاثف، تساقط، جريان وتجمد) بنموذج تفاعلي يحاكي أثر حرارة الشمس والرياح في دورة مغلقة', 'تجارب التبخير والتكثيف على غطاء بارد داخل القسم تشكل نموذجاً مصغراً يفسر تشكل السحب وتساقط الأمطار وجريان الأنهار.'),
('dsc171', ARRAY['primary'], 'dsc', 'التربية الصحية والبيئية', 'ما الهدف التربوي من إدراج محور «السلوك الغذائي السليم والوقاية من الأمراض» في النشاط العلمي؟', '["بناء مواقف وقيم صحية واعية ترتكز على المعرفة البيولوجية (التغذية المتوازنة، النظافة، والنشاط البدني) لحماية الجسم","فرض حمية غذائية قاسية على جميع تلاميذ المدرسة","تحويل قاعة الدرس إلى صيدلية لبيع الأدوية","الاستغناء عن وجبات الطعام المنزلية"]'::jsonb, 'بناء مواقف وقيم صحية واعية ترتكز على المعرفة البيولوجية (التغذية المتوازنة، النظافة، والنشاط البدني) لحماية الجسم', 'تستهدف التربية الصحية تعديل السلوكيات وتوعية الناشئة بأهمية المجموعات الغذائية والوقاية من السمنة وسوء التغذية والجراثيم.'),
('dsc172', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هو الموقف الإيجابي للأستاذ تجاه «الفرضية الخاطئة» التي يقترحها المتعلم في بداية الحصة؟', '["قبولها وتسجيلها في سبورة الفرضيات لاختبارها وتفنيدها عبر التجريب العلمي، مما يبني التفكير النقدي","السخرية من التلميذ وطرده خارج القسم","مسح الفرضية فوراً وكتابة الجواب الصحيح فقط","خصم علامات من نقطة المراقبة المستمرة للتلميذ"]'::jsonb, 'قبولها وتسجيلها في سبورة الفرضيات لاختبارها وتفنيدها عبر التجريب العلمي، مما يبني التفكير النقدي', 'الفرضية غير الصحيحة هي فرصة ديداكتيكية ثمينة؛ إذ يتعلم التلميذ من خطئه حين تكشف التجربة عدم مطابقتها للواقع.'),
('dsc173', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يفسر ديداكتيكياً مفهوم «الطفو والانغمار» في الماء بالسلك الابتدائي؟', '["بالمقارنة بين كتل وحجوم الأجسام ومفهوم الكثافة النوعية والكتلة الحجمية بالنسبة للماء وليس بالوزن وحده","بالقول إن الأجسام الكبيرة تغرق دائماً والأجسام الصغيرة تطفو دائماً","بالاعتماد على لون الجسم وبريقه الخارجي","بادعاء أن الأجسام تطفو في الليل فقط وتغرق في النهار"]'::jsonb, 'بالمقارنة بين كتل وحجوم الأجسام ومفهوم الكثافة النوعية والكتلة الحجمية بالنسبة للماء وليس بالوزن وحده', 'تفكيك عائق (الثقيل يغرق والخفيف يطفو) يتم بتجربة مقارنة قطعة خشب ضخمة تطفو وإبرة حديدية صغيرة تغرق، لإدراك مفهوم الكثافة.'),
('dsc174', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما المعين الديداكتيكي الأساسي لتتبع ظاهرة «إنبات البذور» ونمو النباتات؟', '["إجراء تجارب إنبات حية في الفصل (بذور فاصوليا وعدس في قطن مبلل) مع تغيير شروط الضوء والماء وتسجيل النتائج يومياً","حفظ نص وصفي للإنبات دون رؤية أي بذرة حقيقية","شراء نبتة بلاستيكية ووضعها فوق مكتب المدير","رسم البذرة على اللوح ومسحها بسرعة"]'::jsonb, 'إجراء تجارب إنبات حية في الفصل (بذور فاصوليا وعدس في قطن مبلل) مع تغيير شروط الضوء والماء وتسجيل النتائج يومياً', 'التتبع اليومي للإنبات والقياس بالمسطرة وتدوين الملاحظات في كراسة التقصي يجسد الملاحظة العلمية المستمرة ودور العوامل البيئية.'),
('dsc175', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'ما الهدف الديداكتيكي من دراسة «الطقس والمناخ» في برنامج النشاط العلمي؟', '["التعرف على عناصر الطقس (الحرارة، الرياح، التساقطات، والضغط) واستعمال أدوات القياس البسيطة (محرار، أنيمومتر، ومرياح)","توقع الزلازل الأرضية بدقة قبل حدوثها بعام كامل","إلزام التلاميذ بتقديم النشرة الجوية في التلفاز الرسمي","دراسة التركيب الكيميائي لنيازك كوكب المريخ فقط"]'::jsonb, 'التعرف على عناصر الطقس (الحرارة، الرياح، التساقطات، والضغط) واستعمال أدوات القياس البسيطة (محرار، أنيمومتر، ومرياح)', 'المحاكاة وصنع أدوات قياس الطقس البسيطة يمنحان المتعلم وعياً علمياً بالتقلبات الجوية وتغيرات المناخ في محيطه القريب.'),
('dsc176', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما هو التصور الخاطئ الشائع حول «الظل والضوء» لدى تلاميذ المستوى الابتدائي؟', '["اعتبار الظل مادة تنبعث من الجسم نفسه أو كياناً مستقلاً يتحرك بحرية دون إدراك أنه ناتج عن حجب مسار الضوء المستقيم","معرفة أن الضوء ينتشر في خطوط مستقيمة","إدراك أن مصدر الضوء يحدد موضع وطول الظل","التفريق بين الأجسام المعتمة والأجسام الشفافة"]'::jsonb, 'اعتبار الظل مادة تنبعث من الجسم نفسه أو كياناً مستقلاً يتحرك بحرية دون إدراك أنه ناتج عن حجب مسار الضوء المستقيم', 'أثبتت بحوث الديداكتيك أن الأطفال يعتقدون أن الظل رفيق أو سائل مادي، ويعالج ذلك بتجارب الحجب وتسليط منابع ضوئية مختلفة الاتجاه.'),
('dsc177', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي صيغة العمل الصفية الأنسب لتنفيذ أنشطة التقصي والتجريب العلمي؟', '["العمل في مجموعات بؤرية صغيرة مع توزيع المهام (مسير، كاتب، مناول تجريبي، ومقرر ناطق)","الإلقاء الفردي الصامت من طرف الأستاذ فقط دون مشاركة التلاميذ","جلوس كل تلميذ وحيداً معزولاً عن سائر الزملاء","ترك الفصل في فوضى عارمة دون أي تنظيم أو مهام"]'::jsonb, 'العمل في مجموعات بؤرية صغيرة مع توزيع المهام (مسير، كاتب، مناول تجريبي، ومقرر ناطق)', 'العمل الجماعي التعاوني ينمي التفاعل الاجتماعي ويعزز الصراع السوسيو-معرفي ويدرب على تقاسم المسؤوليات وتكامل الأدوار.'),
('dsc178', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يُميز المتعلم ديداكتيكياً بين «الخليط المتجانس» و«الخليط غير المتجانس»؟', '["الخليط غير المتجانس يمكن تمييز مكوناته بالعين المجردة (ماء وزيت)، بينما المتجانس لا يمكن تمييز مكوناته (ماء وسكر مذاب)","الخليط المتجانس يوجد في الصيدليات فقط والآخر في الغابة فقط","الخليط المتجانس لونه أحمر دائماً والخليط غير المتجانس لونه أزرق","لا يوجد أي فرق بينهما فجميع السوائل متجانسة بالضرورة"]'::jsonb, 'الخليط غير المتجانس يمكن تمييز مكوناته بالعين المجردة (ماء وزيت)، بينما المتجانس لا يمكن تمييز مكوناته (ماء وسكر مذاب)', 'المعاينة العينية واستعمال تقنيات الفصل المادي (التصفيق والترشيح) ترسخ الفرق بين الخلائط المتجانسة وغير المتجانسة بدقة.'),
('dsc179', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما هو المحور الديداكتيكي لدراسة «أنماط التوالد لدى الحيوانات» (ولود / بيوض)؟', '["تصنيف الحيوانات حسب نمط التكاثر وملاحظة مراحل دورات الحياة ورعاية الصغار وتغيرات النمو","حفظ تشريح الجهاز التناسلي المجهري للثدييات بالتفصيل الأكاديمي","القول إن جميع الكائنات الحية تضع بيوضاً في فصل الشتاء","حذف الموضوع تماماً وتجنب الحديث عنه في المدرسة"]'::jsonb, 'تصنيف الحيوانات حسب نمط التكاثر وملاحظة مراحل دورات الحياة ورعاية الصغار وتغيرات النمو', 'تتبع دورة حياة الضفدع أو الدجاجة أو الفراشة عبر بطاقات وصور متسلسلة يبرز تعاقب الأجيال واستمرار النوع الحي.'),
('dsc180', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما دلالة «التحليل والمناقشة» في ختام مرحلة الاختبار والتجريب في النشاط العلمي؟', '["مقارنة النتائج المحصل عليها بالفرضيات الأولية لتأكيد صحتها أو دحضها واستخلاص الاستنتاجات العلمية","تبادل الاتهامات بين التلاميذ حول من كسر الأدوات التجريبية","الخروج فوراً للاستراحة دون تدوين أي نتيجة","كتابة نص إنشائي أدبي عن مشاعر التلميذ نحو الطبيعة"]'::jsonb, 'مقارنة النتائج المحصل عليها بالفرضيات الأولية لتأكيد صحتها أو دحضها واستخلاص الاستنتاجات العلمية', 'المناقشة الجماعية الموجهة هي التي تحول الملاحظات التجريبية الخام إلى معرفة علمية مؤسسة تبرر تأكيد أو نفي الفرضيات.'),
('dsc181', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما هي وظيفة استخدام «الدينامومتر» (Dynamomètre) في تجارب القوى بالابتدائي؟', '["قياس شدة القوة ووحدتها (النيوتن N) وإبراز علاقة استطالة النابض بالثقل المعلق به","قياس درجة حرارة السوائل المغلية","قياس حجم الهواء داخل الغرفة","معرفة اتجاه الرياح الشمالية"]'::jsonb, 'قياس شدة القوة ووحدتها (النيوتن N) وإبراز علاقة استطالة النابض بالثقل المعلق به', 'الدينامومتر جهاز عيني يترجم مفهوم القوة غير المرئي إلى استطالة مرئية على سلم مدرج يحدد شدتها بوحدة النيوتن.'),
('dsc182', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'كيف يساهم درس «حماية التربة والمحافظة على البيئة» في تنمية الحس المدني والبيئي؟', '["بتوعية المتعلم بأهمية الغطاء النباتي في الحد من انجراف التربة ومخاطر التلوث والتصحر وتبني ممارسات مستدامة (التشجير، التدوير)","بتشجيع رمي النفايات في المجاري المائية القريبة","بقطع أشجار الغابات لصنع أوراق الدفاتر","باعتبار البيئة شأناً يخص الدول الغربية فقط"]'::jsonb, 'بتوعية المتعلم بأهمية الغطاء النباتي في الحد من انجراف التربة ومخاطر التلوث والتصحر وتبني ممارسات مستدامة (التشجير، التدوير)', 'يربط النشاط العلمي المعرفة الجيولوجية بالمواطنة البيئية عبر مشاريع غرس النباتات وفرز النفايات المدرسية لترسيخ السلوك البيئي المسؤول.'),
('dsc183', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'في درس المغانط (Les aimants)، ما الذي يكتشفه المتعلم تجريبياً حول قطبي المغناطيس؟', '["أن للمغناطيس قطبين (شمالي وجنوبي)؛ القطبان المتماثلان يتنافران والقطبان المختلفان يتجاذبان","أن المغناطيس يجذب جميع المواد كالبلاستيك والخشب والزجاج","أن المغناطيس يعمل بالكهرباء والبطارية فقط","أن للمغناطيس قطباً واحداً فقط في جميع الحالات"]'::jsonb, 'أن للمغناطيس قطبين (شمالي وجنوبي)؛ القطبان المتماثلان يتنافران والقطبان المختلفان يتجاذبان', 'المناولة الحركية للمغانط تبرز خاصية التجاذب والتنافر والتمييز بين المعادن المغناطيسية (كالحديد والنيكل) والمعادن غير المنجذبة كالنحاس والألومنيوم.'),
('dsc184', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما المقصود بـ «النهج التاريخي» (Approche historique) في تدريس النشاط العلمي؟', '["استحضار السياق التاريخي للاكتشافات العلمية الكبرى وتجارب العلماء ليدرك المتعلم أن العلم بناء بشري متطور وليس حقيقة جامدة","حفظ تواريخ معارك الحروب العالمية في حصة العلوم","إلغاء التجارب المخبرية والاكتفاء بكتب التاريخ القديمة","منع استخدام الأدوات التكنولوجية الحديثة في القسم"]'::jsonb, 'استحضار السياق التاريخي للاكتشافات العلمية الكبرى وتجارب العلماء ليدرك المتعلم أن العلم بناء بشري متطور وليس حقيقة جامدة', 'تاريخ العلوم يضفي بعداً إنسانياً وفلسفياً على المادة، ويوضح للمتعلم كيف تطورت النظريات وتجاوزت أخطاء القرون السابقة.'),
('dsc185', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما هو المدخل الديداكتيكي لدراسة «الحواس الخمس» في المستويات الأولى؟', '["أنشطة استكشافية وتذوقية ولمسية آمنة تميز بين وظائف الأعضاء الحسية والمنبهات الخارجية في البيئة المحيطة","حفظ المسارات العصبية للدماغ في الطور الجنيني","قراءة نصوص صامتة دون أي تنشيط للحواس","منع الأطفال من لمس الأشياء أو النظر إلى الأشكال"]'::jsonb, 'أنشطة استكشافية وتذوقية ولمسية آمنة تميز بين وظائف الأعضاء الحسية والمنبهات الخارجية في البيئة المحيطة', 'يعتمد التعلم على الإدراك الحسي المباشر (صناديق اللمس، ألعاب الشم، التمييز السمعي) لاكتشاف دور الحواس في استكشاف العالم.'),
('dsc186', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يبرهن المتعلم في النشاط العلمي على أن «الصوت ينتشر عبر الأوساط المادية»؟', '["بإجراء تجارب انتشار الصوت عبر الهواء والمواد الصلبة (هاتف الخيط والعلب، سماع الصوت عبر الطاولة) وانعدامه في الفراغ","بالصراخ بصوت مرتفع دون أي وسيط تجريبي","بالقول إن الصوت ينتقل في الفراغ المطلق أسرع من الضوء","بقراءة كتاب الفيزياء في غرفة مظلمة"]'::jsonb, 'بإجراء تجارب انتشار الصوت عبر الهواء والمواد الصلبة (هاتف الخيط والعلب، سماع الصوت عبر الطاولة) وانعدامه في الفراغ', 'صنع الهاتف البسيط بالخيط والكؤوس يثبت أن الصوت موجة ميكانيكية تتطلب وسيطاً مادياً (صلباً أو غازياً أو سائلاً) للانتشار.'),
('dsc187', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'ما هو التفسير العلمي المبسط لظاهرة «المد والجزر» المقدم لتلاميذ الابتدائي؟', '["حركة دورية لمياه البحر ناتجة عن قوة التجاذب بين الأرض والقمر (والشمس) مع دوران الأرض","تنفس وحش بحري عملاق في قاع المحيط","تساقط الأمطار الغزيرة فوق مياه المحيط فجأة ثم توقفها","سفن شحن عملاقة تدفع المياه نحو الشواطئ"]'::jsonb, 'حركة دورية لمياه البحر ناتجة عن قوة التجاذب بين الأرض والقمر (والشمس) مع دوران الأرض', 'يربط المفهوم بين قوى الجاذبية الكونية وحركة المسطحات المائية البحرية، موضحاً انتظام الظاهرة في تعاقب زمني دقيق.'),
('dsc188', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي المعايير المعتمدة لتقويم إنجاز تجريبي لتلميذ في حصة النشاط العلمي؟', '["احترام شروط السلامة، الدقة في استخدام الأدوات، دقة الملاحظة وتسجيل القياسات، وسلامة الاستدلال العلمي والنتائج","سرعة التلميذ في الجري داخل المختبر","تلوين كراسة النشاط العلمي بالألوان الزيتية فقط","عدم ارتكاب أي خطأ إملائي في اللغة اللاتينية"]'::jsonb, 'احترام شروط السلامة، الدقة في استخدام الأدوات، دقة الملاحظة وتسجيل القياسات، وسلامة الاستدلال العلمي والنتائج', 'التقويم في النشاط العلمي يركز على المهارات الإجرائية (Savoir-faire) ومواقف البحث العلمي الرصين والتفكير المنطقي.'),
('dsc189', ARRAY['primary'], 'dsc', 'علوم الحياة', 'كيف تُقدَّم «العلاقات التفاعلية بين الكائنات الحية» (الافتراس، التنافس، والتعايش/التطفل)؟', '["من خلال وثائق مصورة ومقاطع فيديو توثيقية ترصد سلوك الحيوانات في مواطنها الطبيعية وتحليل أثر كل علاقة على بقاء النوع","بحبس حيوانات مفترسة داخل حجرة الدرس لتجريب سلوكها","بالقول إن الحيوانات كلها أصدقاء ولا يوجد أي افتراس في الغابة","بحفظ الأوزان الدقيقة للأسود والنمور في أقفاص حديقة الحيوان"]'::jsonb, 'من خلال وثائق مصورة ومقاطع فيديو توثيقية ترصد سلوك الحيوانات في مواطنها الطبيعية وتحليل أثر كل علاقة على بقاء النوع', 'الاستناد إلى الدعامات التوثيقية والوسائط المتعددة يقرب الواقع البيئي للمتعلم دون تعريضه لأي خطر، ويوضح التوازن البيئي الطبيعي.'),
('dsc190', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما هو النشاط التجريبي المناسب لبيان خاصية «انضغاط وتوسع الغازات»؟', '["سحب ودفع مكبس محقنة طبية مغلقة الفوهة بالإصبع لمعاينة تغير حجم الهواء المحصور بتغير الضغط الممارس","سكب الماء في إناء مفتوح دون غطاء","وزن قطعة حجر جافة بميزان ذي كفتين","تسخين قطعة سكر حتى تتحول إلى كراميل"]'::jsonb, 'سحب ودفع مكبس محقنة طبية مغلقة الفوهة بالإصبع لمعاينة تغير حجم الهواء المحصور بتغير الضغط الممارس', 'تجربة المحقنة تجسد عيانياً وميكانيكياً خاصيتي الانضغاط (نقصان الحجم) والتوسع (ازدياد الحجم) المميزتين للمادة في الحالة الغازية.'),
('dsc191', ARRAY['primary'], 'dsc', 'علوم الأرض والفضاء', 'كيف يُميز التلميذ في النشاط العلمي بين «الصخور والمعادن» والمستحثات؟', '["بفحص عينات صخرية محلية بمكبرة يدوية، واختبار الصلادة والتفاعل مع حمض الليمون (الخل) وملاحظة آثار وبقايا الكائنات الحية القديمة","بتذوق طعم الصخور بألسنتهم في القسم","بقراءة قصة خيالية عن مناجم الذهب في كوكب زحل","باعتبار جميع الصخور كائنات حية تتنفس وتتوالد"]'::jsonb, 'بفحص عينات صخرية محلية بمكبرة يدوية، واختبار الصلادة والتفاعل مع حمض الليمون (الخل) وملاحظة آثار وبقايا الكائنات الحية القديمة', 'المناولة الجيولوجية البسيطة (ملاحظة البلورات، الخدش، واختبار الفوران بالخل للصخور الكلسية) تدرب التلميذ على معايير التصنيف العلمي.'),
('dsc192', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'ما دلالة استثمار «الطاقات المتجددة» (الشمسية، الريحية، والكهرومائية) في النشاط العلمي؟', '["ترسيخ الوعي بالانتقال الطاقي واستدامة الموارد النظيفة مقارنة بالطاقات الأحفورية الملوثة عبر نماذج ومشاريع مصغرة (فرن شمسي، عنفة ريحية)","إلغاء استعمال الكهرباء في المنازل والمدارس تماماً","مطالبة التلاميذ بإنتاج النفط في ساحة المؤسسة","حفظ المعادلات النووية المعقدة لتوليد الكهرباء"]'::jsonb, 'ترسيخ الوعي بالانتقال الطاقي واستدامة الموارد النظيفة مقارنة بالطاقات الأحفورية الملوثة عبر نماذج ومشاريع مصغرة (فرن شمسي، عنفة ريحية)', 'صنع مجسمات مبسطة للعنفات والأفران الشمسية يربط المفهوم الفيزيائي لتوليد الطاقة بالرهانات البيئية والتنموية لبلادنا.'),
('dsc193', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما هو العائق الشائع عند الأطفال حول مفهوم «النبات ككائن حي»؟', '["حصر صفة الكائن الحي في الحيوانات القادرة على الحركة الإرادية والصوت، واستبعاد النبات لثباته وسكونه الظاهري","معرفة أن النباتات تحتاج إلى الماء والأملاح المعدنية","الاعتراف بأن النبات ينمو ويموت ويثمر","التفريق بين الأشجار والأعشاب الصغيرة"]'::jsonb, 'حصر صفة الكائن الحي في الحيوانات القادرة على الحركة الإرادية والصوت، واستبعاد النبات لثباته وسكونه الظاهري', 'يعالج هذا العائق بتتبع دورة نمو النبات وتنفسه وحركته البطيئة نحو الضوء (الانتحاء الضوئي Phototropisme) لإثبات خصائص الحياة لديه.'),
('dsc194', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما هي القيمة التربوية لـ «المحاكاة الرقمية والبرانم التفاعلية» في تدريس النشاط العلمي؟', '["تمكين المتعلم من استكشاف ظواهر يصعب أو يستحيل تجريبها واقعياً في حجرة الدرس لخطورتها أو طول مدتها أو صغرها الشديد","استبدال الأستاذ بروبوت آلي وإلغاء المدرسة","قضاء وقت الحصة في ممارسة ألعاب الفيديو التجارية العنيفة","منع التلاميذ من التفكير وحفظ الصور الرقمية فقط"]'::jsonb, 'تمكين المتعلم من استكشاف ظواهر يصعب أو يستحيل تجريبها واقعياً في حجرة الدرس لخطورتها أو طول مدتها أو صغرها الشديد', 'تعد المحاكاة الحاسوبية (Simulations) معياراً تكنولوجياً فعالاً لمعاينة مدارات الكواكب، الدارة الكهربائية المنزلية، وتفاعلات الانقسام الخلوي بأمان.'),
('dsc195', ARRAY['primary'], 'dsc', 'العلوم الفيزيائية', 'كيف يُميز المتعلم بين «الكتلة» و«الوزن» في المستوى الابتدائي السادس؟', '["الكتلة مقدار ثابت يعبر عن كمية المادة في الجسم وتقاس بالميزان بالكيلوغرام، بينما الوزن قوة جذب الأرض للجسم ويقاس بالدينامومتر بالنيوتن ويتغير بتغير المكان","الكتلة والوزن هما شيء واحد دون أي اختلاف علمي أو عملي","الكتلة تقاس بالدينامومتر والوزن يقاس بميزان الحرارة","الوزن ثابت دائماً في كل الكواكب والكتلة تتلاشى في الفضاء"]'::jsonb, 'الكتلة مقدار ثابت يعبر عن كمية المادة في الجسم وتقاس بالميزان بالكيلوغرام، بينما الوزن قوة جذب الأرض للجسم ويقاس بالدينامومتر بالنيوتن ويتغير بتغير المكان', 'التمييز بين P و m من المكتسبات المفصلية التي تعالج الخلط الدارج ببيان أن رواد الفضاء على القمر تتغير أوزانهم وتبقى كتلهم محفوظة.'),
('dsc196', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما أهمية مرحلة «تقاسم النتائج والتواصل» (Communication) بين مجموعات القسم؟', '["تدريب المتعلمين على التعبير العلمي الدقيق، والاستماع للرأي الآخر، والدفاع عن النتائج بالحجج التجريبية المقنعة","إحراج المجموعات التي ارتكبت أخطاء في القياس","إضاعة الوقت قبل رن جرس نهاية الحصة","نقل نتائج المجموعة الأولى دون فحص أو مناقشة"]'::jsonb, 'تدريب المتعلمين على التعبير العلمي الدقيق، والاستماع للرأي الآخر، والدفاع عن النتائج بالحجج التجريبية المقنعة', 'مرحلة المقاسمة تعكس المؤتمرات العلمية الحقيقية حيث يعرض الباحثون نتائجهم للمراجعة والنقد البناء والتحقق المتبادل.'),
('dsc197', ARRAY['primary'], 'dsc', 'علوم الحياة', 'ما هو المحور الديداكتيكي لدراسة «الحركات والمفاصل والجهاز العضلي العظمي» لدى الإنسان؟', '["صنع مجسمات تحاكي عمل العضلات المتقابلة (الباسطة والقابضة) والمفاصل لتفسير ثني وبسط الأطراف حركياً وعيانياً","حفظ جميع أسماء العظام اللاتينية الـ 206 بالترتيب الدقيق","كسر عظام الحيوانات في المختبر لفحص نخاع العظم","القول إن حركة الجسم تتم بواسطة الأعصاب فقط دون عضلات"]'::jsonb, 'صنع مجسمات تحاكي عمل العضلات المتقابلة (الباسطة والقابضة) والمفاصل لتفسير ثني وبسط الأطراف حركياً وعيانياً', 'استخدام الورق المقوى والمطاط والمشابك لصنع ذراع متحركة يجسد عمل العضلة كثنائية متقابلة تسحب العظم عبر المفصل.'),
('dsc198', ARRAY['primary'], 'dsc', 'التربية الصحية والبيئية', 'كيف يتناول درس النشاط العلمي موضوع «المخاطر الطبيعية» (الزلازل والبراكين والفيضانات)؟', '["تفسير أسباب الظواهر الجيولوجية ومظاهرها وتدريب المتعلمين على سلوكيات الحماية الذاتية وإجراءات الطوارئ الآمنة عند وقوعها","ترهيب الأطفال وإثارة الفزع الدائم في نفوسهم","القول إن الزلازل تحدث بسبب تحرك سلحفاة ضخمة تحت الأرض","تجاهل الموضوع تماماً لعدم إخافة المتعلمين"]'::jsonb, 'تفسير أسباب الظواهر الجيولوجية ومظاهرها وتدريب المتعلمين على سلوكيات الحماية الذاتية وإجراءات الطوارئ الآمنة عند وقوعها', 'الهدف دمج البعد العلمي التفسيري (تكتونية الصفائح) بالبعد الوقائي التوعوي (محاكاة خطط الإخلاء والحماية تحت الطاولات الصلبة).'),
('dsc199', ARRAY['primary'], 'dsc', 'نهج التقصي العلمي', 'ما الذي يجب أن يفعله الأستاذ إذا لم تُسفر تجربة التقصي المقترحة عن النتيجة العلمية المتوقعة؟', '["استثمار النتيجة غير المتوقعة كفرصة للبحث، ومراجعة ظروف التجربة والأدوات المستخدمة لمعرفة مصدر الخلل بطريقة علمية نقدية","تزييف النتائج على السبورة وإجبار التلاميذ على كتابة نتيجة وهمية","عقاب تلاميذ المجموعة بالصراخ وإلقاء الأدوات في سلة المهملات","إنهاء الدرس فوراً والادعاء بأن العلم لا يصلح في هذه المدرسة"]'::jsonb, 'استثمار النتيجة غير المتوقعة كفرصة للبحث، ومراجعة ظروف التجربة والأدوات المستخدمة لمعرفة مصدر الخلل بطريقة علمية نقدية', 'الفشل التجريبي جزء أصيل من تاريخ العلم؛ ومساءلة المتغيرات والأدوات يعلم التلميذ المنهجية العلمية والنزاهة الفكرية.'),
('dsc200', ARRAY['primary'], 'dsc', 'ديداكتيك النشاط العلمي', 'ما هي الغاية التربوية الكبرى لتدريس مادة النشاط العلمي بالتعليم الابتدائي؟', '["تنمية الفكر العلمي النقدي، ترسيخ روح التقصي والملاحظة، وإكساب المتعلم كفايات فهم وتفسير الظواهر الطبيعية وحماية البيئة والصحة","حشو ذهن التلميذ بمعلومات ونظريات معقدة للحفظ الآلي فقط دون وعي","إعداد المتعلمين لامتحانات شفوية روتينية دون ممارسة عملية","فصل التلميذ عن بيئته ومحيطه الطبيعي المعاش"]'::jsonb, 'تنمية الفكر العلمي النقدي، ترسيخ روح التقصي والملاحظة، وإكساب المتعلم كفايات فهم وتفسير الظواهر الطبيعية وحماية البيئة والصحة', 'الهدف الأسمى بناء مواطن متسلح بروح علمية فضولية، قادر على الملاحظة وطرح الأسئلة والتجريب وحل مشكلات بيئته ومجتمعه بنزاهة وعقلانية.')
